 --bs-table-border-color: rgba(255,255,255,0.06);
 --bs-table-hover-bg: rgba(255,255,255,0.03);
 --bs-table-accent-bg: transparent;
 font-size: 0.82rem;
 margin-bottom: 0;
 color: var(--text-primary);
 }

 .param-table-wrap .table > :not(caption) > * > * {
 background-color: transparent !important;
 box-shadow: none !important;
 color: var(--text-primary) !important;
 }

 .param-table-wrap .table thead th {
 background-color: rgba(255,255,255,0.03) !important;
 color: var(--text-muted) !important;
 font-weight: 600;
 font-size: 0.68rem;
 text-transform: uppercase;
 letter-spacing: 0.06em;
 border-bottom: 1px solid var(--glass-border) !important;
 padding: 0.6rem 0.7rem;
 }

 .param-table-wrap .table td {
 border-bottom: 1px solid rgba(255,255,255,0.04) !important;
 padding: 0.55rem 0.45rem;
 vertical-align: middle;
 }

 .param-table-wrap .table tbody tr { transition: background-color 0.15s; }
 .param-table-wrap .table tbody tr:hover { background-color: rgba(255,255,255,0.025) !important; }

 /* Input + Select overrides — target Bootstrap's exact property names */
 .param-table-wrap .table .form-control,
 .param-table-wrap .table .form-select,
 .param-table-wrap .table .form-control.form-control-sm,
 .param-table-wrap .table .form-select.form-select-sm,
 .param-table-wrap .table td input.form-control,
 .param-table-wrap .table td select.form-select,
 .param-table-wrap .table td textarea.form-control {
 background-color: rgba(255,255,255,0.06) !important;
 border: 1px solid rgba(255,255,255,0.12) !important;
 color: #e2e8f0 !important;
 padding: 0.38rem 0.55rem !important;
 font-size: 0.82rem !important;
 border-radius: 6px !important;
 box-shadow: none !important;
 }

 .param-table-wrap .table td input.form-control::placeholder,
 .param-table-wrap .table td textarea.form-control::placeholder {
 color: #64748b !important;
 }

 .param-table-wrap .table td input.form-control:focus,
 .param-table-wrap .table td select.form-select:focus,
 .param-table-wrap .table td textarea.form-control:focus {
 background-color: rgba(99,102,241,0.1) !important;
 border-color: rgba(99,102,241,0.5) !important;
 box-shadow: 0 0 0 2px rgba(99,102,241,0.12) !important;
 color: #f1f5f9 !important;
 }

 .param-table-wrap .table td select.form-select {
 padding-right: 2rem !important;
 background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 16 16'%3e%3cpath fill='none' stroke='%2394a3b8' stroke-linecap='round' stroke-linejoin='round' stroke-width='2' d='m4 6 4 4 4-4'/%3e%3c/svg%3e") !important;
 background-repeat: no-repeat !important;
 background-position: right 0.5rem center !important;
 background-size: 14px 10px !important;
 }

 .btn-delete-param {
 width: 26px; height: 26px;
 border-radius: 6px;
 border: none;
 background: transparent;
 color: var(--text-muted);
 transition: var(--transition);
 display: flex;
 align-items: center;
 justify-content: center;
 padding: 0;
 }

 .btn-delete-param:hover { background: rgba(239,68,68,0.12); color: var(--red); }

 .btn-add-param {
 font-size: 0.76rem;
 font-weight: 600;
 padding: 0.38rem 0.75rem;
 border-radius: 8px;
 background: rgba(255,255,255,0.05);
 border: 1px dashed rgba(255,255,255,0.12);
 color: var(--text-secondary);
 transition: var(--transition);
 }

 .btn-add-param:hover {
 background: rgba(99,102,241,0.08);
 border-color: rgba(99,102,241,0.3);
 color: var(--accent-light);
 }

 .param-empty {
 text-align: center;
 padding: 2rem 1rem;
 color: var(--text-muted);
 font-size: 0.82rem;
 }

 .param-empty .empty-icon {
 width: 44px; height: 44px;
 border-radius: 12px;
 background: rgba(255,255,255,0.04);
 display: inline-flex;
 align-items: center;
 justify-content: center;
 margin-bottom: 0.65rem;
 }

 /* ===== TEST & PUBLISH (Step 4) ===== */
 .publish-zone {
 background: linear-gradient(135deg, rgba(99,102,241,0.05), rgba(139,92,246,0.03));
 border: 1px solid rgba(99,102,241,0.12);
 border-radius: var(--radius-lg);
 padding: 1.5rem;
 }

 .test-args-box {
 background: rgba(0,0,0,0.2);
 border: 1px solid var(--glass-border);
 border-radius: var(--radius);
 padding: 1.15rem;
 margin-bottom: 1.25rem;
 }

 .test-args-box h6 {
 font-size: 0.72rem;
 font-weight: 700;
 text-transform: uppercase;
 letter-spacing: 0.05em;
 color: var(--text-muted);
 margin-bottom: 0.9rem;
 }

 /* File picker for test args */
 .file-picker-wrap {
 position: relative;
 }

 .file-picker-wrap .form-control[type="file"] {
 padding: 0.4rem 0.6rem;
 font-size: 0.8rem;
 cursor: pointer;
 }

 .file-picker-wrap .form-control[type="file"]::file-selector-button {
 background: linear-gradient(135deg, var(--accent), #7c3aed);
 color: #fff;
 border: none;
 padding: 0.3rem 0.75rem;
 border-radius: 6px;
 font-size: 0.75rem;
 font-weight: 600;
 margin-right: 0.75rem;
 cursor: pointer;
 transition: var(--transition);
 }

 .file-picker-wrap .form-control[type="file"]::file-selector-button:hover {
 box-shadow: 0 2px 10px var(--accent-glow);
 }

 .file-picker-wrap .file-status {
 font-size: 0.7rem;
 margin-top: 0.3rem;
 display: flex;
 align-items: center;
 gap: 0.4rem;
 }

 .file-picker-wrap .file-status.uploading { color: var(--amber); }
 .file-picker-wrap .file-status.uploaded { color: var(--green); }
 .file-picker-wrap .file-status.error { color: var(--red); }

 .btn-test {
 background: rgba(255,255,255,0.08);
 border: 1px solid rgba(255,255,255,0.15);
 color: var(--text-primary);
 font-weight: 600;
 font-size: 0.82rem;
 padding: 0.55rem 1.2rem;
 border-radius: var(--radius);
 transition: var(--transition);
 }

 .btn-test:hover {
 background: rgba(255,255,255,0.12);
 color: #fff;
 transform: translateY(-1px);
 }

 .btn-save-draft {
 background: transparent;
 border: 1px solid var(--glass-border);
 color: var(--text-secondary);
 font-weight: 600;
 font-size: 0.82rem;
 padding: 0.55rem 1rem;
 border-radius: var(--radius);
 transition: var(--transition);
 }

 .btn-save-draft:hover {
 border-color: rgba(255,255,255,0.18);
 background: rgba(255,255,255,0.04);
 color: var(--text-primary);
 }

 .btn-publish-live {
 background: linear-gradient(135deg, var(--green), #16a34a);
 border: none;
 color: #fff;
 font-weight: 600;
 font-size: 0.82rem;
 padding: 0.55rem 1.2rem;
 border-radius: var(--radius);
 transition: var(--transition);
 }

 .btn-publish-live:disabled {
 opacity: 0.35;
 cursor: not-allowed;
 transform: none !important;
 box-shadow: none !important;
 }

 .btn-publish-live:not(:disabled):hover {
 transform: translateY(-1px);
 box-shadow: 0 6px 20px var(--green-glow);
 color: #fff;
 }

 /* ===== TEST CONSOLE ===== */
 .test-console {
 background: #08080f;
 border: 1px solid rgba(255,255,255,0.05);
 border-radius: var(--radius);
 padding: 1rem 1.15rem;
 max-height: 400px;
 overflow-y: auto;
 font-family: 'JetBrains Mono', monospace;
 font-size: 0.76rem;
 line-height: 1.7;
 color: var(--green);
 margin-top: 1.15rem;
 }

 .test-console .error-text { color: var(--red); }
 .test-console .sys-text { color: var(--text-muted); }
 .test-console pre {
 color: var(--text-secondary);
 font-family: 'JetBrains Mono', monospace;
 font-size: 0.74rem;
 white-space: pre-wrap;
 word-break: break-word;
 margin: 0;
 }

 /* ===== MODAL ===== */
 .modal-content {
 background: var(--bg-surface);
 border: 1px solid var(--glass-border);
 border-radius: var(--radius-lg);
 box-shadow: 0 25px 60px rgba(0,0,0,0.5);
 }

 .modal-header { border-bottom: 1px solid var(--glass-border); padding: 1.15rem 1.5rem; }
 .modal-title { font-weight: 700; font-size: 0.95rem; color: var(--text-primary); }
 .modal-body { padding: 1.5rem; }

 .modal-body textarea {
 background: rgba(255,255,255,0.04) !important;
 border: 1px solid var(--glass-border) !important;
 color: var(--text-primary) !important;
 font-family: 'JetBrains Mono', monospace;
 font-size: 0.8rem;
 }

 .modal-body textarea:focus {
 background: rgba(99,102,241,0.04) !important;
 border-color: rgba(99,102,241,0.3) !important;
 box-shadow: 0 0 0 3px rgba(99,102,241,0.08) !important;
 }

 .modal-footer { border-top: 1px solid var(--glass-border); padding: 1rem 1.5rem; }

 .modal-footer .btn-secondary {
 background: rgba(255,255,255,0.06);
 border: 1px solid var(--glass-border);
 color: var(--text-secondary);
 }

 .modal-footer .btn-primary-modal {
 background: linear-gradient(135deg, var(--accent), #7c3aed);
 border: none;
 color: #fff;
 font-weight: 600;
 padding: 0.5rem 1.2rem;
 border-radius: 8px;
 transition: var(--transition);
 }

 .modal-footer .btn-primary-modal:hover {
 box-shadow: 0 4px 16px var(--accent-glow);
 }

 .btn-close { filter: invert(1) grayscale(100%) brightness(200%); opacity: 0.5; }

 /* ===== TOAST ===== */
 .toast { border-radius: var(--radius) !important; font-size: 0.82rem; font-weight: 500; }

 .spinner-border-sm { width: 0.85rem; height: 0.85rem; border-width: 2px; }

 /* ===== STEP SUMMARY BADGES (visible on completed steps in stepper) ===== */
 .step-summary {
 margin-top: 0.3rem;
 font-size: 0.6rem;
 color: var(--text-muted);
 max-width: 120px;
 text-align: center;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 }

 /* ===== SCROLLBAR ===== */
 ::-webkit-scrollbar { width: 5px; height: 5px; }
 ::-webkit-scrollbar-track { background: transparent; }
 ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.08); border-radius: 4px; }
 ::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.15); }

 /* ===== RESPONSIVE ===== */
 @media (max-width: 991.98px) {
 .sidebar { transform: translateX(-100%); }
 .sidebar.open { transform: translateX(0); }
 .sidebar-overlay.active { display: block; }
 .sidebar-toggle { display: flex; align-items: center; justify-content: center; }
 .main-content { margin-left: 0; padding: 1.25rem; padding-top: 4rem; }
 .page-header { flex-direction: column; align-items: flex-start; gap: 0.75rem; }
 .wizard-stepper { gap: 0; }
 .wizard-step .step-label { font-size: 0.6rem; }
 .wizard-step .step-node { width: 34px; height: 34px; font-size: 0.72rem; }
 .wizard-step:not(:last-child)::after { top: 17px; left: calc(50% + 20px); width: calc(100% - 40px); }
 }

 @media (max-width: 575.98px) {
 .main-content { padding: 0.85rem; padding-top: 3.5rem; }
 .wizard-step .step-label { display: none; }
 }
 </style>
</head>
<body>

<!-- Mobile toggle -->
<button class="sidebar-toggle" onclick="toggleSidebar()" aria-label="Toggle sidebar">
 <i class="fa-solid fa-bars"></i>
</button>
<div class="sidebar-overlay" id="sidebarOverlay" onclick="toggleSidebar()"></div>

<!-- ===== SIDEBAR ===== -->
<aside class="sidebar" id="sidebar">
 <div class="sidebar-brand">
 <div class="logo"><i class="fa-solid fa-cube me-2"></i>MCP Studio</div>
 <div class="subtitle">Zero-Code Tool Builder</div>
 </div>
 <button class="btn btn-new-tool w-auto" onclick="createNewTool()">
 <i class="fa-solid fa-plus me-2"></i>New Tool
 </button>
 <div class="sidebar-tools">
 <div class="sidebar-section-label">
 <i class="fa-solid fa-circle" style="color:var(--green); font-size:0.35rem; vertical-align:middle;"></i> Published
 </div>
 <ul class="nav flex-column" id="published-list"></ul>
 <div class="sidebar-section-label" style="margin-top:0.5rem;">
 <i class="fa-solid fa-circle" style="color:var(--amber); font-size:0.35rem; vertical-align:middle;"></i> Drafts
 </div>
 <ul class="nav flex-column" id="drafts-list"></ul>
 </div>
 <div class="sidebar-footer">
 <div class="server-status">
 <span class="dot" id="serverDot"></span>
 <span id="serverLabel">Checking server…</span>
 </div>
 </div>
</aside>

<!-- ===== MAIN CONTENT ===== -->
<main class="main-content">

 <div class="page-header">
 <div>
 <h2 id="form-title">Create New Tool</h2>
 <div class="subtitle">Define, test, and publish dynamic tools to the MCP server</div>
 </div>
 <button class="btn btn-curl-import" data-bs-toggle="modal" data-bs-target="#curlModal">
 <i class="fa-solid fa-bolt text-warning me-2"></i>Import cURL
 </button>
 </div>

 <!-- WIZARD STEPPER -->
 <div class="wizard-stepper" id="wizardStepper">
 <div class="wizard-step active" data-step="0" onclick="goToStep(0)">
 <div class="step-node">1</div>
 <div class="step-label">Core Definition</div>
 <div class="step-summary" id="step0-summary"></div>
 </div>
 <div class="wizard-step locked" data-step="1" onclick="goToStep(1)">
 <div class="step-node">2</div>
 <div class="step-label">Governance</div>
 <div class="step-summary" id="step1-summary"></div>
 </div>
 <div class="wizard-step locked" data-step="2" onclick="goToStep(2)">
 <div class="step-node">3</div>
 <div class="step-label">Parameters</div>
 <div class="step-summary" id="step2-summary"></div>
 </div>
 <div class="wizard-step locked" data-step="3" onclick="goToStep(3)">
 <div class="step-node">4</div>
 <div class="step-label">Test & Publish</div>
 <div class="step-summary" id="step3-summary"></div>
 </div>
 </div>

 <form id="tool-form" autocomplete="off">

 <!-- STEP 0: Core Definition -->
 <div class="step-panel active" id="stepPanel0">
 <div class="glass-panel">
 <div class="panel-title">
 <span class="icon-box"><i class="fa-solid fa-gear"></i></span>
 Core Definition
 </div>
 <div class="panel-body">
 <div class="row g-3">
 <div class="col-lg-5 col-md-6">
 <label class="form-label required">Tool Name (MCP ID)</label>
 <input type="text" class="form-control" id="f_name" placeholder="e.g. check_inventory">
 <div class="form-text">Unique snake_case ID used by the AI agent.</div>
 </div>
 <div class="col-lg-3 col-md-3">
 <label class="form-label required">HTTP Method</label>
 <select class="form-select" id="f_method">
 <option value="GET">GET</option>
 <option value="POST">POST</option>
 <option value="PUT">PUT</option>
 <option value="PATCH">PATCH</option>
 <option value="DELETE">DELETE</option>
 </select>
 </div>
 <div class="col-lg-4 col-md-3">
 <label class="form-label required">Timeout (sec)</label>
 <input type="number" class="form-control" id="f_timeout" value="120" min="1">
 </div>
 <div class="col-12">
 <label class="form-label required">Endpoint URL</label>
 <input type="url" class="form-control" id="f_endpoint" placeholder="https://api.example.com/v1/resource">
 </div>
 <div class="col-12">
 <label class="form-label required">AI Description</label>
 <input type="text" class="form-control" id="f_desc" placeholder="Tell the AI exactly when and why to call this tool...">
 <div class="form-text text-danger">
 <i class="fa-solid fa-circle-exclamation me-1"></i>
 The AI reads this to decide when to trigger the tool. Be precise.
 </div>
 </div>
 </div>
 </div>
 </div>
 <div class="step-nav">
 <div></div>
 <button type="button" class="btn btn-step btn-step-next" onclick="nextStep()">
 Continue <i class="fa-solid fa-arrow-right"></i>
 </button>
 </div>
 </div>

 <!-- STEP 1: Governance -->
 <div class="step-panel" id="stepPanel1">
 <div class="glass-panel">
 <div class="panel-title">
 <span class="icon-box"><i class="fa-solid fa-shield-halved"></i></span>
 Governance & Security
 </div>
 <div class="panel-body">
 <div class="row g-3">
 <div class="col-md-4">
 <label class="form-label">Risk Level</label>
 <select class="form-select" id="f_risk">
 <option value="low">Low</option>
 <option value="medium">Medium</option>
 <option value="high">High</option>
 </select>
 </div>
 <div class="col-md-4">
 <label class="form-label">Impact Area</label>
 <select class="form-select" id="f_impact">
 <option value="read">Read</option>
 <option value="write">Write</option>
 <option value="delete">Delete</option>
 <option value="execute">Execute</option>
 </select>
 </div>
 <div class="col-md-4 d-flex align-items-end">
 <div class="form-check form-switch mb-1">
 <input class="form-check-input" type="checkbox" id="f_auth" role="switch">
 <label class="form-check-label" for="f_auth">Requires Authentication</label>
 </div>
 </div>
 <div class="col-12">
 <label class="form-label">Risk Description</label>
 <textarea class="form-control" id="f_risk_desc" rows="2" placeholder="Describe the worst-case scenario if misused..."></textarea>
 </div>
 </div>
 </div>
 </div>
 <div class="step-nav">
 <button type="button" class="btn btn-step btn-step-back" onclick="prevStep()">
 <i class="fa-solid fa-arrow-left"></i> Back
 </button>
 <div class="d-flex gap-2">
 <button type="button" class="btn btn-skip" onclick="nextStep()">Skip</button>
 <button type="button" class="btn btn-step btn-step-next" onclick="nextStep()">
 Continue <i class="fa-solid fa-arrow-right"></i>
 </button>
 </div>
 </div>
 </div>

 <!-- STEP 2: Parameters -->
 <div class="step-panel" id="stepPanel2">
 <div class="glass-panel">
 <div class="panel-title">
 <span class="icon-box"><i class="fa-solid fa-sliders"></i></span>
 Parameters
 <span class="text-muted" style="font-weight:400; font-size:0.78rem;">(API Payload)</span>
 <div class="ms-auto">
 <button type="button" class="btn btn-add-param" onclick="addParameterRow()">
 <i class="fa-solid fa-plus me-1"></i>Add
 </button>
 </div>
 </div>
 <div class="panel-body p-0">
 <div class="param-table-wrap">
 <table class="table table-borderless align-middle mb-0" id="params-table">
 <thead>
 <tr>
 <th width="20%">Name</th>
 <th width="14%">Type</th>
 <th width="34%">AI Description</th>
 <th width="27%">Default Value</th>
 <th width="5%"></th>
 </tr>
 </thead>
 <tbody id="params-body"></tbody>
 </table>
 </div>
 <div id="no-params-msg" class="param-empty">
 <div class="empty-icon"><i class="fa-solid fa-box-open" style="color:var(--text-muted);"></i></div>
 <div>No parameters defined yet</div>
 <div class="form-text mt-1">The AI will send an empty payload when calling this tool.</div>
 </div>
 </div>
 </div>
 <div class="step-nav">
 <button type="button" class="btn btn-step btn-step-back" onclick="prevStep()">
 <i class="fa-solid fa-arrow-left"></i> Back
 </button>
 <div class="d-flex gap-2">
 <button type="button" class="btn btn-skip" onclick="nextStep()">Skip</button>
 <button type="button" class="btn btn-step btn-step-next" onclick="nextStep()">
 Continue <i class="fa-solid fa-arrow-right"></i>
 </button>
 </div>
 </div>
 </div>

 <!-- STEP 3: Test & Publish -->
 <div class="step-panel" id="stepPanel3">
 <div class="publish-zone">
 <h5 style="font-size:0.9rem; font-weight:700; margin-bottom:0.4rem;">
 <i class="fa-solid fa-vial-circle-check me-2" style="color:var(--accent-light);"></i>
 Test & Publish
 </h5>
 <p style="font-size:0.76rem; color:var(--text-muted); margin-bottom:1.25rem;">
 The tool is registered in-memory, tested via a real MCP call, and the result appears below.
 A successful test unlocks the Publish button.
 </p>

 <div id="test-inputs-container" class="test-args-box d-none">
 <h6><i class="fa-solid fa-terminal me-2"></i>Test Arguments</h6>
 <div id="test-fields" class="row g-3"></div>
 </div>

 <div class="d-flex flex-wrap gap-2 align-items-center">
 <button type="button" class="btn btn-test" id="btn-test" onclick="runTest()">
 <i class="fa-solid fa-play me-2"></i>Run MCP Test
 </button>
 <div class="ms-auto d-flex gap-2">
 <button type="button" class="btn btn-save-draft" id="btn-save" onclick="saveTool('draft')">
 <i class="fa-regular fa-floppy-disk me-1"></i>Save Draft
 </button>
 <button type="button" class="btn btn-publish-live" id="btn-publish" onclick="saveTool('published')" disabled>
 <i class="fa-solid fa-rocket me-1"></i>Publish Live
 </button>
 </div>
 </div>

 <div id="test-console" class="test-console d-none">
 <div id="test-console-text"></div>
 </div>
 </div>
 <div class="step-nav">
 <button type="button" class="btn btn-step btn-step-back" onclick="prevStep()">
 <i class="fa-solid fa-arrow-left"></i> Back
 </button>
 <div></div>
 </div>
 </div>

 </form>
</main>

<!-- ===== cURL MODAL ===== -->
<div class="modal fade" id="curlModal" tabindex="-1">
 <div class="modal-dialog modal-lg modal-dialog-centered">
 <div class="modal-content">
 <div class="modal-header">
 <h5 class="modal-title"><i class="fa-solid fa-bolt text-warning me-2"></i>Quick Import from cURL</h5>
 <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
 </div>
 <div class="modal-body">
 <label class="form-label" style="text-transform:none; letter-spacing:0;">Paste your raw cURL command below</label>
 <textarea class="form-control" id="curl-input" rows="7" placeholder="curl -X POST https://api.example.com/data &#10; -H 'Authorization: Bearer ...' &#10; -d '{&quot;key&quot;: &quot;value&quot;}'"></textarea>
 </div>
 <div class="modal-footer">
 <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button>
 <button type="button" class="btn btn-primary-modal" id="btn-curl-import" onclick="importCurl()">
 Parse & Apply <i class="fa-solid fa-wand-magic-sparkles ms-2"></i>
 </button>
 </div>
 </div>
 </div>
</div>

<!-- ===== TOAST ===== -->
<div class="toast-container position-fixed bottom-0 end-0 p-4" style="z-index: 1090;">
 <div id="liveToast" class="toast align-items-center text-white border-0 shadow-lg" role="alert">
 <div class="d-flex">
 <div class="toast-body fw-medium" id="toast-body"></div>
 <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button>
 </div>
 </div>
</div>

<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script>
<script src="/static/app.js"></script>
</body>
</html>

