/**
 * MCP Studio — Wizard-flow Frontend
 */

let currentTools = [];
let currentToolId = null;
let parameters = {};
let testPassed = false;

const TOTAL_STEPS = 4;
let currentStep = 0;
let highestUnlocked = 0;

document.addEventListener('DOMContentLoaded', () => {
 fetchTools();
 checkServerHealth();
 setInterval(checkServerHealth, 30000);

 const form = document.getElementById('tool-form');
 form.addEventListener('input', handleFormChange);
 form.addEventListener('change', handleFormChange);

 syncStepperUI();
});

// ── Wizard Navigation ──────────────────────────────────────────────────

function goToStep(index) {
 if (index < 0 || index >= TOTAL_STEPS) return;
 if (index > highestUnlocked) return;

 if (index > currentStep && !validateCurrentStep()) return;

 currentStep = index;
 showStepPanel(currentStep);
 syncStepperUI();
}

function nextStep() {
 if (!validateCurrentStep()) return;

 if (currentStep < TOTAL_STEPS - 1) {
 if (currentStep >= highestUnlocked) {
 highestUnlocked = currentStep + 1;
 }
 currentStep++;
 showStepPanel(currentStep);
 syncStepperUI();
 window.scrollTo({ top: 0, behavior: 'smooth' });
 }
}

function prevStep() {
 if (currentStep > 0) {
 currentStep--;
 showStepPanel(currentStep);
 syncStepperUI();
 }
}

function showStepPanel(index) {
 document.querySelectorAll('.step-panel').forEach((p, i) => {
 if (i === index) {
 p.classList.add('active');
 } else {
 p.classList.remove('active');
 }
 });

 if (index === 3) renderTestFields();
}

function syncStepperUI() {
 const steps = document.querySelectorAll('.wizard-step');

 steps.forEach((el, i) => {
 el.classList.remove('active', 'completed', 'locked', 'accessible');

 if (i === currentStep) {
 el.classList.add('active');
 } else if (i < currentStep) {
 el.classList.add('completed');
 el.querySelector('.step-node').innerHTML = '<i class="fa-solid fa-check" style="font-size:0.7rem;"></i>';
 } else if (i <= highestUnlocked) {
 el.classList.add('accessible');
 } else {
 el.classList.add('locked');
 }

 if (i !== currentStep && i < currentStep) {
 // keep checkmark
 } else if (i >= currentStep) {
 const num = i + 1;
 if (i !== currentStep || !el.querySelector('.fa-check')) {
 el.querySelector('.step-node').textContent = num;
 }
 }
 });

 updateStepSummaries();
}

function updateStepSummaries() {
 const name = document.getElementById('f_name').value.trim();
 document.getElementById('step0-summary').textContent = name || '';

 const risk = document.getElementById('f_risk').value;
 document.getElementById('step1-summary').textContent = currentStep > 1 ? `Risk: ${risk}` : '';

 const paramCount = Object.keys(parameters).length;
 document.getElementById('step2-summary').textContent = currentStep > 2
 ? `${paramCount} param${paramCount !== 1 ? 's' : ''}`
 : '';

 document.getElementById('step3-summary').textContent = testPassed ? 'Tested' : '';
}

function validateCurrentStep() {
 if (currentStep === 0) {
 const name = document.getElementById('f_name').value.trim();
 const endpoint = document.getElementById('f_endpoint').value.trim();
 const desc = document.getElementById('f_desc').value.trim();

 if (!name) {
 shakeField('f_name');
 showToast('Tool Name is required.', 'warning');
 return false;
 }
 if (!endpoint) {
 shakeField('f_endpoint');
 showToast('Endpoint URL is required.', 'warning');
 return false;
 }
 if (!desc) {
 shakeField('f_desc');
 showToast('AI Description is required.', 'warning');
 return false;
 }
 return true;
 }

 // Steps 1,2 are optional
 return true;
}

function shakeField(id) {
 const el = document.getElementById(id);
 el.style.borderColor = 'rgba(239,68,68,0.6)';
 el.style.animation = 'shake 0.4s ease';
 el.focus();
 setTimeout(() => {
 el.style.borderColor = '';
 el.style.animation = '';
 }, 600);
}

// Inject shake keyframe
const shakeStyle = document.createElement('style');
shakeStyle.textContent = `
@keyframes shake {
 0%, 100% { transform: translateX(0); }
 20% { transform: translateX(-6px); }
 40% { transform: translateX(6px); }
 60% { transform: translateX(-4px); }
 80% { transform: translateX(4px); }
}`;
document.head.appendChild(shakeStyle);

// ── Form Change → invalidate test ──────────────────────────────────────

function handleFormChange(e) {
 if (e.target.closest('#test-inputs-container')) return;
 testPassed = false;
 document.getElementById('btn-publish').disabled = true;
}

// ── Server Health ──────────────────────────────────────────────────────

async function checkServerHealth() {
 const dot = document.getElementById('serverDot');
 const label = document.getElementById('serverLabel');
 try {
 const res = await fetch('/api/tools', { signal: AbortSignal.timeout(5000) });
 if (res.ok) {
 dot.className = 'dot online';
 label.textContent = 'Server connected';
 } else { throw new Error(); }
 } catch {
 dot.className = 'dot offline';
 label.textContent = 'Server unreachable';
 }
}

// ── Toast ──────────────────────────────────────────────────────────────

function showToast(message, type = 'success') {
 const toastEl = document.getElementById('liveToast');
 const body = document.getElementById('toast-body');
 const colors = { success: 'bg-success', danger: 'bg-danger', warning: 'bg-warning text-dark', info: 'bg-info text-dark' };
 toastEl.className = `toast align-items-center border-0 shadow-lg ${colors[type] || 'bg-primary'}`;
 body.innerHTML = message;
 new bootstrap.Toast(toastEl, { delay: 4000 }).show();
}

// ── Mobile Sidebar ─────────────────────────────────────────────────────

function toggleSidebar() {
 document.getElementById('sidebar').classList.toggle('open');
 document.getElementById('sidebarOverlay').classList.toggle('active');
}

// ── API: Fetch Tools ───────────────────────────────────────────────────

async function fetchTools() {
 try {
 const res = await fetch('/api/tools');
 if (!res.ok) throw new Error();
 const data = await res.json();
 currentTools = data.tools || [];
 renderSidebar();
 } catch (e) {
 showToast('<i class="fa-solid fa-triangle-exclamation me-2"></i>Failed to load tools', 'danger');
 }
}

// ── cURL Import ────────────────────────────────────────────────────────

async function importCurl() {
 const curlStr = document.getElementById('curl-input').value;
 const btn = document.getElementById('btn-curl-import');
 if (!curlStr.trim()) { showToast('Please paste a cURL command', 'warning'); return; }

 const saved = btn.innerHTML;
 btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Parsing…';
 btn.disabled = true;

 try {
 const res = await fetch('/api/curl/parse', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({ curl_cmd: curlStr }),
 });
 const data = await res.json();
 if (res.ok) {
 loadToolIntoForm(data, true);
 bootstrap.Modal.getInstance(document.getElementById('curlModal')).hide();
 document.getElementById('curl-input').value = '';
 showToast('<i class="fa-solid fa-check-circle me-2"></i>cURL imported!', 'success');
 } else {
 showToast(data.detail, 'danger');
 }
 } catch {
 showToast('Error parsing cURL', 'danger');
 } finally {
 btn.innerHTML = saved;
 btn.disabled = false;
 }
}

// ── Sidebar ────────────────────────────────────────────────────────────

function renderSidebar() {
 const pubList = document.getElementById('published-list');
 const draftList = document.getElementById('drafts-list');
 pubList.innerHTML = '';
 draftList.innerHTML = '';

 currentTools.sort((a, b) => (a.name || '').localeCompare(b.name || ''));

 currentTools.forEach(tool => {
 const li = document.createElement('li');
 li.className = 'nav-item';
 const a = document.createElement('a');
 a.className = `nav-link tool-item ${tool.id === currentToolId ? 'active' : ''}`;
 a.href = '#';
 a.onclick = (e) => {
 e.preventDefault();
 loadToolIntoForm(tool);
 document.querySelectorAll('.tool-item').forEach(el => el.classList.remove('active'));
 a.classList.add('active');
 if (window.innerWidth < 992) toggleSidebar();
 };
 const isPub = tool.status === 'published';
 a.innerHTML = `<span class="status-dot ${isPub ? 'published' : 'draft'}"></span>${tool.name}`;
 (isPub ? pubList : draftList).appendChild(li);
 li.appendChild(a);
 });

 if (!pubList.children.length) pubList.innerHTML = '<li class="sidebar-empty">No published tools</li>';
 if (!draftList.children.length) draftList.innerHTML = '<li class="sidebar-empty">No drafts yet</li>';
}

// ── New / Load Tool ────────────────────────────────────────────────────

function createNewTool() {
 document.querySelectorAll('.tool-item').forEach(el => el.classList.remove('active'));
 loadToolIntoForm({
 name: '', description: '',
 metadata: { risk_level: 'low', impact_area: 'read', requires_auth: false, risk_description: '' },
 config: { endpoint: '', method: 'GET', timeout: 120 },
 parameters: {},
 });
 document.getElementById('form-title').textContent = 'Create New Tool';
 if (window.innerWidth < 992) toggleSidebar();
}

function loadToolIntoForm(tool, isNewImport = false) {
 currentToolId = isNewImport ? null : tool.id;
 document.getElementById('form-title').textContent = isNewImport
 ? 'Imported Tool (Unsaved)'
 : (tool.name ? `Editing: ${tool.name}` : 'Create New Tool');

 document.getElementById('f_name').value = tool.name || '';
 document.getElementById('f_method').value = tool.config?.method || 'GET';
 document.getElementById('f_endpoint').value = tool.config?.endpoint || '';
 document.getElementById('f_desc').value = tool.description || '';
 document.getElementById('f_timeout').value = tool.config?.timeout || 120;

 const meta = tool.metadata || {};
 document.getElementById('f_risk').value = meta.risk_level || 'low';
 document.getElementById('f_impact').value = meta.impact_area || 'read';
 document.getElementById('f_auth').checked = meta.requires_auth || false;
 document.getElementById('f_risk_desc').value = meta.risk_description || '';

 parameters = tool.parameters ? JSON.parse(JSON.stringify(tool.parameters)) : {};

 testPassed = false;
 document.getElementById('btn-publish').disabled = true;
 document.getElementById('test-console').classList.add('d-none');

 // Clear stale uploaded file references
 Object.keys(uploadedFilePaths).forEach(k => delete uploadedFilePaths[k]);

 renderParamsTable();

 // Reset wizard to step 0 for new tools, or unlock all for existing tools
 if (isNewImport || !tool.id) {
 currentStep = 0;
 highestUnlocked = 0;
 } else {
 currentStep = 0;
 highestUnlocked = TOTAL_STEPS - 1;
 }
 showStepPanel(currentStep);
 syncStepperUI();
}

// ── Parameters ─────────────────────────────────────────────────────────

function renderParamsTable() {
 const tbody = document.getElementById('params-body');
 const noMsg = document.getElementById('no-params-msg');
 const tableEl = document.getElementById('params-table');
 tbody.innerHTML = '';

 const keys = Object.keys(parameters);
 if (!keys.length) {
 noMsg.classList.remove('d-none');
 tableEl.classList.add('d-none');
 return;
 }

 noMsg.classList.add('d-none');
 tableEl.classList.remove('d-none');

 keys.forEach(key => {
 const p = parameters[key];
 const tr = document.createElement('tr');

 let defValue = p.default !== undefined ? p.default : '';
 if (p.type === 'array' || p.type === 'json') {
 defValue = typeof defValue === 'object' ? JSON.stringify(defValue) : defValue;
 }

 const types = ['string', 'file', 'number', 'boolean', 'array', 'json'];
 const opts = types.map(t => `<option value="${t}" ${p.type === t ? 'selected' : ''}>${t}</option>`).join('');

 const isComplex = p.type === 'array' || p.type === 'json';
 const defHtml = isComplex
 ? `<textarea class="form-control form-control-sm" rows="2" onchange="updateParam('${key}','default',this.value)" placeholder="[] or {}">${defValue}</textarea>`
 : `<input type="text" class="form-control form-control-sm" value='${defValue}' onchange="updateParam('${key}','default',this.value)">`;

 tr.innerHTML = `
 <td><input type="text" class="form-control form-control-sm fw-medium" value="${key}"
 onchange="updateParamKey('${key}',this.value)" placeholder="param_name"></td>
 <td><select class="form-select form-select-sm" onchange="updateParam('${key}','type',this.value)">${opts}</select></td>
 <td><input type="text" class="form-control form-control-sm" value="${p.description || ''}"
 onchange="updateParam('${key}','description',this.value)" placeholder="Description for AI…"></td>
 <td>${defHtml}</td>
 <td class="text-end">
 <button type="button" class="btn-delete-param" onclick="deleteParam('${key}')" title="Remove">
 <i class="fa-solid fa-xmark"></i>
 </button>
 </td>`;
 tbody.appendChild(tr);
 });
}

function addParameterRow() {
 let name = 'new_param';
 let i = 1;
 while (parameters[name]) name = `new_param_${i++}`;
 parameters[name] = { type: 'string', description: '', default: '' };
 renderParamsTable();
}

function updateParamKey(oldKey, newKey) {
 newKey = newKey.trim();
 if (oldKey === newKey || !newKey) return;
 if (parameters[newKey]) {
 showToast('Parameter name already exists', 'warning');
 renderParamsTable();
 return;
 }
 parameters[newKey] = parameters[oldKey];
 delete parameters[oldKey];
 renderParamsTable();
}

function updateParam(key, field, value) {
 parameters[key][field] = value;
 if (field === 'type') {
 parameters[key].default = '';
 renderParamsTable();
 }
}

function deleteParam(key) {
 delete parameters[key];
 renderParamsTable();
}

// ── Test Fields ────────────────────────────────────────────────────────

// Tracks server-side paths for uploaded test files { paramKey: "/tmp/..." }
const uploadedFilePaths = {};

function renderTestFields() {
 const container = document.getElementById('test-inputs-container');
 const fieldsDiv = document.getElementById('test-fields');
 fieldsDiv.innerHTML = '';

 const keys = Object.keys(parameters);
 if (!keys.length) {
 container.classList.add('d-none');
 return;
 }

 container.classList.remove('d-none');

 keys.forEach(key => {
 const p = parameters[key];
 const col = document.createElement('div');
 col.className = 'col-md-6';

 let defVal = p.default || '';
 if (p.type === 'array' || p.type === 'json') {
 defVal = typeof defVal === 'object' ? JSON.stringify(defVal) : defVal;
 }

 const badge = (label, cls) => `<span class="badge ${cls} ms-1" style="font-size:0.6rem;">${label}</span>`;
 let html = '';

 if (p.type === 'file') {
 const alreadyUploaded = uploadedFilePaths[key];
 const statusHtml = alreadyUploaded
 ? `<div class="file-status uploaded"><i class="fa-solid fa-circle-check"></i> ${escapeHtml(alreadyUploaded.split('/').pop())}</div>`
 : `<div class="file-status" id="file-status-${key}"></div>`;
 html = `
 <label class="form-label" style="text-transform:none;letter-spacing:0;">
 ${key} ${badge('file', 'bg-warning text-dark')}
 </label>
 <div class="file-picker-wrap">
 <input type="file" class="form-control test-file-input" data-key="${key}"
 onchange="handleTestFileSelect(this, '${key}')">
 ${statusHtml}
 </div>`;
 } else if (p.type === 'boolean') {
 html = `<div class="form-check form-switch mt-3">
 <input type="checkbox" class="form-check-input test-input" id="test_${key}"
 data-key="${key}" data-type="boolean" ${defVal === 'true' || defVal === true ? 'checked' : ''}>
 <label class="form-check-label" for="test_${key}">${key} ${badge('bool','bg-secondary')}</label>
 </div>`;
 } else if (p.type === 'number') {
 html = `<label class="form-label" style="text-transform:none;letter-spacing:0;">${key} ${badge('number','bg-secondary')}</label>
 <input type="number" class="form-control test-input" data-key="${key}" data-type="number" value="${defVal}">`;
 } else if (p.type === 'array' || p.type === 'json') {
 html = `<label class="form-label" style="text-transform:none;letter-spacing:0;">${key} ${badge(p.type,'bg-info text-dark')}</label>
 <textarea class="form-control test-input" rows="2" data-key="${key}" data-type="${p.type}"
 style="font-family:'JetBrains Mono',monospace;font-size:0.8rem;">${defVal}</textarea>`;
 } else {
 html = `<label class="form-label" style="text-transform:none;letter-spacing:0;">${key} ${badge(p.type,'bg-secondary bg-opacity-50')}</label>
 <input type="text" class="form-control test-input" data-key="${key}" data-type="${p.type}" value='${defVal}'>`;
 }

 col.innerHTML = html;
 fieldsDiv.appendChild(col);
 });
}

// ── File Upload for Test ───────────────────────────────────────────────

async function handleTestFileSelect(inputEl, paramKey) {
 const file = inputEl.files[0];
 if (!file) return;

 const statusEl = inputEl.parentElement.querySelector('.file-status')
 || document.getElementById(`file-status-${paramKey}`);

 if (statusEl) {
 statusEl.className = 'file-status uploading';
 statusEl.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Uploading ${escapeHtml(file.name)}…`;
 }

 const formData = new FormData();
 formData.append('file', file);

 try {
 const res = await fetch('/api/upload-test-file', { method: 'POST', body: formData });
 const data = await res.json();

 if (res.ok && data.path) {
 uploadedFilePaths[paramKey] = data.path;
 if (statusEl) {
 statusEl.className = 'file-status uploaded';
 statusEl.innerHTML = `<i class="fa-solid fa-circle-check"></i> ${escapeHtml(file.name)}`;
 }
 } else {
 delete uploadedFilePaths[paramKey];
 if (statusEl) {
 statusEl.className = 'file-status error';
 statusEl.innerHTML = `<i class="fa-solid fa-circle-xmark"></i> Upload failed`;
 }
 showToast('File upload failed: ' + (data.detail || 'unknown error'), 'danger');
 }
 } catch {
 delete uploadedFilePaths[paramKey];
 if (statusEl) {
 statusEl.className = 'file-status error';
 statusEl.innerHTML = `<i class="fa-solid fa-circle-xmark"></i> Network error`;
 }
 showToast('Network error uploading file.', 'danger');
 }
}

// ── Form Data ──────────────────────────────────────────────────────────

function getFormData() {
 const cleanedParams = {};
 Object.keys(parameters).forEach(k => {
 const p = { ...parameters[k] };
 if (p.default !== '' && p.default != null) {
 if (p.type === 'number') p.default = parseFloat(p.default) || 0;
 if (p.type === 'boolean') p.default = (p.default === 'true' || p.default === true);
 if (p.type === 'array' || p.type === 'json') {
 try { p.default = JSON.parse(p.default); } catch { /* keep string */ }
 }
 } else {
 delete p.default;
 }
 cleanedParams[k] = p;
 });

 return {
 id: currentToolId,
 status: 'draft',
 name: document.getElementById('f_name').value.trim(),
 description: document.getElementById('f_desc').value.trim(),
 metadata: {
 risk_level: document.getElementById('f_risk').value,
 impact_area: document.getElementById('f_impact').value,
 requires_auth: document.getElementById('f_auth').checked,
 risk_description: document.getElementById('f_risk_desc').value.trim(),
 },
 config: {
 endpoint: document.getElementById('f_endpoint').value.trim(),
 method: document.getElementById('f_method').value,
 timeout: parseFloat(document.getElementById('f_timeout').value) || 120,
 },
 parameters: cleanedParams,
 };
}

// ── Run MCP Test ───────────────────────────────────────────────────────

async function runTest() {
 const config = getFormData();
 if (!config.name || !config.config.endpoint || !config.description) {
 showToast('Name, Endpoint, and Description are required.', 'warning');
 return;
 }

 const btn = document.getElementById('btn-test');
 const saved = btn.innerHTML;
 btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Running…';
 btn.disabled = true;

 const testArgs = {};

 // Collect non-file inputs
 document.querySelectorAll('.test-input').forEach(input => {
 const key = input.dataset.key;
 const type = input.dataset.type;
 if (type === 'boolean') testArgs[key] = input.checked;
 else if (type === 'number') testArgs[key] = parseFloat(input.value) || 0;
 else if (type === 'array' || type === 'json') {
 try { testArgs[key] = JSON.parse(input.value || 'null'); }
 catch { testArgs[key] = input.value; }
 } else testArgs[key] = input.value;
 });

 // Inject uploaded file paths
 for (const [key, serverPath] of Object.entries(uploadedFilePaths)) {
 testArgs[key] = serverPath;
 }

 // Validate that all file params have been uploaded
 const missingFiles = Object.entries(parameters)
 .filter(([k, v]) => v.type === 'file' && !uploadedFilePaths[k])
 .map(([k]) => k);
 if (missingFiles.length) {
 showToast(`Select a file for: ${missingFiles.join(', ')}`, 'warning');
 btn.innerHTML = saved;
 btn.disabled = false;
 return;
 }

 const consoleDiv = document.getElementById('test-console');
 const consoleText = document.getElementById('test-console-text');
 consoleDiv.classList.remove('d-none');
 consoleText.innerHTML =
 '<span class="sys-text">▸ Registering dynamic handler…</span><br>' +
 '<span class="sys-text">▸ Executing MCP call…</span><br>';

 try {
 const res = await fetch('/api/tools/test', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({ config, test_args: testArgs }),
 });
 const data = await res.json();

 if (data.success) {
 const pretty = typeof data.output === 'object'
 ? JSON.stringify(data.output, null, 2) : data.output;
 consoleText.innerHTML +=
 `<br><span class="text-success fw-bold">● SUCCESS — 200 OK</span>` +
 `<br><pre class="mt-2">${escapeHtml(String(pretty))}</pre>`;
 testPassed = true;
 document.getElementById('btn-publish').disabled = false;
 showToast('<i class="fa-solid fa-circle-check me-2"></i>Test passed! Ready to publish.', 'success');
 } else {
 const prettyErr = typeof data.output === 'object'
 ? JSON.stringify(data.output, null, 2) : (data.output || data.detail);
 consoleText.innerHTML +=
 `<br><span class="error-text fw-bold">✕ FAILED</span>` +
 `<br><pre class="mt-2">${escapeHtml(String(prettyErr))}</pre>`;
 showToast('Test failed. Check console output.', 'danger');
 }
 } catch {
 consoleText.innerHTML += '<br><span class="error-text fw-bold">✕ FATAL — Network error.</span>';
 showToast('Network error during test.', 'danger');
 } finally {
 btn.innerHTML = saved;
 btn.disabled = false;
 }
}

// ── Save / Publish ─────────────────────────────────────────────────────

async function saveTool(status) {
 if (status === 'published' && !testPassed) {
 showToast('Run a successful test before publishing.', 'warning');
 return;
 }

 const config = getFormData();
 config.status = status;

 if (!config.name) { showToast('Tool name is required.', 'warning'); return; }

 const btnId = status === 'published' ? 'btn-publish' : 'btn-save';
 const btn = document.getElementById(btnId);
 const saved = btn.innerHTML;
 btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Saving…';
 btn.disabled = true;

 try {
 const res = await fetch('/api/tools/save', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify(config),
 });
 const data = await res.json();

 if (res.ok) {
 showToast(`<i class="fa-solid fa-check me-2"></i>${data.message}`, 'success');
 await fetchTools();
 if (!currentToolId) {
 const found = currentTools.find(t => t.name === config.name);
 if (found) currentToolId = found.id;
 }
 } else {
 showToast(`<i class="fa-solid fa-triangle-exclamation me-2"></i>${data.detail || 'Error saving'}`, 'danger');
 }
 } catch {
 showToast('Network error saving tool.', 'danger');
 } finally {
 btn.innerHTML = saved;
 btn.disabled = false;
 }
}

// ── Utility ────────────────────────────────────────────────────────────

function escapeHtml(str) {
 const d = document.createElement('div');
 d.appendChild(document.createTextNode(str));
 return d.innerHTML;
}

