"""
Load MCP tools from JSON definitions under tools/dynamic_configs/.
"""

import asyncio
import json
import os
from typing import Any, Callable, Type, Dict

import httpx
from loguru import logger
from pydantic import Field, create_model

from helpers.helper import (
 flatten_dynamic_params_for_query_or_form,
 normalize_dynamic_array_default,
)
from mcp.server.fastmcp import Context, FastMCP

# Names registered in the last load_dynamic_tools() call (for hot-reload).
_registered_dynamic_tool_names: set[str] = set()

_DYNAMIC_CONFIG_DIR = os.path.normpath(
 os.path.join(os.path.dirname(__file__), "..", "dynamic_configs")
)

async def call_api(
 url: str,
 method: str,
 payload: dict[str, Any],
 config: dict[str, Any],
) -> dict[str, Any]:
 api_timeout = config.get("config", {}).get("timeout", 120.0)
 async with httpx.AsyncClient(timeout=api_timeout) as client:
 files: dict[str, Any] = {}
 native: dict[str, Any] = {}
 params_cfg = config.get("parameters", {})
 for key, value in payload.items():
 param_entry = params_cfg.get(key, {})
 if not isinstance(param_entry, dict):
 param_entry = {}
 if param_entry.get("type") == "file":
 clean_path = str(value).strip('"').strip("'")
 if os.path.exists(clean_path):
 file_handle = open(clean_path, "rb")
 basename = os.path.basename(clean_path)
 files[key] = (basename, file_handle)
 else:
 return {"error": f"File not found: {clean_path}"}
 else:
 native[key] = value
 flat = flatten_dynamic_params_for_query_or_form(native, params_cfg)
 try:
 method_u = method.upper()
 resp = None

 if method_u == "POST":
 if files:
 resp = await client.post(url, data=flat, files=files)
 else:
 resp = await client.post(url, json=native)
 elif method_u == "GET":
 resp = await client.get(url, params=flat)
 elif method_u == "PUT":
 if files:
 resp = await client.put(url, data=flat, files=files)
 else:
 resp = await client.put(url, json=native)
 elif method_u == "PATCH":
 if files:
 resp = await client.patch(url, data=flat, files=files)
 else:
 resp = await client.patch(url, json=native)
 elif method_u == "DELETE":
 resp = await client.delete(url, params=flat)
 else:
 return {"error": f"Unsupported HTTP method: {method}"}

 try:
 return resp.json()
 except Exception:
 return {"status": resp.status_code, "raw_response": resp.text}
 except Exception as e:
 return {"error": "API Error", "details": str(e)}
 finally:
 for file_key in files:
 entry = files[file_key]
 file_obj = entry[1]
 try:
 file_obj.close()
 except Exception:
 pass

def _safe_model_name(tool_name: str) -> str:
 parts: list[str] = []
 for char in tool_name:
 if char.isalnum():
 parts.append(char)
 else:
 parts.append("_")
 safe = "".join(parts)
 if not safe:
 safe = "Dynamic"
 return f"{safe}Model"

def _build_field_definitions(parameters: dict[str, Any]) -> dict[str, Any]:
 fields: dict[str, Any] = {}
 for name, info in parameters.items():
 if info is None or not isinstance(info, dict):
 param_info: dict[str, Any] = {}
 else:
 param_info = info

 ptype = param_info.get("type", "string")
 desc = param_info.get("description", "")

 if "default" in param_info:
 default = param_info["default"]
 if ptype == "number":
 ann = float
 try:
 default = float(default) # type: ignore[arg-type]
 except (TypeError, ValueError):
 default = 0.0
 elif ptype == "boolean":
 ann = bool
 if isinstance(default, str):
 default = default.lower() in ("true", "1", "yes")
 elif ptype == "array":
 ann = list[str]
 default = normalize_dynamic_array_default(default)
 elif ptype in ("json", "object"):
 ann = dict[str, Any]
 if not isinstance(default, dict):
 try:
 parsed = json.loads(str(default))
 default = parsed if isinstance(parsed, dict) else {}
 except Exception:
 default = {}
 else:
 ann = str
 fields[name] = (ann, Field(default=default, description=desc))
 else:
 if ptype == "number":
 fields[name] = (float, Field(..., description=desc))
 elif ptype == "boolean":
 fields[name] = (bool, Field(..., description=desc))
 elif ptype == "array":
 fields[name] = (
 list[str],
 Field(default_factory=list, description=desc),
 )
 elif ptype in ("json", "object"):
 fields[name] = (
 dict[str, Any],
 Field(default_factory=dict, description=desc),
 )
 else:
 fields[name] = (str, Field(..., description=desc))
 return fields

def _unregister_previous_dynamic_tools(mcp_instance: FastMCP) -> None:
 """
 Drop dynamic tools we registered last time.

 FastMCP keeps tools by name: registering the same name again does not replace
 the old handler. We remove our previous names first so a reload re-reads JSON
 from disk and picks up edits (endpoint, parameters, etc.).
 """
 global _registered_dynamic_tool_names
 tm = mcp_instance._tool_manager
 for name in _registered_dynamic_tool_names:
 removed = tm._tools.pop(name, None)
 if removed:
 logger.debug("Removed previous dynamic tool: {}", name)
 _registered_dynamic_tool_names.clear()

def _list_json_config_filenames(config_dir: str) -> list[str]:
 names: list[str] = []
 for entry in os.listdir(config_dir):
 if entry.endswith(".json"):
 names.append(entry)
 names.sort()
 return names

def _register_dynamic_tool_handler(
 mcp_instance: FastMCP,
 cfg: dict[str, Any],
 ToolModel: Type[Any],
) -> None:
 """Attach one dynamic tool to FastMCP from a config dict and Pydantic arg model."""

 tool_desc = cfg.get("description")
 if not (isinstance(tool_desc, str) and tool_desc.strip()):
 tool_desc = None

 @mcp_instance.tool(name=cfg["name"], description=tool_desc)
 async def dynamic_tool(args: ToolModel, ctx: Context) -> Any:
 async def heartbeat() -> None:
 seconds = 0
 while True:
 await asyncio.sleep(5)
 seconds = seconds + 5
 try:
 await ctx.report_progress(
 seconds,
 120,
 f"Still processing API... {seconds}s elapsed",
 )
 except Exception:
 break

 pulse_task = asyncio.create_task(heartbeat())
 try:
 api_config = cfg.get("config")
 if api_config is None:
 api_config = {}
 endpoint = api_config.get("endpoint", "")
 http_method = api_config.get("method", "GET")
 dumped = args.model_dump()
 return await call_api(
 endpoint,
 http_method,
 dumped,
 cfg,
 )
 finally:
 pulse_task.cancel()

 # --- Attach Governance Metadata ---
 metadata = cfg.get("metadata", {})
 if not hasattr(mcp_instance, "_tool_metadata"):
 mcp_instance._tool_metadata = {}

 mcp_instance._tool_metadata[cfg["name"]] = {
 "risk_level": metadata.get("risk_level", "low"),
 "impact_area": metadata.get("impact_area", "read"),
 "requires_auth": metadata.get("requires_auth", False),
 "risk_description": metadata.get("risk_description", "")
 }

def register_dynamic_tool_from_config(
 mcp_instance: FastMCP,
 cfg: dict[str, Any],
 *,
 replace_existing: bool = True,
) -> tuple[bool, str]:
 """
 Register a single tool from an in-memory config (e.g. Streamlit Studio test preview).

 If replace_existing, removes any existing MCP tool with the same name first so the
 new handler is used (FastMCP does not overwrite duplicates by default).
 """
 tool_name = cfg.get("name")
 if not tool_name:
 return False, "Config is missing 'name'."

 params = cfg.get("parameters")
 if params is None:
 params = {}

 tm = mcp_instance._tool_manager
 if replace_existing:
 tm._tools.pop(str(tool_name), None)

 field_defs = _build_field_definitions(params)
 model_name = _safe_model_name(str(tool_name))
 ToolModel = create_model(model_name, **field_defs)
 _register_dynamic_tool_handler(mcp_instance, cfg, ToolModel)
 _registered_dynamic_tool_names.add(str(tool_name))
 logger.info("Registered dynamic tool '{}' from in-memory config (preview/studio)", tool_name)
 return True, "Registered."

def load_dynamic_tools(
 mcp_instance: FastMCP,
 tool_allowed_func: Callable[[str], bool],
) -> None:
 """
 Scan tools/dynamic_configs for *.json and register published tools.
 Clears tools registered by the previous call so configs can be hot-reloaded.
 """
 # Must run first: see _unregister_previous_dynamic_tools docstring.
 _unregister_previous_dynamic_tools(mcp_instance)

 if not os.path.isdir(_DYNAMIC_CONFIG_DIR):
 logger.warning(
 "Dynamic tools config directory missing: {} (skipping)",
 _DYNAMIC_CONFIG_DIR,
 )
 return

 json_files = _list_json_config_filenames(_DYNAMIC_CONFIG_DIR)
 if not json_files:
 logger.info("No JSON tool configs found in {}", _DYNAMIC_CONFIG_DIR)
 return

 for filename in json_files:
 path = os.path.join(_DYNAMIC_CONFIG_DIR, filename)
 try:
 with open(path, encoding="utf-8") as fp:
 cfg = json.load(fp)
 except Exception as e:
 logger.error("Failed to read dynamic tool config {}: {}", path, e)
 continue

 if cfg.get("status") != "published":
 continue

 tool_name = cfg.get("name")
 if not tool_name:
 logger.warning("Skipping {}: missing 'name'", path)
 continue

 if not tool_allowed_func(tool_name):
 logger.info("Dynamic tool '{}' skipped by tool_allowed_func", tool_name)
 continue

 params = cfg.get("parameters")
 if params is None:
 params = {}
 field_defs = _build_field_definitions(params)
 model_name = _safe_model_name(str(tool_name))
 ToolModel = create_model(model_name, **field_defs)
 _register_dynamic_tool_handler(mcp_instance, cfg, ToolModel)
 _registered_dynamic_tool_names.add(str(tool_name))
 logger.info("Registered dynamic tool '{}' from {}", tool_name, filename)

 count = len(_registered_dynamic_tool_names)
 logger.info(
 "Dynamic tools load complete: {} published tool(s) active",
 count,
 )

Project Brief: Zero-Code MCP Tooling & Studio (Phase 3)

Context & Objective
You are a senior AI collaborator and UI/UX expert. The goal is to maintain and evolve a Zero-Code Model Context Protocol (MCP) Framework. This system allows non-technical team members to create, test, and publish tools to a production MCP server via a web-based "Studio" without touching Python code or restarting the server process.

Technical Architecture:
The system is distributed across two main service processes running in the same project environment:

MCP Server (mcp_server_refactored.py - Port 8001):
The primary "Reader." It hosts the FastMCP instance and FastAPI shell.
Hot-Reloading Logic: Contains an /admin/reload endpoint. When triggered, it calls loader.py to clear the in-memory tool registry and re-scan the disk.
Execution Safety: Leverages Python’s asyncio event loop; active tool calls (Tasks) continue using old function objects in memory until completion, while new calls use the updated registry.

MCP Studio (studio_backend.py - Port 8002):
The primary "Writer." A separate FastAPI backend serving a modern UI.
Functionality: Handles cURL parsing, file writing to tools/dynamic_configs/, and proxies test calls.

The Admin Hook: Upon "Publishing," it saves a JSON config and sends a POST request to the MCP Server (8001) to sync state.

Dynamic Loader (loader.py):
The "Factory." It iterates through JSON files, generates dynamic Pydantic models for arguments, and registers @mcp.tool handlers on the fly.
Parameter Types Supported: string, number, boolean, array, json (nested objects), and file (multipart/form-data).

Frontend (studioUI/):
A high-end Bootstrap 5 + Vanilla JS interface. Uses an accordion-based workflow: Core Definition → Governance & Security → Parameters → Test & Publish.

Current Implementation Details:
JSON Schema: Tools are defined by an id, name, description, metadata (risk levels, impact area, auth), config (endpoint, method, timeout), and parameters.
Authentication: Supports standard Authorization: Bearer <token> headers.
Hot-Swap Flow: 1. Studio saves tool.json.
2. Studio hits 8001/admin/reload.
3. Server pops old tool names from tm._tools and re-registers.
4. Zero downtime achieved.

Roadmap & Future Requirements:
UI Redesign (Phase 3): Moving from Streamlit POC to a premium, dark-mode/glassmorphism inspired Dashboard. Focus on typography (Inter), consistent spacing, and micro-interactions (GSAP/AOS).
Intelligence: AI-assisted descriptions and JSON response filtering (picking specific fields to return to the LLM).

Governance: Stricter validation rules and global header presets (Vault for API keys).
Deployment: Production strategy uses process managers like pm2 or Docker Compose to run both services as isolated sidecars.

Your Tasking Rules:
Persona: Senior Product Designer + Lead Frontend Engineer. Prioritize usability and "premium" feel.
Code Consistency: Never modify the core tool-calling logic in mcp_server_refactored.py unless adding admin hooks. Preserve Pydantic-based dynamic model generation.
Safety: Ensure all dynamic registration logic avoids name collisions and properly handles file stream closures.
Simplicity: Keep the "Zero-Code" promise—adding a tool must only ever require a JSON/YAML configuration.

Instructions for the Assistant: Refer to the existing loader.py and studio_backend.py patterns for all new feature implementations. Use the "Admin Hook" pattern for any cross-process synchronization. Maintain the vanilla JS + Bootstrap 5 stack for the frontend to ensure high performance and easy maintainability.

RoadMap:
MCP Studio Future Roadmap
Version 2: Onboarding & Governance Core
Focus: Speeding up tool creation while re-integrating the access controls from your manual version.
cURL-to-Tool Instant Converter: Automatically parses pasted cURL commands into methods, headers, and params so you don't have to type them manually. [Partially Completed]
OpenAPI/Swagger URL Importer: Bulk-imports multiple API endpoints from a documentation link directly into your draft list to save setup time.[Hold for Now]
Visual Risk & Access Toggler: A simple UI checkbox/dropdown system to assign risk levels and user permissions to tools, just like your Version 1 manual code.[Completed]
Response Schema Preview: Displays the raw API output in a clean JSON tree during testing so you can confirm the data structure is correct before publishing.[Hold for Now]
Version 3: Intelligence & Data Refining
Focus: Making tools "smarter" for the LLM and cleaning up the data it receives.
AI-Assisted Descriptions: Uses an LLM to write clear, descriptive text for tools and parameters, ensuring the model knows exactly when and how to call them.
JSON Response Filtering: A checklist that lets you pick only the essential data fields to send back to the LLM, preventing "context bloat" and saving tokens.
Global Header Presets: A central "vault" to store API keys and auth tokens once so they automatically apply to all tools in the studio.
Input Validation Rules: Lets you set constraints (like "must be a number" or "max 100 characters") in the UI to stop the LLM from sending invalid requests.
Version 4: Team Collaboration & Scaling
Focus: Turning the studio into a shared environment for your whole team.
Tool Versioning & Rollback: Keeps a history of every config change, allowing you to quickly revert to a working version if a new update breaks the tool.
Visual Tool Chaining: A drag-and-drop flow builder to link tools together (e.g., use the output of a "Search User" tool as the input for a "Get Orders" tool).
Draft Review & Promotion: A staging area where a manager can approve "Draft" tools created by the team before they are published to the live server.
Category Tagging & Discovery: Organizes tools into searchable folders (e.g., #Payments, #Inventory) so different teams can find and reuse each other's work.
Version 5: Performance & Maintenance
Focus: Keeping the "Central Studio" healthy and optimized for production.
Live Execution Logs: A real-time monitor within Streamlit that shows exactly which tools are being triggered by the AI and their success/fail status.
Latency & Error Analytics: Provides visual charts showing which APIs are slow or failing often, helping you spot backend issues early.
Mock Response Builder: Allows you to define "fake" data for a tool so you can keep building your AI workflow even if the actual API isn't finished yet.
Auto-Fix Suggestions: Analyzes failed tool calls and suggests UI configuration changes (like switching from GET to POST) to fix the error automatically.

