 color: var(--text-muted);
 margin-top: 2px;
 }

 .btn-new-tool {
 margin: 0.85rem 1rem;
 padding: 0.55rem 1rem;
 border-radius: var(--radius);
 font-weight: 600;
 font-size: 0.78rem;
 background: linear-gradient(135deg, var(--accent), #7c3aed);
 border: none;
 color: #fff;
 transition: var(--transition);
 }

 .btn-new-tool:hover {
 transform: translateY(-1px);
 box-shadow: 0 6px 20px var(--accent-glow);
 color: #fff;
 }

 .sidebar-section-label {
 font-size: 0.58rem;
 text-transform: uppercase;
 letter-spacing: 0.12em;
 font-weight: 700;
 color: var(--text-muted);
 padding: 0.85rem 1.25rem 0.35rem;
 }

 .sidebar-tools { overflow-y: auto; flex: 1; padding-bottom: 1rem; }

 .sidebar-tools .nav-link {
 color: var(--text-secondary);
 font-size: 0.8rem;
 font-weight: 500;
 padding: 0.4rem 1.1rem;
 margin: 1px 0.6rem;
 border-radius: 8px;
 transition: var(--transition);
 display: flex;
 align-items: center;
 gap: 0.55rem;
 position: relative;
 }

 .sidebar-tools .nav-link:hover { background: rgba(255,255,255,0.05); color: var(--text-primary); }

 .sidebar-tools .nav-link.active {
 background: rgba(99,102,241,0.12);
 color: var(--accent-light);
 }

 .sidebar-tools .nav-link.active::before {
 content: '';
 position: absolute;
 left: 0; top: 50%;
 transform: translateY(-50%);
 width: 3px; height: 60%;
 background: var(--accent);
 border-radius: 0 3px 3px 0;
 }

 .status-dot {
 width: 6px; height: 6px;
 border-radius: 50%;
 flex-shrink: 0;
 }

 .status-dot.published { background: var(--green); box-shadow: 0 0 6px var(--green-glow); }
 .status-dot.draft { background: var(--amber); box-shadow: 0 0 6px rgba(245,158,11,0.25); }

 .sidebar-footer {
 padding: 0.85rem 1.25rem;
 border-top: 1px solid var(--glass-border);
 font-size: 0.68rem;
 color: var(--text-muted);
 }

 .sidebar-empty {
 padding: 0.4rem 1.25rem;
 font-size: 0.75rem;
 color: var(--text-muted);
 font-style: italic;
 }

 .sidebar-toggle {
 display: none;
 position: fixed;
 top: 0.85rem; left: 0.85rem;
 z-index: 200;
 width: 38px; height: 38px;
 border-radius: 10px;
 border: 1px solid var(--glass-border);
 background: rgba(13,13,26,0.92);
 backdrop-filter: blur(12px);
 color: var(--text-primary);
 font-size: 0.95rem;
 cursor: pointer;
 }

 .sidebar-overlay {
 display: none;
 position: fixed;
 inset: 0;
 background: rgba(0,0,0,0.55);
 z-index: 99;
 }

 .server-status {
 display: flex;
 align-items: center;
 gap: 6px;
 }

 .server-status .dot {
 width: 6px; height: 6px;
 border-radius: 50%;
 background: var(--text-muted);
 }

 .server-status .dot.online {
 background: var(--green);
 animation: pulse-glow 2s ease-in-out infinite;
 }

 .server-status .dot.offline { background: var(--red); }

 @keyframes pulse-glow {
 0%, 100% { box-shadow: 0 0 4px var(--green-glow); }
 50% { box-shadow: 0 0 12px var(--green-glow); }
 }

 /* ===== MAIN ===== */
 .main-content {
 margin-left: var(--sidebar-w);
 padding: 2rem 2.5rem 4rem;
 position: relative;
 z-index: 1;
 min-height: 100vh;
 }

 .page-header {
 display: flex;
 justify-content: space-between;
 align-items: flex-end;
 padding-bottom: 1.25rem;
 margin-bottom: 1.75rem;
 border-bottom: 1px solid var(--glass-border);
 }

 .page-header h2 {
 font-size: 1.4rem;
 font-weight: 700;
 letter-spacing: -0.02em;
 margin: 0;
 }

 .page-header .subtitle {
 font-size: 0.8rem;
 color: var(--text-muted);
 margin-top: 3px;
 }

 .btn-curl-import {
 background: var(--bg-card);
 border: 1px solid var(--glass-border);
 color: var(--text-secondary);
 font-size: 0.78rem;
 font-weight: 500;
 padding: 0.45rem 0.9rem;
 border-radius: var(--radius);
 transition: var(--transition);
 }

 .btn-curl-import:hover {
 border-color: rgba(245,158,11,0.3);
 background: rgba(245,158,11,0.06);
 color: var(--amber);
 }

 /* ===== WIZARD STEPPER ===== */
 .wizard-stepper {
 display: flex;
 align-items: flex-start;
 justify-content: center;
 gap: 0;
 margin-bottom: 2.5rem;
 position: relative;
 padding: 0 1rem;
 }

 .wizard-step {
 display: flex;
 flex-direction: column;
 align-items: center;
 flex: 1;
 position: relative;
 cursor: pointer;
 user-select: none;
 }

 .wizard-step .step-node {
 width: 40px; height: 40px;
 border-radius: 50%;
 display: flex;
 align-items: center;
 justify-content: center;
 font-size: 0.8rem;
 font-weight: 700;
 border: 2px solid rgba(255,255,255,0.1);
 background: var(--bg-surface);
 color: var(--text-muted);
 transition: var(--transition);
 position: relative;
 z-index: 2;
 }

 .wizard-step .step-label {
 margin-top: 0.6rem;
 font-size: 0.7rem;
 font-weight: 600;
 color: var(--text-muted);
 text-align: center;
 transition: var(--transition);
 white-space: nowrap;
 }

 /* Connector line between steps */
 .wizard-step:not(:last-child)::after {
 content: '';
 position: absolute;
 top: 20px;
 left: calc(50% + 24px);
 width: calc(100% - 48px);
 height: 2px;
 background: rgba(255,255,255,0.08);
 z-index: 1;
 transition: background 0.5s ease;
 }

 /* Step states */
 .wizard-step.active .step-node {
 border-color: var(--accent);
 background: rgba(99,102,241,0.15);
 color: var(--accent-light);
 box-shadow: 0 0 20px var(--accent-glow), 0 0 40px rgba(99,102,241,0.1);
 }

 .wizard-step.active .step-label { color: var(--accent-light); }

 .wizard-step.completed .step-node {
 border-color: var(--green);
 background: rgba(34,197,94,0.15);
 color: var(--green);
 }

 .wizard-step.completed .step-label { color: var(--green); }

 .wizard-step.completed:not(:last-child)::after {
 background: linear-gradient(90deg, var(--green), rgba(34,197,94,0.3));
 }

 .wizard-step.accessible { cursor: pointer; }
 .wizard-step.locked { cursor: not-allowed; opacity: 0.5; }

 .wizard-step.accessible:hover .step-node {
 border-color: rgba(255,255,255,0.2);
 background: rgba(255,255,255,0.06);
 }

 /* ===== STEP PANELS ===== */
 .step-panels-wrapper {
 position: relative;
 overflow: hidden;
 }

 .step-panel {
 display: none;
 animation: panelFadeIn 0.35s ease-out;
 }

 .step-panel.active { display: block; }

 @keyframes panelFadeIn {
 from { opacity: 0; transform: translateY(10px); }
 to { opacity: 1; transform: translateY(0); }
 }

 .glass-panel {
 background: var(--bg-card);
 border: 1px solid var(--glass-border);
 border-radius: var(--radius-lg);
 backdrop-filter: blur(12px);
 overflow: hidden;
 }

 .glass-panel .panel-title {
 padding: 1.15rem 1.5rem;
 border-bottom: 1px solid var(--glass-border);
 font-weight: 600;
 font-size: 0.85rem;
 display: flex;
 align-items: center;
 gap: 0.6rem;
 }

 .glass-panel .panel-title .icon-box {
 width: 28px; height: 28px;
 border-radius: 7px;
 background: rgba(99,102,241,0.12);
 color: var(--accent-light);
 display: flex;
 align-items: center;
 justify-content: center;
 font-size: 0.75rem;
 }

 .glass-panel .panel-body {
 padding: 1.5rem;
 }

 /* ===== FORMS ===== */
 .form-label {
 font-size: 0.72rem;
 font-weight: 600;
 color: var(--text-secondary);
 margin-bottom: 0.3rem;
 text-transform: uppercase;
 letter-spacing: 0.04em;
 }

 .form-label.required::after {
 content: ' *';
 color: var(--red);
 }

 .form-control, .form-select {
 background-color: rgba(255,255,255,0.04) !important;
 border: 1px solid rgba(255,255,255,0.1) !important;
 border-radius: 8px !important;
 color: var(--text-primary) !important;
 font-size: 0.85rem;
 padding: 0.55rem 0.8rem;
 transition: var(--transition);
 }

 .form-control::placeholder { color: var(--text-muted) !important; }

 .form-control:focus, .form-select:focus {
 background-color: rgba(99,102,241,0.05) !important;
 border-color: rgba(99,102,241,0.4) !important;
 box-shadow: 0 0 0 3px rgba(99,102,241,0.1), 0 0 20px rgba(99,102,241,0.05) !important;
 color: var(--text-primary) !important;
 }

 /* FIX: Custom select arrow — override Bootstrap's default completely */
 .form-select {
 background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 16 16'%3e%3cpath fill='none' stroke='%2394a3b8' stroke-linecap='round' stroke-linejoin='round' stroke-width='2' d='m4 6 4 4 4-4'/%3e%3c/svg%3e") !important;
 background-repeat: no-repeat !important;
 background-position: right 0.75rem center !important;
 background-size: 16px 12px !important;
 padding-right: 2.5rem !important;
 -webkit-appearance: none !important;
 -moz-appearance: none !important;
 appearance: none !important;
 }

 .form-select option {
 background: #1a1a2e;
 color: var(--text-primary);
 padding: 8px;
 }

 .form-text {
 font-size: 0.7rem;
 color: var(--text-muted);
 margin-top: 0.3rem;
 }

 .form-text.text-danger { color: rgba(239,68,68,0.75) !important; }

 .form-check-input {
 background-color: rgba(255,255,255,0.08);
 border-color: rgba(255,255,255,0.2);
 }

 .form-check-input:checked { background-color: var(--accent); border-color: var(--accent); }
 .form-check-input:focus { box-shadow: 0 0 0 3px rgba(99,102,241,0.15); border-color: var(--accent); }
 .form-check-label { color: var(--text-secondary); font-size: 0.85rem; }

 /* ===== STEP NAVIGATION ===== */
 .step-nav {
 display: flex;
 justify-content: space-between;
 align-items: center;
 margin-top: 1.75rem;
 padding-top: 1.25rem;
 border-top: 1px solid var(--glass-border);
 }

 .btn-step {
 font-weight: 600;
 font-size: 0.82rem;
 padding: 0.55rem 1.4rem;
 border-radius: var(--radius);
 transition: var(--transition);
 display: inline-flex;
 align-items: center;
 gap: 0.5rem;
 }

 .btn-step-back {
 background: transparent;
 border: 1px solid var(--glass-border);
 color: var(--text-secondary);
 }

 .btn-step-back:hover {
 background: rgba(255,255,255,0.04);
 border-color: rgba(255,255,255,0.15);
 color: var(--text-primary);
 }

 .btn-step-next {
 background: linear-gradient(135deg, var(--accent), #7c3aed);
 border: none;
 color: #fff;
 }

 .btn-step-next:hover {
 transform: translateY(-1px);
 box-shadow: 0 6px 20px var(--accent-glow);
 color: #fff;
 }

 .btn-step-next:disabled {
 opacity: 0.4;
 cursor: not-allowed;
 transform: none !important;
 box-shadow: none !important;
 }

 .btn-skip {
 background: transparent;
 border: none;
 color: var(--text-muted);
 font-size: 0.78rem;
 font-weight: 500;
 padding: 0.5rem 0.8rem;
 transition: var(--transition);
 }

 .btn-skip:hover { color: var(--text-secondary); }

 /* ===== PARAMS TABLE ===== */
 .param-table-wrap { overflow-x: auto; }

 /* Override Bootstrap CSS variables inside the table scope */
 .param-table-wrap,
 .param-table-wrap .table {
 --bs-body-bg: transparent;
 --bs-body-color: #e2e8f0;
 --bs-border-color: rgba(255,255,255,0.08);
 --bs-table-bg: transparent;
 --bs-table-color: #e2e8f0;
 --bs-table-border-color: rgba(255,255,255,0.06);
 --bs-table-hover-bg: rgba(255,255,255,0.03);
 --bs-table-accent-bg: transparent;
 font-size: 0.82rem;
 margin-bottom: 0;
 color: var(--text-primary);
 }

 .param-table-wrap .table > :not(caption) > * > * {
 background-color: transparent !important;
 box-shadow: none !important;
 color: var(--text-primary) !important;
 }

 .param-table-wrap .table thead th {
 background-color: rgba(255,255,255,0.03) !important;
 color: var(--text-muted) !important;
 font-weight: 600;
 font-size: 0.68rem;
 text-transform: uppercase;
 letter-spacing: 0.06em;
 border-bottom: 1px solid var(--glass-border) !important;
 padding: 0.6rem 0.7rem;
 }

 .param-table-wrap .table td {
 border-bottom: 1px solid rgba(255,255,255,0.04) !important;
 padding: 0.55rem 0.45rem;
 vertical-align: middle;
 }

 .param-table-wrap .table tbody tr { transition: background-color 0.15s; }
 .param-table-wrap .table tbody tr:hover { background-color: rgba(255,255,255,0.025) !important; }

 /* Input + Select overrides — target Bootstrap's exact property names */
 .param-table-wrap .table .form-control,
 .param-table-wrap .table .form-select,
 .param-table-wrap .table .form-control.form-control-sm,
 .param-table-wrap .table .form-select.form-select-sm,
 .param-table-wrap .table td input.form-control,
 .param-table-wrap .table td select.form-select,
 .param-table-wrap .table td textarea.form-control {
 background-color: rgba(255,255,255,0.06) !important;
 border: 1px solid rgba(255,255,255,0.12) !important;
 color: #e2e8f0 !important;
 padding: 0.38rem 0.55rem !important;
 font-size: 0.82rem !important;
 border-radius: 6px !important;
 box-shadow: none !important;
 }

 .param-table-wrap .table td input.form-control::placeholder,
 .param-table-wrap .table td textarea.form-control::placeholder {
 color: #64748b !important;
 }

 .param-table-wrap .table td input.form-control:focus,
 .param-table-wrap .table td select.form-select:focus,
 .param-table-wrap .table td textarea.form-control:focus {
 background-color: rgba(99,102,241,0.1) !important;
 border-color: rgba(99,102,241,0.5) !important;
 box-shadow: 0 0 0 2px rgba(99,102,241,0.12) !important;
 color: #f1f5f9 !important;
 }

 .param-table-wrap .table td select.form-select {
 padding-right: 2rem !important;
 background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 16 16'%3e%3cpath fill='none' stroke='%2394a3b8' stroke-linecap='round' stroke-linejoin='round' stroke-width='2' d='m4 6 4 4 4-4'/%3e%3c/svg%3e") !important;
 background-repeat: no-repeat !important;
 background-position: right 0.5rem center !important;
 background-size: 14px 10px !important;
 }

 .btn-delete-param {
 width: 26px; height: 26px;
 border-radius: 6px;
 border: none;
 background: transparent;
 color: var(--text-muted);
 transition: var(--transition);
 display: flex;
 align-items: center;
 justify-content: center;
 padding: 0;
 }

 .btn-delete-param:hover { background: rgba(239,68,68,0.12); color: var(--red); }

 .btn-add-param {
 font-size: 0.76rem;
 font-weight: 600;
 padding: 0.38rem 0.75rem;
 border-radius: 8px;
 background: rgba(255,255,255,0.05);
 border: 1px dashed rgba(255,255,255,0.12);
 color: var(--text-secondary);
 transition: var(--transition);
 }

 .btn-add-param:hover {
 background: rgba(99,102,241,0.08);
 border-color: rgba(99,102,241,0.3);
 color: var(--accent-light);
 }

 .param-empty {
 text-align: center;
 padding: 2rem 1rem;
 color: var(--text-muted);
 font-size: 0.82rem;
 }

 .param-empty .empty-icon {
 width: 44px; height: 44px;
 border-radius: 12px;
 background: rgba(255,255,255,0.04);
 display: inline-flex;
 align-items: center;
 justify-content: center;
 margin-bottom: 0.65rem;
 }

 /* ===== TEST & PUBLISH (Step 4) ===== */
 .publish-zone {
 background: linear-gradient(135deg, rgba(99,102,241,0.05), rgba(139,92,246,0.03));
 border: 1px solid rgba(99,102,241,0.12);
 border-radius: var(--radius-lg);
 padding: 1.5rem;
 }

 .test-args-box {
 background: rgba(0,0,0,0.2);
 border: 1px solid var(--glass-border);
 border-radius: var(--radius);
 padding: 1.15rem;
 margin-bottom: 1.25rem;
 }

 .test-args-box h6 {
 font-size: 0.72rem;
 font-weight: 700;
 text-transform: uppercase;
 letter-spacing: 0.05em;
 color: var(--text-muted);
 margin-bottom: 0.9rem;
 }

 /* File picker for test args */
 .file-picker-wrap {
 position: relative;
 }

 .file-picker-wrap .form-control[type="file"] {
 padding: 0.4rem 0.6rem;
 font-size: 0.8rem;
 cursor: pointer;
 }

 .file-picker-wrap .form-control[type="file"]::file-selector-button {
 background: linear-gradient(135deg, var(--accent), #7c3aed);
 color: #fff;
 border: none;
 padding: 0.3rem 0.75rem;
 border-radius: 6px;
 font-size: 0.75rem;
 font-weight: 600;
 margin-right: 0.75rem;
 cursor: pointer;
 transition: var(--transition);
 }

 .file-picker-wrap .form-control[type="file"]::file-selector-button:hover {
 box-shadow: 0 2px 10px var(--accent-glow);
 }

 .file-picker-wrap .file-status {
 font-size: 0.7rem;
 margin-top: 0.3rem;
 display: flex;
 align-items: center;
 gap: 0.4rem;
 }

 .file-picker-wrap .file-status.uploading { color: var(--amber); }
 .file-picker-wrap .file-status.uploaded { color: var(--green); }
 .file-picker-wrap .file-status.error { color: var(--red); }

 .btn-test {
 background: rgba(255,255,255,0.08);
 border: 1px solid rgba(255,255,255,0.15);
 color: var(--text-primary);
 font-weight: 600;
 font-size: 0.82rem;
 padding: 0.55rem 1.2rem;
 border-radius: var(--radius);
 transition: var(--transition);
 }

 .btn-test:hover {
 background: rgba(255,255,255,0.12);
 color: #fff;
 transform: translateY(-1px);
 }

 .btn-save-draft {
 background: transparent;
 border: 1px solid var(--glass-border);
 color: var(--text-secondary);
 font-weight: 600;
 font-size: 0.82rem;
 padding: 0.55rem 1rem;
 border-radius: var(--radius);
 transition: var(--transition);
 }

 .btn-save-draft:hover {
 border-color: rgba(255,255,255,0.18);
 background: rgba(255,255,255,0.04);
 color: var(--text-primary);
 }

 .btn-publish-live {
 background: linear-gradient(135deg, var(--green), #16a34a);
 border: none;
 color: #fff;
 font-weight: 600;
 font-size: 0.82rem;
 padding: 0.55rem 1.2rem;
 border-radius: var(--radius);
 transition: var(--transition);
 }

 .btn-publish-live:disabled {
 opacity: 0.35;
 cursor: not-allowed;
 transform: none !important;
 box-shadow: none !important;
 }

 .btn-publish-live:not(:disabled):hover {
 transform: translateY(-1px);
 box-shadow: 0 6px 20px var(--green-glow);
 color: #fff;
 }

 /* ===== TEST CONSOLE ===== */
 .test-console {
 background: #08080f;
 border: 1px solid rgba(255,255,255,0.05);
 border-radius: var(--radius);
 padding: 1rem 1.15rem;
 max-height: 400px;
 overflow-y: auto;
 font-family: 'JetBrains Mono', monospace;
 font-size: 0.76rem;
 line-height: 1.7;
 color: var(--green);
 margin-top: 1.15rem;
 }

 .test-console .error-text { color: var(--red); }
 .test-console .sys-text { color: var(--text-muted); }
 .test-console pre {
 color: var(--text-secondary);
 font-family: 'JetBrains Mono', monospace;
 font-size: 0.74rem;
 white-space: pre-wrap;
 word-break: break-word;
 margin: 0;
 }

 /* ===== MODAL ===== */
 .modal-content {
 background: var(--bg-surface);
 border: 1px solid var(--glass-border);
 border-radius: var(--radius-lg);
 box-shadow: 0 25px 60px rgba(0,0,0,0.5);
 }

 .modal-header { border-bottom: 1px solid var(--glass-border); padding: 1.15rem 1.5rem; }
 .modal-title { font-weight: 700; font-size: 0.95rem; color: var(--text-primary); }
 .modal-body { padding: 1.5rem; }

 .modal-body textarea {
 background: rgba(255,255,255,0.04) !important;
 border: 1px solid var(--glass-border) !important;
 color: var(--text-primary) !important;
 font-family: 'JetBrains Mono', monospace;
 font-size: 0.8rem;
 }

 .modal-body textarea:focus {
 background: rgba(99,102,241,0.04) !important;
 border-color: rgba(99,102,241,0.3) !important;
 box-shadow: 0 0 0 3px rgba(99,102,241,0.08) !important;
 }

 .modal-footer { border-top: 1px solid var(--glass-border); padding: 1rem 1.5rem; }

 .modal-footer .btn-secondary {
 background: rgba(255,255,255,0.06);
 border: 1px solid var(--glass-border);
 color: var(--text-secondary);
 }

 .modal-footer .btn-primary-modal {
 background: linear-gradient(135deg, var(--accent), #7c3aed);
 border: none;
 color: #fff;
 font-weight: 600;
 padding: 0.5rem 1.2rem;
 border-radius: 8px;
 transition: var(--transition);
 }

 .modal-footer .btn-primary-modal:hover {
 box-shadow: 0 4px 16px var(--accent-glow);
 }

 .btn-close { filter: invert(1) grayscale(100%) brightness(200%); opacity: 0.5; }

 /* ===== TOAST ===== */
 .toast { border-radius: var(--radius) !important; font-size: 0.82rem; font-weight: 500; }

 .spinner-border-sm { width: 0.85rem; height: 0.85rem; border-width: 2px; }

 /* ===== STEP SUMMARY BADGES (visible on completed steps in stepper) ===== */
 .step-summary {
 margin-top: 0.3rem;
 font-size: 0.6rem;
 color: var(--text-muted);
 max-width: 120px;
 text-align: center;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 }

 /* ===== SCROLLBAR ===== */
 ::-webkit-scrollbar { width: 5px; height: 5px; }
 ::-webkit-scrollbar-track { background: transparent; }
 ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.08); border-radius: 4px; }
 ::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.15); }

 /* ===== RESPONSIVE ===== */
 @media (max-width: 991.98px) {
 .sidebar { transform: translateX(-100%); }
 .sidebar.open { transform: translateX(0); }
 .sidebar-overlay.active { display: block; }
 .sidebar-toggle { display: flex; align-items: center; justify-content: center; }
 .main-content { margin-left: 0; padding: 1.25rem; padding-top: 4rem; }
