# helpers/helper.py

import os
import json
import base64
import requests
import re
import time
import threading
import tempfile
from typing import Any, Dict
from bs4 import BeautifulSoup
from urllib.parse import urljoin
from loguru import logger
from dotenv import load_dotenv

load_dotenv()

# ---------------------------------------------------------------------
# SKYc token management (centralized here)
# ---------------------------------------------------------------------
SKYC_AUTH_URL = os.getenv("SKYC_AUTH_URL")
SKYC_INITIAL_BEARER = os.getenv("SKYC_INITIAL_BEARER")
SKYC_APP_ID = os.getenv("SKYC_APP_ID")
SKYC_APP_KEY = os.getenv("SKYC_APP_KEY")
SKYC_EXPIRY_AT = os.getenv("SKYC_EXPIRY_AT")

# How often to force-refresh the token, in minutes
REFRESH_INTERVAL_MINUTES = 58
_refresh_interval_secs = REFRESH_INTERVAL_MINUTES * 60

_skyc_token = None
_skyc_token_timestamp = 0.0
_skyc_token_lock = threading.Lock()

def get_skyc_token(force_refresh: bool = False) -> str:
 """
 Fetches (and caches) a SKYc auth token.
 - On first call or if older than REFRESH_INTERVAL_MINUTES, obtains a new token.
 - Retries once on HTTP 401/403 or network error.
 - Never spawns new threads here.

 Args:
 force_refresh: if True, ignore cache and always fetch a new token.

 Returns:
 A valid SKYc auth token string.

 Raises:
 RuntimeError if authentication fails or required env vars are missing.
 """
 global _skyc_token, _skyc_token_timestamp

 with _skyc_token_lock:
 now = time.time()
 # Return cached token if still fresh
 if not force_refresh and _skyc_token and (now - _skyc_token_timestamp) < _refresh_interval_secs:
 return _skyc_token

 # Validate environment
 if not (SKYC_INITIAL_BEARER and SKYC_APP_ID and SKYC_APP_KEY and SKYC_AUTH_URL):
 raise RuntimeError("Missing SKYc auth environment variables")

 headers = {"Authorization": f"Bearer {SKYC_INITIAL_BEARER}"}
 data = {
 "app_id": SKYC_APP_ID,
 "expiry_at": SKYC_EXPIRY_AT,
 "app_key": SKYC_APP_KEY,
 "send_token":"1"
 }

 logger.info("Requesting new SKYc auth token (forced={})", force_refresh)

 last_exc = None
 for attempt in range(2):
 try:
 resp = requests.post(SKYC_AUTH_URL, headers=headers, data=data, timeout=10)
 except requests.RequestException as e:
 last_exc = e
 logger.warning("SKYc auth HTTP error on attempt {}: {}", attempt+1, e)
 continue

 # If unauthorized on first try, retry once
 if resp.status_code in (401, 403) and attempt == 0:
 logger.warning("SKYc auth returned {}, retrying", resp.status_code)
 continue

 try:
 resp.raise_for_status()
 payload = resp.json()
 except Exception as e:
 last_exc = e
 logger.error("SKYc auth response invalid on attempt {}: {}", attempt+1, e)
 continue

 token = payload.get("token")
 if not token:
 last_exc = RuntimeError("No token field in SKYc auth response")
 logger.error("SKYc auth missing token on attempt {}", attempt+1)
 continue

 # Success: cache and record timestamp
 _skyc_token = token
 _skyc_token_timestamp = now
 next_time = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(now + _refresh_interval_secs))
 logger.info("SKYc token refreshed; next refresh earliest at {}", next_time)
 return _skyc_token

 # All attempts failed
 raise RuntimeError(f"Failed to fetch SKYc auth token: {last_exc}")

def _refresh_loop():
 """Background thread: sleep for interval, then force‐refresh the token."""
 while True:
 time.sleep(_refresh_interval_secs)
 try:
 get_skyc_token(force_refresh=True)
 except Exception as e:
 logger.error("Background SKYc token refresh failed: {}", e)

# Start a single daemon thread for background refresh
threading.Thread(target=_refresh_loop, daemon=True).start()

# ---------------------------------------------------------------------
# Dynamic tool configs (tools/dynamic_configs): value normalization & HTTP encoding
# ---------------------------------------------------------------------

def normalize_dynamic_array_default(raw: Any) -> list[str]:
 """Coerce JSON / CSV-ish defaults into list[str] for parameter type ``array``."""
 if raw is None:
 return []
 if isinstance(raw, list):
 return [str(x) for x in raw]
 if isinstance(raw, str):
 s = raw.strip()
 if not s:
 return []
 if s.startswith("["):
 try:
 parsed = json.loads(s)
 if isinstance(parsed, list):
 return [str(x) for x in parsed]
 except json.JSONDecodeError:
 pass
 return [p.strip() for p in s.split(",") if p.strip()]
 return [str(raw)]

def serialize_dynamic_param_for_query(
 value: Any, param_info: Dict[str, Any] | None = None
) -> str:
 """Turn a Python value into a string for URL query strings or multipart form fields.

 ``param_info`` is for per-parameter options (e.g. ``query_format``); today all
 list values are comma-joined regardless.
 """
 if param_info and param_info.get("query_format") not in (None, "comma_separated"):
 logger.debug(
 "serialize_dynamic_param_for_query: unsupported query_format={!r}, using default",
 param_info.get("query_format"),
 )
 if isinstance(value, bool):
 return str(value).lower()
 if isinstance(value, (int, float)) and not isinstance(value, bool):
 return str(value)
 if isinstance(value, list):
 return ",".join(str(x) for x in value)
 return str(value)

def flatten_dynamic_params_for_query_or_form(
 native: Dict[str, Any], params_cfg: Dict[str, Any]
) -> Dict[str, str]:
 """Build a flat str->str map for GET params or urlencoded multipart (not JSON body)."""
 out: Dict[str, str] = {}
 for key, value in native.items():
 pinfo = params_cfg.get(key, {}) or {}
 out[key] = serialize_dynamic_param_for_query(value, pinfo)
 return out

def extract_and_pretty(tool_result: Any) -> str:
 """
 description:
 Given an MCP CallToolResult (or similar), extract its JSON payload
 (either via tool_result.result or via content[0].text) and pretty-print it.
 On parse failures, returns an error string. If the raw text begins with
 "Unknown tool: …", returns an explanation tied to ENABLED_TOOLS / server registration.

 Args:
 tool_result: The raw CallToolResult returned by the MCP client.

 Returns:
 A human-readable JSON string or friendly error message.
 """
 if hasattr(tool_result, "result"):
 try:
 return json.dumps(tool_result.result, indent=2)
 except Exception:
 pass

 try:
 raw = tool_result.content[0].text.strip()
 if raw.startswith("Unknown tool:"):
 return (
 f"{raw} — The server has no tool registered under that name. "
 "If you use ENABLED_TOOLS, include this tool (or leave the list empty); "
 "check DISABLED_TOOLS as well. Restart the server after changing .env."
 )
 parsed = json.loads(raw)
 return json.dumps(parsed, indent=2)
 except Exception as e:
 return f"Cannot extract/parse JSON: {e}"

def read_image_as_b64(path: str) -> str:
 """
 description:
 Read a local image file or accept a raw Base64/URL string.

 Args:
 path:
 - if it begins with "http://" or "https://", return unchanged
 - else if it's a filesystem path, load and base64-encode it
 - else assume it's already a base64 blob

 Returns:
 A base64 string or URL (unchanged), or "" on error.
 """
 if path.startswith(("http://", "https://")):
 return path
 if os.path.isfile(path):
 try:
 b = open(path, "rb").read()
 return base64.b64encode(b).decode("ascii")
 except Exception as e:
 print(f"[read_image_as_b64] ⚠️ Error reading {path}: {e}")
 return ""
 return path # assume already base64

def load_from_url(source: str, input_type: str) -> str: 
 """
 description:
 Given a URL, base64 blob, or local file path, return a base64-encoded image blob.
 - If input_type == "b64", returns source unchanged.
 - If input_type == "url":
 1. If source is a local file path, load and encode it
 2. If the URL path ends in a common image extension, download directly.
 3. Else, fetch the HTML, parse the first non-logo <img> tag
 whose src has an image extension, and download that.
 4. Fallback: try the original URL as an image.
 - input_type == "pdf": return local path unchanged
 - input_type == "url_pdf": download PDF to temp file → return its path

 Args:
 source: HTTP/HTTPS URL, local file path, or raw base64 string.
 input_type: "url", "b64", "pdf" or "url_pdf".

 Returns:
 Base64-encoded image string, or local PDF path, or "" on error.
 """
 if input_type == "b64" or input_type == "pdf":
 return source

 if input_type == "url_pdf":
 try:
 r = requests.get(source, timeout=15)
 r.raise_for_status()
 suffix = os.path.splitext(source)[1] or ".pdf"
 fd, path = tempfile.mkstemp(suffix=suffix)
 with os.fdopen(fd, "wb") as f:
 f.write(r.content)
 return path
 except Exception as e:
 print(f"[load_from_url] ⚠️ PDF download failed {source!r}: {e}")
 return ""

 # input_type == "url" (images)
 if input_type != "url":
 print(f"[load_from_url] ⚠️ Unknown input_type: {input_type}")
 return ""

 # 0) Check if source is a local file path first
 if os.path.isfile(source):
 try:
 with open(source, 'rb') as f:
 return base64.b64encode(f.read()).decode("ascii")
 except Exception as e:
 print(f"[load_from_url] ⚠️ Failed to read local file {source!r}: {e}")
 return ""

 # 1) Direct-image URL?
 if re.search(r'\.(jpe?g|png|gif|bmp|webp)(?:\?.*)?$', source, re.IGNORECASE):
 try:
 r = requests.get(source, timeout=10); r.raise_for_status()
 return base64.b64encode(r.content).decode("ascii")
 except Exception as e:
 print(f"[load_from_url] ⚠️ Failed image download {source!r}: {e}")

 # 2) Scrape HTML for first non-logo <img>
 try:
 page = requests.get(source, timeout=10); page.raise_for_status()
 soup = BeautifulSoup(page.text, "html.parser")
 for img in soup.find_all("img", src=True):
 src2 = img["src"]
 if re.search(r'logo|icon|favicon', src2, re.IGNORECASE): continue
 if not re.search(r'\.(jpe?g|png|gif|bmp|webp)', src2, re.IGNORECASE): continue
 full = urljoin(source, src2)
 try:
 r2 = requests.get(full, timeout=10); r2.raise_for_status()
 return base64.b64encode(r2.content).decode("ascii")
 except:
 continue
 # fallback original URL as image
 r3 = requests.get(source, timeout=10); r3.raise_for_status()
 return base64.b64encode(r3.content).decode("ascii")
 except Exception as e:
 print(f"[load_from_url] ⚠️ Could not scrape image from {source!r}: {e}")
 return ""

