class RequestLoggingMiddleware:
 """
 Pure ASGI middleware for request handling.

 Unlike BaseHTTPMiddleware, this middleware doesn't buffer responses,
 making it compatible with SSE streaming endpoints.

 Logging is minimal - only errors are logged.
 """

 def __init__(self, app: ASGIApp):
 self.app = app

 async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
 if scope["type"] != "http":
 await self.app(scope, receive, send)
 return

 path = scope.get("path", "/")

 try:
 await self.app(scope, receive, send)
 except Exception as e:
 logger.error("Exception in request processing for {}: {}", path, str(e))
 raise

