def setup_tool_configuration():
 """Setup tool configuration from environment variables"""
 # Read ENV vars with JSON-style list for ENABLED_TOOLS
 try:
 ENABLED_TOOLS = {n.lower() for n in json.loads(os.getenv("ENABLED_TOOLS", "[]"))}
 except (json.JSONDecodeError, TypeError):
 ENABLED_TOOLS = set()

 disabled_env = os.getenv("DISABLED_TOOLS", "").strip()
 DISABLED_TOOLS = {n.strip().lower() for n in disabled_env.split(",") if n.strip()}

 def tool_allowed(tool_name: str) -> bool:
 """
 Determine whether a tool should be registered based on ENABLED_TOOLS
 and DISABLED_TOOLS environment variables.

 New behavior: All tools are enabled by default unless explicitly disabled.
 ENABLED_TOOLS is now optional - if not set, all tools are enabled.
 """
 low = tool_name.lower()

 # If tool is explicitly disabled, don't allow it
 if low in DISABLED_TOOLS:
 return False

 # If ENABLED_TOOLS is specified and not empty, only allow tools in the list
 if ENABLED_TOOLS and low not in ENABLED_TOOLS:
 return False

 # Default: allow all tools (enable by default)
 return True

 return tool_allowed

