@app.post("/upload")
async def upload_file(
 file: UploadFile = File(...),
 metadata: Optional[str] = Form(None),
 agent_id: Optional[str] = Form("default")
):
 """Upload a file and add it to the RAG database for a specific agent."""
 file_path = None
 try:
 logger.info("[Upload] Starting file upload: filename='{}', agent_id='{}'", file.filename, agent_id)

 # Create uploads directory if it doesn't exist
 os.makedirs("uploads", exist_ok=True)

 # Save the uploaded file
 file_path = f"uploads/{file.filename}"
 content = await file.read()
 file_size = len(content)
 logger.info("[Upload] File received: size={} bytes", file_size)

 with open(file_path, "wb") as buffer:
 buffer.write(content)
 logger.info("[Upload] File saved to: {}", file_path)

 # Parse metadata if provided
 metadata_dict = {}
 if metadata:
 try:
 metadata_dict = json.loads(metadata)
 logger.info("[Upload] Metadata parsed: {}", metadata_dict)
 except json.JSONDecodeError as e:
 logger.warning("[Upload] Invalid metadata JSON, using empty dict: {}", str(e))

 # Add document to database with agent_id
 logger.info("[Upload] Processing document and adding to database...")
 result = add_document_to_db(file_path, metadata_dict, agent_id)

 if result.get("status") == "success":
 chunks_added = result.get("chunks_added", 0)
 logger.info("[Upload] Successfully added document: {} chunks added", chunks_added)
 else:
 error_msg = result.get("message", "Unknown error")
 logger.error("[Upload] Failed to add document to database: {}", error_msg)

 # Delete file after adding to database
 if file_path and os.path.exists(file_path):
 os.remove(file_path)
 logger.info("[Upload] Temporary file deleted: {}", file_path)

 return result

 except json.JSONDecodeError as e:
 error_msg = f"Invalid metadata JSON: {str(e)}"
 logger.error("[Upload] {}", error_msg)
 return {"status": "error", "message": error_msg}
 except Exception as e:
 error_msg = str(e)
 logger.error("[Upload] Error uploading file '{}': {}", file.filename if file else "unknown", error_msg)

 # Clean up file if it exists
 if file_path and os.path.exists(file_path):
 try:
 os.remove(file_path)
 logger.info("[Upload] Cleaned up temporary file: {}", file_path)
 except Exception as cleanup_error:
 logger.warning("[Upload] Failed to cleanup file: {}", str(cleanup_error))

 return {"status": "error", "message": error_msg}

