def _serialize_tool_result(result: Any) -> Any:
 """Best-effort JSON-serializable representation of MCP tool results."""
 try:
 # Common case: iterable of chunks with .text
 if isinstance(result, list):
 out: List[Any] = []
 for item in result:
 if hasattr(item, "text"):
 out.append(getattr(item, "text"))
 elif isinstance(item, (str, int, float, bool, type(None), dict, list)):
 out.append(item)
 else:
 out.append(str(item))
 return out
 # Already JSON-friendly
 if isinstance(result, (str, int, float, bool, type(None), dict, list)):
 return result
 # Fallback
 return str(result)
 except Exception as e:
 logger.error("Failed to serialize tool result: {}", e)
 return str(result)

