import streamlit as st

ROOT_DIR = os.path.dirname(os.path.abspath(__file__))
CONFIG_DIR = os.path.join(ROOT_DIR, "tools", "dynamic_configs")
if ROOT_DIR not in sys.path:
 sys.path.insert(0, ROOT_DIR)

NEW_TOOL_LABEL = "— New tool —"
PARAM_TYPES = ["string", "file", "number", "boolean", "array", "json"] # Added JSON for Phase 2.1
SESSION_PARAMS = "studio_params"
SESSION_PREV_SEL = "_studio_prev_tool_select"
SESSION_FORM_GEN = "studio_form_generation"
SESSION_BOOTSTRAP = "studio_bootstrap"
SESSION_VERIFIED_FP = "studio_verified_cfg_fingerprint"

st.set_page_config(page_title="Dynamic Tool Studio", layout="wide")
st.title("Zero-Code Dynamic Tool Studio")
st.caption(
 "Workflow: choose a tool → expand **2** to define → **3** to test → **4** to save or publish. "
