This is a massive and exciting upgrade. Moving from a Streamlit POC to a decoupled FastAPI + HTML/JS/Bootstrap architecture is exactly what you need for a production-grade, client-facing system. 

 By splitting the Studio into an API backend and a clean frontend, you gain complete control over the UX, eliminate Streamlit's "rerun-the-whole-script" overhead, and set the stage for multi-user collaboration. 

 We will achieve this in three new files (without touching mcp_server_refactored.py or loader.py ): 

 studio_backend.py : A dedicated FastAPI server just for the Studio. It handles file writing, cURL parsing, and triggering the MCP tests. 

 static/index.html : The clean, Bootstrap 5 UI. 

 static/app.js : The vanilla JavaScript that drives the dynamic form and API calls. 

 Let's build it. 

 Step 1: The Studio Backend (FastAPI) 

 Create a new file named studio_backend.py in your root directory. 

 This script imports your existing mcp instance just like Streamlit did, but exposes everything via clean REST APIs. You will run this on a different port (e.g., 8002) so it runs side-by-side with your main MCP server. 

 # studio_backend.py

import os
import json
import hashlib
import shlex
from urllib.parse import urlparse, parse_qsl
from typing import Any, Dict, List, Optional
from fastapi import FastAPI, HTTPException
from fastapi.staticfiles import StaticFiles
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel

# Import existing MCP architecture
from mcp_server_refactored import mcp, setup_tool_configuration
from tools.dynamic_tools.loader import load_dynamic_tools, register_dynamic_tool_from_config

app = FastAPI(title="Zero-Code MCP Studio API")

# Enable CORS for frontend development
app.add_middleware(
 CORSMiddleware,
 allow_origins=["*"],
 allow_credentials=True,
 allow_methods=["*"],
 allow_headers=["*"],
)

CONFIG_DIR = os.path.normpath(os.path.join(os.path.dirname(__file__), "tools", "dynamic_configs"))
os.makedirs(CONFIG_DIR, exist_ok=True)

# --- Pydantic Models for API Requests ---
class CurlRequest(BaseModel):
 curl_cmd: str

class ToolConfig(BaseModel):
 id: Optional[str] = None
 status: str
 name: str
 description: str
 metadata: Dict[str, Any]
 config: Dict[str, Any]
 parameters: Dict[str, Any]

class TestRequest(BaseModel):
 config: ToolConfig
 test_args: Dict[str, Any]

# --- Helper Functions (From previous Studio) ---
def config_filename_for_tool(tool_name: str) -> str:
 safe = "".join(c if c.isalnum() or c in ("-", "_") else "_" for c in tool_name)
 return f"{safe or 'tool'}.json"

# --- API Endpoints ---

@app.get("/api/tools")
async def get_all_tools():
 """Returns a list of all existing tool configurations."""
 tools = []
 for name in sorted(os.listdir(CONFIG_DIR)):
 if name.endswith(".json"):
 try:
 with open(os.path.join(CONFIG_DIR, name), encoding="utf-8") as fp:
 tools.append(json.load(fp))
 except Exception:
 continue
 return {"tools": tools}

@app.post("/api/curl/parse")
async def parse_curl(req: CurlRequest):
 """Parses a cURL command into a Studio-compatible configuration dictionary."""
 curl_cmd = req.curl_cmd.replace('\\\n', ' ').replace('\\\r', ' ').strip()
 if not curl_cmd:
 raise HTTPException(status_code=400, detail="Empty cURL command")

 try:
 tokens = shlex.split(curl_cmd)
 except ValueError as e:
 raise HTTPException(status_code=400, detail=f"Failed to parse cURL syntax: {e}")

 method, url, headers, body, has_data_flag = "GET", "", {}, None, False
 it = iter(tokens)
 for token in it:
 if token.startswith("http"):
 url = token
 elif token in ("-X", "--request"):
 method = next(it, "GET").upper()
 elif token in ("-H", "--header"):
 header_str = next(it, "")
 if ":" in header_str:
 k, v = header_str.split(":", 1)
 headers[k.strip().lower()] = v.strip()
 elif token in ("-d", "--data", "--data-raw", "--data-binary", "--data-urlencode"):
 body = next(it, "")
 has_data_flag = True

 if not url:
 raise HTTPException(status_code=400, detail="No URL found in cURL command.")
 if has_data_flag and method == "GET":
 method = "POST"

 requires_auth = "authorization" in headers or "x-api-key" in headers
 impact_area = "write" if method in ("POST", "PUT", "PATCH") else ("delete" if method == "DELETE" else "read")
 risk_level = "medium" if impact_area in ("write", "delete") else "low"

 parsed_url = urlparse(url)
 base_endpoint = f"{parsed_url.scheme}://{parsed_url.netloc}{parsed_url.path}"

 parameters = {}
 for k, v in parse_qsl(parsed_url.query):
 parameters[k] = {"type": "string", "description": f"Query param: {k}", "default": v}

 if body:
 try:
 parsed_body = json.loads(body)
 if isinstance(parsed_body, dict):
 for k, v in parsed_body.items():
 ptype = "string"
 if isinstance(v, bool): ptype = "boolean"
 elif isinstance(v, (int, float)): ptype = "number"
 elif isinstance(v, list): ptype = "array"
 elif isinstance(v, dict): ptype = "json"
 parameters[k] = {"type": ptype, "description": f"Body param: {k}", "default": v}
 else:
 parameters["raw_body"] = {"type": "string", "description": "Raw body content", "default": body}
 except json.JSONDecodeError:
 parameters["raw_data"] = {"type": "string", "description": "Raw data content", "default": body}

 path_parts = [p for p in parsed_url.path.split("/") if p]
 base_name = path_parts[-1].replace("-", "_") if path_parts else "api"

 return {
 "name": f"{method.lower()}_{base_name}",
 "description": f"Auto-generated tool for {method} {base_endpoint}",
 "metadata": {
 "risk_level": risk_level,
 "impact_area": impact_area,
 "requires_auth": requires_auth,
 "risk_description": "Auto-imported from cURL."
 },
 "config": {"endpoint": base_endpoint, "method": method, "timeout": 120.0},
 "parameters": parameters
 }

