 raise HTTPException(status_code=500, detail=f"Saved, but hot-reload failed: {e}")

 return {"message": "Draft saved successfully.", "path": path}

# Mount the static frontend directory
app.mount("/", StaticFiles(directory="static", html=True), name="static")

if __name__ == "__main__":
 import uvicorn
 # Run the studio on a different port than the main MCP server
 uvicorn.run("studio_backend:app", host="0.0.0.0", port=8002, reload=True)

