 Inside the static folder, create app.js . This replaces Streamlit's entire backend-heavy UI logic with lightweight, instant client-side rendering. 

 // static/app.js

let currentTools = [];
let currentToolId = null;
let parameters = {}; // Maps param_name -> config
let testPassed = false;

// Initialize
document.addEventListener('DOMContentLoaded', () => {
 fetchTools();

 // Auto-update Test form when inputs change
 document.getElementById('tool-form').addEventListener('input', () => {
 testPassed = false;
 document.getElementById('btn-publish').disabled = true;
 renderTestFields();
 });
});

function showToast(message, type="success") {
 const toastEl = document.getElementById('liveToast');
 const toastBody = document.getElementById('toast-body');
 toastEl.className = `toast align-items-center text-white border-0 bg-${type}`;
 toastBody.textContent = message;
 const toast = new bootstrap.Toast(toastEl);
 toast.show();
}

// --- API Calls ---

async function fetchTools() {
 try {
 const res = await fetch('/api/tools');
 const data = await res.json();
 currentTools = data.tools;
 renderSidebar();
 } catch (e) {
 showToast('Failed to load tools from server', 'danger');
 }
}

async function importCurl() {
 const curlStr = document.getElementById('curl-input').value;
 try {
 const res = await fetch('/api/curl/parse', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({curl_cmd: curlStr})
 });
 const data = await res.json();
 if (res.ok) {
 loadToolIntoForm(data, true);
 bootstrap.Modal.getInstance(document.getElementById('curlModal')).hide();
 showToast('cURL parsed successfully!', 'success');
 } else {
 showToast(data.detail, 'danger');
 }
 } catch (e) {
 showToast('Error parsing cURL', 'danger');
 }
}

// --- UI Rendering ---

function renderSidebar() {
 const pubList = document.getElementById('published-list');
 const draftList = document.getElementById('drafts-list');
 pubList.innerHTML = '';
 draftList.innerHTML = '';

 currentTools.forEach(tool => {
 const li = document.createElement('li');
 li.className = 'nav-item';

 const a = document.createElement('a');
 a.className = 'nav-link tool-item text-dark px-3 py-2';
 a.textContent = tool.name;
 a.onclick = () => loadToolIntoForm(tool);

 if (tool.status === 'published') {
 a.innerHTML = `<i class="fa-solid fa-circle text-success me-2" style="font-size:0.6rem"></i>${tool.name}`;
 pubList.appendChild(li);
 } else {
 a.innerHTML = `<i class="fa-solid fa-circle text-warning me-2" style="font-size:0.6rem"></i>${tool.name}`;
 draftList.appendChild(li);
 }
 li.appendChild(a);
 });
}

function createNewTool() {
 loadToolIntoForm({
 name: "", description: "", metadata: {risk_level: "low", impact_area: "read", requires_auth: false, risk_description: ""},
 config: {endpoint: "", method: "GET", timeout: 120}, parameters: {}
 });
 document.getElementById('form-title').textContent = "Create New Tool";
}

function loadToolIntoForm(tool, isNewImport = false) {
 currentToolId = isNewImport ? null : tool.id;
 document.getElementById('form-title').textContent = isNewImport ? "Imported Tool (Unsaved)" : `Editing: ${tool.name}`;

 document.getElementById('f_name').value = tool.name || "";
 document.getElementById('f_method').value = tool.config?.method || "GET";
 document.getElementById('f_endpoint').value = tool.config?.endpoint || "";
 document.getElementById('f_desc').value = tool.description || "";
 document.getElementById('f_timeout').value = tool.config?.timeout || 120;

 const meta = tool.metadata || {};
 document.getElementById('f_risk').value = meta.risk_level || "low";
 document.getElementById('f_impact').value = meta.impact_area || "read";
 document.getElementById('f_auth').checked = meta.requires_auth || false;
 document.getElementById('f_risk_desc').value = meta.risk_description || "";

 parameters = tool.parameters || {};
 testPassed = false;
 document.getElementById('btn-publish').disabled = true;
 document.getElementById('test-console').classList.add('d-none');

 renderParamsTable();
 renderTestFields();
}

// --- Parameters Logic ---

function renderParamsTable() {
 const tbody = document.getElementById('params-body');
 const noMsg = document.getElementById('no-params-msg');
 tbody.innerHTML = '';

 const keys = Object.keys(parameters);
 if (keys.length === 0) {
 noMsg.classList.remove('d-none');
 return;
 }
 noMsg.classList.add('d-none');

 keys.forEach(key => {
 const p = parameters[key];
 const tr = document.createElement('tr');

 let defValue = p.default !== undefined ? p.default : "";
 if (p.type === 'array' || p.type === 'json') {
 defValue = typeof defValue === 'object' ? JSON.stringify(defValue) : defValue;
 }

 tr.innerHTML = `
 <td><input type="text" class="form-control form-control-sm" value="${key}" onchange="updateParamKey('${key}', this.value)"></td>
 <td>
 <select class="form-select form-select-sm" onchange="updateParam('${key}', 'type', this.value)">
 ${['string','file','number','boolean','array','json'].map(t => `<option value="${t}" ${p.type === t ? 'selected' : ''}>${t}</option>`).join('')}
 </select>
 </td>
 <td><input type="text" class="form-control form-control-sm" value="${p.description || ''}" onchange="updateParam('${key}', 'description', this.value)"></td>
 <td><input type="text" class="form-control form-control-sm" value='${defValue}' onchange="updateParam('${key}', 'default', this.value)"></td>
 <td><button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteParam('${key}')"><i class="fa-solid fa-trash"></i></button></td>
 `;
 tbody.appendChild(tr);
 });
}

function addParameterRow() {
 const baseName = "new_param";
 let name = baseName;
 let i = 1;
 while(parameters[name]) { name = `${baseName}_${i++}`; }

 parameters[name] = { type: "string", description: "", default: "" };
 renderParamsTable();
 renderTestFields();
}

function updateParamKey(oldKey, newKey) {
 if (oldKey === newKey || !newKey) return;
 parameters[newKey] = parameters[oldKey];
 delete parameters[oldKey];
 renderParamsTable();
 renderTestFields();
}

function updateParam(key, field, value) {
 parameters[key][field] = value;
 renderTestFields();
}

function deleteParam(key) {
 delete parameters[key];
 renderParamsTable();
 renderTestFields();
}

// --- Testing Logic ---

function renderTestFields() {
 const container = document.getElementById('test-inputs-container');
 const fieldsDiv = document.getElementById('test-fields');
 fieldsDiv.innerHTML = '';

 const keys = Object.keys(parameters);
 if (keys.length === 0) {
 container.classList.add('d-none');
 return;
 }

 container.classList.remove('d-none');
 keys.forEach(key => {
 const p = parameters[key];
 const col = document.createElement('div');
 col.className = 'col-md-6 mb-2';

 let inputHtml = '';
 let defVal = p.default || '';
 if(p.type === 'array' || p.type === 'json') {
 defVal = typeof defVal === 'object' ? JSON.stringify(defVal) : defVal;
 }

 if (p.type === 'boolean') {
 inputHtml = `<div class="form-check mt-4"><input type="checkbox" class="form-check-input test-input" data-key="${key}" data-type="boolean" ${defVal === 'true' || defVal === true ? 'checked' : ''}><label class="form-check-label">${key}</label></div>`;
 } else if (p.type === 'number') {
 inputHtml = `<label class="form-label">${key} <small class="text-muted">(number)</small></label><input type="number" class="form-control test-input" data-key="${key}" data-type="number" value="${defVal}">`;
 } else {
 inputHtml = `<label class="form-label">${key} <small class="text-muted">(${p.type})</small></label><input type="text" class="form-control test-input" data-key="${key}" data-type="${p.type}" value='${defVal}'>`;
 }

 col.innerHTML = inputHtml;
 fieldsDiv.appendChild(col);
 });
}

function getFormData() {
 // Reconstruct Parameter objects ensuring types are correct
 let cleanedParams = {};
 Object.keys(parameters).forEach(k => {
 let p = {...parameters[k]};
 if (p.default !== "" && p.default !== null) {
 if (p.type === 'number') p.default = parseFloat(p.default) || 0;
 if (p.type === 'boolean') p.default = (p.default === 'true' || p.default === true);
 if (p.type === 'array' || p.type === 'json') {
 try { p.default = JSON.parse(p.default); } catch(e) {}
 }
 } else {
 delete p.default;
 }
 cleanedParams[k] = p;
 });

 return {
 id: currentToolId,
 status: "draft", // Temp
 name: document.getElementById('f_name').value,
 description: document.getElementById('f_desc').value,
 metadata: {
 risk_level: document.getElementById('f_risk').value,
 impact_area: document.getElementById('f_impact').value,
 requires_auth: document.getElementById('f_auth').checked,
 risk_description: document.getElementById('f_risk_desc').value
 },
 config: {
 endpoint: document.getElementById('f_endpoint').value,
 method: document.getElementById('f_method').value,
 timeout: parseFloat(document.getElementById('f_timeout').value)
 },
 parameters: cleanedParams
 };
}

async function runTest() {
 const config = getFormData();
 if (!config.name || !config.config.endpoint) {
 showToast("Name and Endpoint are required to test.", "warning");
 return;
 }

 // Gather Test Args
 let testArgs = {};
 document.querySelectorAll('.test-input').forEach(input => {
 const key = input.dataset.key;
 const type = input.dataset.type;
 if (type === 'boolean') {
 testArgs[key] = input.checked;
 } else if (type === 'number') {
 testArgs[key] = parseFloat(input.value) || 0;
 } else if (type === 'array' || type === 'json') {
 try { testArgs[key] = JSON.parse(input.value || "null"); } catch(e) { testArgs[key] = input.value; }
 } else {
 testArgs[key] = input.value;
 }
 });

 const consoleDiv = document.getElementById('test-console');
 const consoleText = document.getElementById('test-console-text');
 consoleDiv.classList.remove('d-none');
 consoleText.innerHTML = '<span class="text-warning">Running MCP simulation...</span>';

 try {
 const res = await fetch('/api/tools/test', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({ config: config, test_args: testArgs })
 });
 const data = await res.json();

 if (data.success) {
 consoleText.innerHTML = `<span class="text-success">[SUCCESS]</span><br><pre class="text-light mt-2">${typeof data.output === 'object' ? JSON.stringify(data.output, null, 2) : data.output}</pre>`;
 testPassed = true;
 document.getElementById('btn-publish').disabled = false;
 showToast("Test successful! You can now publish.", "success");
 } else {
 consoleText.innerHTML = `<span class="text-danger">[ERROR]</span><br><pre class="text-light mt-2">${data.output || data.detail}</pre>`;
 showToast("Test failed. Check console.", "danger");
 }
 } catch (e) {
 consoleText.innerHTML = `<span class="text-danger">Network Error</span>`;
 }
}

async function saveTool(status) {
 if (!testPassed && status === 'published') return;

 const config = getFormData();
 config.status = status;

 if (!config.name) {
 showToast("Tool name is required.", "warning");
 return;
 }

 try {
 const res = await fetch('/api/tools/save', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify(config)
 });
 const data = await res.json();

 if (res.ok) {
 showToast(data.message, "success");
 fetchTools(); // Refresh sidebar
 } else {
 showToast(data.detail || "Error saving tool", "danger");
 }
 } catch (e) {
 showToast("Network error saving tool.", "danger");
 }
}

 How to Run This Setup 

 Make sure your main MCP server is still running as usual on its port (e.g., 8001 ). 

 Open a new terminal and run your new Studio backend using Uvicorn on a different port:
 uvicorn studio_backend:app --host 0.0.0.0 --port 8002

 Open your browser and navigate to http://localhost:8002 . 

 You will now see a lightning-fast, production-ready Bootstrap UI that behaves exactly like your POC, but with perfect separation of concerns and immediate "Push" syncing to the MCP server upon publishing!

