"""
Tool metadata utilities for MCP server.

This module provides utilities for attaching risk metadata to MCP tools,
including risk levels, impact areas, authentication requirements, and descriptions.
"""

from typing import Callable, Dict, Any
from mcp.server.fastmcp import FastMCP

def create_tool_metadata_decorator(mcp: FastMCP) -> Callable:
 """
 Creates a decorator factory for attaching metadata to MCP tools.

 Args:
 mcp: The FastMCP instance to register tools with

 Returns:
 A decorator function that can be used to attach metadata to tools

 Example:
 ```python
 tool_with_metadata = create_tool_metadata_decorator(mcp)

 @tool_with_metadata(
 risk_level="low",
 impact_area="read",
 requires_auth=False,
 risk_description="Read-only operation"
 )
 def my_tool():
 pass
 ```
 """
 def tool_with_metadata(**metadata):
 """
 Decorator to attach risk metadata to a tool while using
 the existing FastMCP registration decorator.

 Metadata fields:
 risk_level: "low" | "medium" | "high"
 impact_area: "read" | "write" | "delete" | "execute"
 requires_auth: bool
 risk_description: str - Human-readable explanation of why it is risky
 """
 def decorator(func: Callable) -> Callable:
 # Register the tool with FastMCP
 decorated = mcp.tool()(func)

 # Store metadata on the MCP instance for later retrieval
 tool_name = getattr(decorated, "name", func.__name__)
 if not hasattr(mcp, "_tool_metadata"):
 mcp._tool_metadata = {}
 mcp._tool_metadata[tool_name] = metadata

 return decorated

 return decorator

 return tool_with_metadata

