 logger.error("[MCP] pdf_to_text_tool failed to download file from URL")
 return {"error": "Failed to download file from URL"} 
 else:
 # Handle base64 encoded PDF/image
 import tempfile
 try:
 file_data = base64.b64decode(file_src)
 # Determine file extension based on content or assume PDF
 suffix = ".pdf" # Default to PDF
 fd, file_path = tempfile.mkstemp(suffix=suffix)
 with os.fdopen(fd, "wb") as f:
 f.write(file_data)
 except Exception as e:
 logger.error("[MCP] pdf_to_text_tool base64 decode failed: {}", e)
 return {"error": "Invalid base64 file input"}

 # Call the PDF to text function
 result = pdf_to_text(file_path, is_back, xcall_id, input_type)

 # Clean up temp file if it was created
 if input_type in ["url", "url_pdf"] and file_path.startswith("/tmp"):
 try:
 os.unlink(file_path)
 except Exception:
 pass # Ignore cleanup errors

 if "error" in result:
 logger.error("[MCP] pdf_to_text_tool error result={}", result)
 else:
 logger.info("[MCP] pdf_to_text_tool success")

 return result

 except Exception as e:
 logger.error("[MCP] pdf_to_text_tool exception: {}", e)
