"""
Load MCP tools from JSON definitions under tools/dynamic_configs/.
"""

import asyncio
import json
import os
from typing import Any, Callable, Type

import httpx
from loguru import logger
from pydantic import Field, create_model

from helpers.helper import (
 flatten_dynamic_params_for_query_or_form,
 normalize_dynamic_array_default,
)
from mcp.server.fastmcp import Context, FastMCP

# Names registered in the last load_dynamic_tools() call (for hot-reload).
_registered_dynamic_tool_names: set[str] = set()

_DYNAMIC_CONFIG_DIR = os.path.normpath(
 os.path.join(os.path.dirname(__file__), "..", "dynamic_configs")
)

async def call_api(
 url: str,
 method: str,
 payload: dict[str, Any],
 config: dict[str, Any],
) -> dict[str, Any]:
 api_timeout = config.get("config", {}).get("timeout", 120.0)
 async with httpx.AsyncClient(timeout=api_timeout) as client:
 files: dict[str, Any] = {}
 native: dict[str, Any] = {}
 params_cfg = config.get("parameters", {})
 for key, value in payload.items():
 param_entry = params_cfg.get(key, {})
 if not isinstance(param_entry, dict):
 param_entry = {}
 if param_entry.get("type") == "file":
 clean_path = str(value).strip('"').strip("'")
 if os.path.exists(clean_path):
 file_handle = open(clean_path, "rb")
 basename = os.path.basename(clean_path)
 files[key] = (basename, file_handle)
 else:
 return {"error": f"File not found: {clean_path}"}
 else:
 native[key] = value
 flat = flatten_dynamic_params_for_query_or_form(native, params_cfg)
 try:
 method_u = method.upper()
 resp = None

 if method_u == "POST":
 if files:
 resp = await client.post(url, data=flat, files=files)
 else:
 resp = await client.post(url, json=native)
 elif method_u == "GET":
 resp = await client.get(url, params=flat)
 elif method_u == "PUT":
 if files:
 resp = await client.put(url, data=flat, files=files)
 else:
 resp = await client.put(url, json=native)
 elif method_u == "PATCH":
 if files:
 resp = await client.patch(url, data=flat, files=files)
 else:
 resp = await client.patch(url, json=native)
 elif method_u == "DELETE":
 resp = await client.delete(url, params=flat)
 else:
 return {"error": f"Unsupported HTTP method: {method}"}

 try:
 return resp.json()
 except Exception:
 return {"status": resp.status_code, "raw_response": resp.text}
 except Exception as e:
 return {"error": "API Error", "details": str(e)}
 finally:
 for file_key in files:
 entry = files[file_key]
 file_obj = entry[1]
 try:
 file_obj.close()
 except Exception:
 pass

def _safe_model_name(tool_name: str) -> str:
 parts: list[str] = []
 for char in tool_name:
 if char.isalnum():
 parts.append(char)
 else:
 parts.append("_")
 safe = "".join(parts)
 if not safe:
 safe = "Dynamic"
 return f"{safe}Model"

def _build_field_definitions(parameters: dict[str, Any]) -> dict[str, Any]:
 fields: dict[str, Any] = {}
 for name, info in parameters.items():
 if info is None or not isinstance(info, dict):
 param_info: dict[str, Any] = {}
 else:
 param_info = info

 ptype = param_info.get("type", "string")
 desc = param_info.get("description", "")

 if "default" in param_info:
 default = param_info["default"]
 if ptype == "number":
 ann = float
 try:
 default = float(default) # type: ignore[arg-type]
 except (TypeError, ValueError):
 default = 0.0
 elif ptype == "boolean":
 ann = bool
 if isinstance(default, str):
 default = default.lower() in ("true", "1", "yes")
 elif ptype == "array":
 ann = list[str]
 default = normalize_dynamic_array_default(default)
 else:
 ann = str
 fields[name] = (ann, Field(default=default, description=desc))
 else:
 if ptype == "number":
 fields[name] = (float, Field(..., description=desc))
 elif ptype == "boolean":
 fields[name] = (bool, Field(..., description=desc))
 elif ptype == "array":
 fields[name] = (
 list[str],
 Field(default_factory=list, description=desc),
 )
 else:
 fields[name] = (str, Field(..., description=desc))
 return fields

def _unregister_previous_dynamic_tools(mcp_instance: FastMCP) -> None:
 """
 Drop dynamic tools we registered last time.

 FastMCP keeps tools by name: registering the same name again does not replace
 the old handler. We remove our previous names first so a reload re-reads JSON
 from disk and picks up edits (endpoint, parameters, etc.).
 """
 global _registered_dynamic_tool_names
 tm = mcp_instance._tool_manager
 for name in _registered_dynamic_tool_names:
 removed = tm._tools.pop(name, None)
 if removed:
 logger.debug("Removed previous dynamic tool: {}", name)
 _registered_dynamic_tool_names.clear()

def _list_json_config_filenames(config_dir: str) -> list[str]:
 names: list[str] = []
 for entry in os.listdir(config_dir):
 if entry.endswith(".json"):
 names.append(entry)
 names.sort()
 return names

def _register_dynamic_tool_handler(
 mcp_instance: FastMCP,
 cfg: dict[str, Any],
 ToolModel: Type[Any],
) -> None:
 """Attach one dynamic tool to FastMCP from a config dict and Pydantic arg model."""

 # Pass description into @tool() — setting fn.__doc__ after the decorator runs is too
 # late; FastMCP already captured metadata for tools/list (agents + Inspector).
 tool_desc = cfg.get("description")
 if not (isinstance(tool_desc, str) and tool_desc.strip()):
 tool_desc = None

 @mcp_instance.tool(name=cfg["name"], description=tool_desc)
 async def dynamic_tool(args: ToolModel, ctx: Context) -> Any:
 async def heartbeat() -> None:
 seconds = 0
 while True:
 await asyncio.sleep(5)
 seconds = seconds + 5
 try:
 await ctx.report_progress(
 seconds,
 120,
 f"Still processing API... {seconds}s elapsed",
 )
 except Exception:
 break

 pulse_task = asyncio.create_task(heartbeat())
 try:
 api_config = cfg.get("config")
 if api_config is None:
 api_config = {}
 endpoint = api_config.get("endpoint", "")
 http_method = api_config.get("method", "GET")
 dumped = args.model_dump()
 return await call_api(
 endpoint,
 http_method,
 dumped,
 cfg,
 )
 finally:
 pulse_task.cancel()

def register_dynamic_tool_from_config(
 mcp_instance: FastMCP,
 cfg: dict[str, Any],
 *,
 replace_existing: bool = True,
) -> tuple[bool, str]:
 """
 Register a single tool from an in-memory config (e.g. Streamlit Studio test preview).

 If replace_existing, removes any existing MCP tool with the same name first so the
 new handler is used (FastMCP does not overwrite duplicates by default).
 """
 tool_name = cfg.get("name")
 if not tool_name:
 return False, "Config is missing 'name'."

 params = cfg.get("parameters")
 if params is None:
 params = {}

 tm = mcp_instance._tool_manager
 if replace_existing:
 tm._tools.pop(str(tool_name), None)

 field_defs = _build_field_definitions(params)
 model_name = _safe_model_name(str(tool_name))
 ToolModel = create_model(model_name, **field_defs)
 _register_dynamic_tool_handler(mcp_instance, cfg, ToolModel)
 _registered_dynamic_tool_names.add(str(tool_name))
 logger.info("Registered dynamic tool '{}' from in-memory config (preview/studio)", tool_name)
 return True, "Registered."

def load_dynamic_tools(
 mcp_instance: FastMCP,
 tool_allowed_func: Callable[[str], bool],
) -> None:
 """
 Scan tools/dynamic_configs for *.json and register published tools.
 Clears tools registered by the previous call so configs can be hot-reloaded.
 """
 # Must run first: see _unregister_previous_dynamic_tools docstring.
 _unregister_previous_dynamic_tools(mcp_instance)

 if not os.path.isdir(_DYNAMIC_CONFIG_DIR):
 logger.warning(
 "Dynamic tools config directory missing: {} (skipping)",
 _DYNAMIC_CONFIG_DIR,
 )
 return

 json_files = _list_json_config_filenames(_DYNAMIC_CONFIG_DIR)
 if not json_files:
 logger.info("No JSON tool configs found in {}", _DYNAMIC_CONFIG_DIR)
 return

 for filename in json_files:
 path = os.path.join(_DYNAMIC_CONFIG_DIR, filename)
 try:
 with open(path, encoding="utf-8") as fp:
 cfg = json.load(fp)
 except Exception as e:
 logger.error("Failed to read dynamic tool config {}: {}", path, e)
 continue

 if cfg.get("status") != "published":
 continue

 tool_name = cfg.get("name")
 if not tool_name:
 logger.warning("Skipping {}: missing 'name'", path)
 continue

 if not tool_allowed_func(tool_name):
 logger.info("Dynamic tool '{}' skipped by tool_allowed_func", tool_name)
 continue

 params = cfg.get("parameters")
 if params is None:
 params = {}
 field_defs = _build_field_definitions(params)
 model_name = _safe_model_name(str(tool_name))
 ToolModel = create_model(model_name, **field_defs)
 _register_dynamic_tool_handler(mcp_instance, cfg, ToolModel)
 _registered_dynamic_tool_names.add(str(tool_name))
 logger.info("Registered dynamic tool '{}' from {}", tool_name, filename)

 count = len(_registered_dynamic_tool_names)
 logger.info(
 "Dynamic tools load complete: {} published tool(s) active",
 count,
 )

helper.py:

# ---------------------------------------------------------------------
# Dynamic tool configs (tools/dynamic_configs): value normalization & HTTP encoding
# ---------------------------------------------------------------------

def normalize_dynamic_array_default(raw: Any) -> list[str]:
 """Coerce JSON / CSV-ish defaults into list[str] for parameter type ``array``."""
 if raw is None:
 return []
 if isinstance(raw, list):
 return [str(x) for x in raw]
 if isinstance(raw, str):
 s = raw.strip()
 if not s:
 return []
 if s.startswith("["):
 try:
 parsed = json.loads(s)
 if isinstance(parsed, list):
 return [str(x) for x in parsed]
 except json.JSONDecodeError:
 pass
 return [p.strip() for p in s.split(",") if p.strip()]
 return [str(raw)]

def serialize_dynamic_param_for_query(
 value: Any, param_info: Dict[str, Any] | None = None
) -> str:
 """Turn a Python value into a string for URL query strings or multipart form fields.

 ``param_info`` is for per-parameter options (e.g. ``query_format``); today all
 list values are comma-joined regardless.
 """
 if param_info and param_info.get("query_format") not in (None, "comma_separated"):
 logger.debug(
 "serialize_dynamic_param_for_query: unsupported query_format={!r}, using default",
 param_info.get("query_format"),
 )
 if isinstance(value, bool):
 return str(value).lower()
 if isinstance(value, (int, float)) and not isinstance(value, bool):
 return str(value)
 if isinstance(value, list):
 return ",".join(str(x) for x in value)
 return str(value)

def flatten_dynamic_params_for_query_or_form(
 native: Dict[str, Any], params_cfg: Dict[str, Any]
) -> Dict[str, str]:
 """Build a flat str->str map for GET params or urlencoded multipart (not JSON body)."""
 out: Dict[str, str] = {}
 for key, value in native.items():
 pinfo = params_cfg.get(key, {}) or {}
 out[key] = serialize_dynamic_param_for_query(value, pinfo)
 return out

