 help="Writes JSON with status draft. Does not require a passed test.",
 )
 with c2:
 publish = st.button(
 "Publish to production",
 type="primary",
 disabled=not can_publish,
 help="Enabled only after a successful MCP test for the current definition.",
 )

 if not can_publish and name.strip():
 st.info(
 "Publish is locked until **Run MCP test** (section 3) succeeds for this exact "
 "definition (endpoint, method, parameters, and name)."
 )

if save_draft or publish:
 if not name.strip():
 st.error("Tool name is required.")
 else:
 status = "published" if publish else "draft"
 cfg_out = build_cfg(
 name=name,
 description=description,
 endpoint=endpoint,
 method=method,
 timeout=timeout,
 parameters=parameters,
 status=status,
 existing_id=existing_id,
 )
 path = save_config(cfg_out)
 st.success(f"Saved: `{path}`")

 if publish:
 if mcp is None:
 st.warning(
 "File saved as published, but MCP was not loaded — restart the server or fix imports to pick up tools."
 )
 else:
 try:
 from mcp_server_refactored import setup_tool_configuration
 from tools.dynamic_tools.loader import load_dynamic_tools

 load_dynamic_tools(mcp, setup_tool_configuration())
 st.info("Reloaded dynamic tools from disk on the in-process MCP server.")
 except Exception as e:
 st.warning(f"Saved file but reload failed: {e!s}")
 st.rerun()

mcp_server_refactored.py:
 logger.info("Step 3b: Loading dynamic tools from JSON configs...")
 load_dynamic_tools(mcp, tool_allowed_func)
 logger.info("Step 3b: Dynamic tools loading completed")

