 <tr><td><strong>Agent</strong></td><td><code>{"id": "researcher", "agent": "UUID"}</code></td></tr>
 <tr><td><strong>Tool Node</strong></td><td><code>{"id": "tools", "type": "tool_node", "tools": ["web_search"]}</code></td></tr>
