 <!-- Monaco Editor -->
 <script src="https://cdn.jsdelivr.net/npm/monaco-editor@0.45.0/min/vs/loader.js"></script>
 <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>

 <script>
 let editor = null;
 let currentWorkflowData = null;
 let currentWorkflowId = null; // Track currently selected workflow ID
 let currentSessionId = null; // For execute-hierarchical-workflow; enables DB-backed chat history
 let chatHistory = []; // Store chat history for context

 // Initialize Monaco Editor
 require.config({ paths: { vs: 'https://cdn.jsdelivr.net/npm/monaco-editor@0.45.0/min/vs' } });
 require(['vs/editor/editor.main'], function () {
 editor = monaco.editor.create(document.getElementById('workflowEditor'), {
 value: '// Select a workflow card above to start editing...\n',
 language: 'json',
 theme: 'vs-light',
 automaticLayout: true,
 minimap: { enabled: true },
 scrollBeyondLastLine: false,
 fontSize: 14,
 lineNumbers: 'on',
 formatOnPaste: true,
 formatOnType: true,
 wordWrap: 'on',
 tabSize: 2,
 insertSpaces: true
 });

 // Add validation on content change
 editor.onDidChangeModelContent(() => {
 // Reset validation button state
 const validateBtn = document.getElementById('validateBtn');
 const compileStatus = document.getElementById('compileStatus');
 if (validateBtn) {
 validateBtn.classList.remove('btn-success');
 validateBtn.classList.add('btn-warning');
 const validateBtnText = document.getElementById('validateBtnText');
 if (validateBtnText) {
 validateBtnText.textContent = 'Validate JSON';
 }
 }
 if (compileStatus) {
 compileStatus.innerHTML = '';
 compileStatus.className = 'compile-status';
 }
 // Run basic JSON validation
 try {
 const content = editor.getValue();
 JSON.parse(content);
 setStatus('valid', 'Valid JSON');
 } catch (error) {
 setStatus('invalid', 'Invalid JSON');
 }
 });

 // Load workflow list on initialization
 loadWorkflowList();
 });

 // Load list of hierarchical workflows from database
 // Store loaded workflows for card rendering
 let loadedWorkflows = [];

 async function loadWorkflowList() {
 try {
 const selector = document.getElementById('workflowSelector');
 const cardsGrid = document.getElementById('workflowCardsGrid');
 const noWorkflowsMessage = document.getElementById('noWorkflowsMessage');

 selector.innerHTML = '<option value="">-- Loading workflows... --</option>';
 noWorkflowsMessage.innerHTML = '<i class="fas fa-spinner fa-spin"></i><p>Loading workflows...</p>';

 const response = await fetchWithAuth('/api/workflow/hierarchical-workflows');
 if (!response.ok) {
 throw new Error(`Failed to load workflows: ${response.statusText}`);
 }

 const data = await response.json();
 const workflows = data.workflows || [];
 loadedWorkflows = workflows;

 selector.innerHTML = '<option value="">-- Select a workflow --</option>';

 if (workflows.length === 0) {
 selector.innerHTML += '<option value="" disabled>No hierarchical workflows found</option>';
 noWorkflowsMessage.innerHTML = `
 <i class="fas fa-sitemap"></i>
 <p>No hierarchical workflows found</p>
 <small class="text-muted">Create a workflow agent with type "hierarchical_workflow" to get started.</small>
 `;
 setStatus('valid', 'Ready');
 return;
 }

 // Populate selector (for compatibility)
 workflows.forEach(wf => {
 const option = document.createElement('option');
 option.value = wf.id;
 option.textContent = `${wf.workflow_name || wf.name} (${wf.nodes_count} nodes, ${wf.edges_count} edges)`;
 selector.appendChild(option);
 });

 // Render workflow cards
 renderWorkflowCards(workflows);

 // Check if workflow_id is in URL params
 const urlParams = new URLSearchParams(window.location.search);
 const workflowIdFromUrl = urlParams.get('workflow_id');
 if (workflowIdFromUrl) {
 selectWorkflowCard(workflowIdFromUrl);
 }

 setStatus('valid', 'Ready');
 } catch (error) {
 console.error('Error loading workflow list:', error);
 const noWorkflowsMessage = document.getElementById('noWorkflowsMessage');
 noWorkflowsMessage.innerHTML = `
 <i class="fas fa-exclamation-triangle text-danger"></i>
 <p class="text-danger">Error loading workflows</p>
 <small class="text-muted">${error.message}</small>
 `;
 setStatus('invalid', 'Error');
 }
 }

 // Render workflow cards
 function renderWorkflowCards(workflows) {
 const cardsGrid = document.getElementById('workflowCardsGrid');

 // Clear existing content
 cardsGrid.innerHTML = '';

 workflows.forEach(wf => {
 const card = createWorkflowCard(wf);
 cardsGrid.appendChild(card);
 });
 }

 // Create a single workflow card
 function createWorkflowCard(workflow) {
 const card = document.createElement('div');
 card.className = 'h-workflow-card';
 card.id = `workflow-card-${workflow.id}`;
 card.onclick = () => selectWorkflowCard(workflow.id);

 const statusClass = workflow.is_active ? 'active' : 'inactive';
 const statusText = workflow.is_active ? 'Active' : 'Inactive';

 // Build nodes HTML similar to supervisor's agents list
 const nodes = workflow.nodes || [];
 const nodesHtml = nodes.map(node => {
 const isEntry = node.id === workflow.entry_point;
 const typeClass = isEntry ? 'entry' : '';
 const typeLabel = isEntry ? 'entry' : node.type || 'simple';

 return `
 <div class="node-item">
 <span class="node-name">${node.name || node.id}</span>
 <span class="node-type ${typeClass}">${typeLabel}</span>
 </div>
 `;
 }).join('');

 card.innerHTML = `
 <div class="card-body">
 <div class="d-flex justify-content-between align-items-start mb-2">
 <h5 class="card-title mb-1">${workflow.workflow_name || workflow.name}</h5>
 <span class="workflow-status ${statusClass}">${statusText}</span>
 </div>

 <p class="text-muted small mb-3">${workflow.description || 'No description'}</p>

 <div class="nodes-section mb-2">
 <div class="d-flex justify-content-between align-items-center mb-2">
 <small class="text-muted">
 <i class="fas fa-project-diagram me-1"></i><strong>Nodes (${nodes.length}):</strong>
 </small>
 <button class="btn btn-sm btn-outline-secondary" onclick="event.stopPropagation(); toggleNodesList('${workflow.id}')" id="toggleBtn-${workflow.id}">
 <i class="fas fa-chevron-down" id="chevron-${workflow.id}"></i>
 </button>
 </div>
 <div class="nodes-list" id="nodesList-${workflow.id}">
 ${nodesHtml || '<div class="text-muted small">No nodes defined</div>'}
 </div>
 </div>
 </div>

 <div class="card-footer">
 <div class="d-flex gap-1">
 <button class="btn btn-sm btn-outline-primary" onclick="event.stopPropagation(); selectWorkflowCard('${workflow.id}')">
 <i class="fas fa-edit me-1"></i>Edit
 </button>
