 // Save workflow configuration to database
 async function saveWorkflow() {
 try {
 if (!currentWorkflowId) {
 showMessage('Please select a workflow card first.', 'error');
 return;
 }

 setStatus('loading', 'Saving...');
 clearMessages();

 // Get editor content
 const editorContent = editor.getValue();

