 },
 body: JSON.stringify(workflowData)
 });

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.detail || `Failed to save: ${response.statusText}`);
 }

 const result = await response.json();
 currentWorkflowData = workflowData;
 setStatus('valid', 'Saved');
 showMessage(`Workflow "${workflowData.workflow_name}" saved successfully to database!`, 'success');

 // Refresh the workflow list to update any name changes
