 }

 // Validate JSON in editor
 function validateJSON() {
 const validateBtn = document.getElementById('validateBtn');
 const compileStatus = document.getElementById('compileStatus');

 try {
 const content = editor.getValue();
 const parsed = JSON.parse(content);

 // Additional structure validation
 let validationErrors = [];
 if (!parsed.workflow_name) {
 validationErrors.push('Missing required field: workflow_name');
 }
 if (!parsed.nodes || !Array.isArray(parsed.nodes)) {
 validationErrors.push('Missing or invalid field: nodes (must be an array)');
 }
 if (!parsed.edges || !Array.isArray(parsed.edges)) {
 validationErrors.push('Missing or invalid field: edges (must be an array)');
 }

 if (validationErrors.length > 0) {
 throw new Error(validationErrors.join('; '));
 }

 // Valid JSON
 setStatus('valid', 'Valid JSON');
 compileStatus.innerHTML = '<i class="fas fa-check-circle me-1"></i>JSON is valid';
 compileStatus.className = 'compile-status success';
 validateBtn.classList.remove('btn-warning');
 validateBtn.classList.add('btn-success');
 const validateBtnText = document.getElementById('validateBtnText');
 if (validateBtnText) {
 validateBtnText.textContent = 'Valid';
 }

 clearMessages();
 showMessage('JSON is valid and ready to compile!', 'success');

 return true;
 } catch (error) {
 setStatus('invalid', 'Invalid JSON');
 compileStatus.innerHTML = `<i class="fas fa-exclamation-circle me-1"></i>${error.message}`;
 compileStatus.className = 'compile-status error';
 validateBtn.classList.remove('btn-success');
 validateBtn.classList.add('btn-warning');
 const validateBtnText = document.getElementById('validateBtnText');
 if (validateBtnText) {
 validateBtnText.textContent = 'Validate JSON';
 }

 showMessage(`JSON validation failed: ${error.message}`, 'error');
 return false;
 }
 }

