 // Render workflow graph
 async function renderGraph() {
 try {
 // Show loading state
 const loadingOverlay = document.getElementById('graphLoading');
 const graphPlaceholder = document.getElementById('graphPlaceholder');
 const graphImage = document.getElementById('graphImage');

 loadingOverlay.style.display = 'flex';
 graphPlaceholder.style.display = 'none';
 graphImage.style.display = 'none';

 clearMessages();

 // Get current editor content
 const editorContent = editor.getValue();

 // Parse and validate JSON
 let workflowData;
 try {
 workflowData = JSON.parse(editorContent);
 } catch (parseError) {
 throw new Error(`Invalid JSON: ${parseError.message}`);
 }

 // Validate structure
 if (!workflowData.workflow_name) {
 throw new Error('Missing required field: workflow_name');
 }
 if (!workflowData.nodes || !Array.isArray(workflowData.nodes)) {
 throw new Error('Missing or invalid field: nodes (must be an array)');
 }
 if (!workflowData.edges || !Array.isArray(workflowData.edges)) {
 throw new Error('Missing or invalid field: edges (must be an array)');
 }

 // Call render API - uses agent IDs from editor JSON to load agents from database
 const response = await fetchWithAuth('/api/workflow/render', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json'
 },
 body: JSON.stringify({
 workflow_config: workflowData
 // Note: Agent IDs are extracted from workflow_config on the backend
 })
 });

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.detail || `Failed to render graph: ${response.statusText}`);
 }

 const result = await response.json();

 if (result.success && result.image) {
 // Display image
 graphImage.src = result.image;
 graphImage.style.display = 'block';
 graphPlaceholder.style.display = 'none';
 showMessage('Workflow graph rendered successfully!', 'success');
 } else {
 throw new Error(result.error || 'Failed to render graph');
 }
 } catch (error) {
 console.error('Error rendering graph:', error);

 // Show placeholder again
 document.getElementById('graphPlaceholder').style.display = 'block';
 document.getElementById('graphImage').style.display = 'none';

 // Show detailed error message
 let errorMsg = error.message;
 if (error.message.includes('unknown node')) {
 errorMsg = `Graph compilation error: ${error.message}. Check that all edges reference valid node IDs.`;
 } else if (error.message.includes('Error rendering workflow graph')) {
 errorMsg = `Graph compilation failed: ${error.message}. Verify workflow configuration in the editor.`;
 }
 showMessage(errorMsg, 'error');

 // Also log to console for debugging
 console.error('Graph compilation error details:', error);
 } finally {
 // Hide loading overlay
 document.getElementById('graphLoading').style.display = 'none';
 }
 }

