 const query = chatInput.value.trim();
 if (!query) return;

 const user_name = 'user';
 const context = ''; // Context removed - not used with execute-hierarchical-workflow

 // Clear input
 chatInput.value = '';

 // Terminal is disabled - skip terminal status updates
 // (Keeping code for future when execute-stream is enabled)
 if (terminalOutput && terminalStatus) {
 terminalOutput.innerHTML = '';
 terminalStatus.textContent = 'Running...';
 terminalStatus.className = 'terminal-status running';
 }

 // Remove welcome message if present
 const welcomeMsg = chatMessages.querySelector('.chat-welcome');
 if (welcomeMsg) {
 welcomeMsg.remove();
 }

 // Add user message to chat history
 chatHistory.push({ role: 'user', content: query });

 // Update chat history badge
 const chatHistoryBadge = document.getElementById('chatHistoryBadge');
 if (chatHistoryBadge) {
 chatHistoryBadge.style.display = 'inline-block';
 chatHistoryBadge.textContent = `${chatHistory.length} messages in history`;
 }

 // Add user message to UI
 addChatMessage('user', query, 'user');

 // Show loading
 const loadingId = addChatLoading();

 // Disable send button
 sendButton.disabled = true;
 sendButton.innerHTML = '<i class="fas fa-spinner fa-spin me-1"></i>Sending...';

 try {
 if (!currentWorkflowId) {
 throw new Error('Please select a workflow to run.');
 }

 // Terminal logging disabled - will be enabled with execute-stream
 // addTerminalLog('Executing workflow (saved version from database)...');

 // execute-hierarchical-workflow: loads from DB, persists transaction/agent_execution_log/tool_execution_log/interactions, session_id for chat history
 const response = await fetchWithAuth('/api/workflow/execute-hierarchical-workflow', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({
 workflow_id: currentWorkflowId,
 query: query,
 user_name: user_name,
 context: '', // Context removed - not used
 session_id: currentSessionId || undefined
 })
 });

 const body = await response.json().catch(() => ({}));

 if (!response.ok) {
 throw new Error(body.detail || `Request failed: ${response.statusText}`);
 }

 const finalResponse = body.response || body.final_response || '';
 if (body.session_id) {
 currentSessionId = body.session_id;
 }

 // Terminal logging disabled
 // addTerminalLog('Workflow completed. Session: ' + (body.session_id || '—') + ', Transaction: ' + (body.transaction_id || '—'));

 if (terminalStatus) {
 terminalStatus.textContent = 'Completed';
 terminalStatus.className = 'terminal-status';
 }

 removeChatLoading(loadingId);

 if (finalResponse) {
 chatHistory.push({ role: 'assistant', content: finalResponse });
 addChatMessage('assistant', finalResponse, 'Workflow');
 } else {
 const errorMsg = 'Workflow executed but no response generated';
 chatHistory.push({ role: 'assistant', content: errorMsg });
 addChatMessage('assistant', errorMsg, 'System');
 }
 } catch (error) {
 console.error('Error executing workflow:', error);

 // Update terminal status (disabled but kept for future)
 if (terminalStatus) {
 terminalStatus.textContent = 'Error';
 terminalStatus.className = 'terminal-status';
 terminalStatus.style.background = '#dc3545';
 }

 // Remove loading
 removeChatLoading(loadingId);

 // Show detailed error message
 let errorMsg = error.message;
 if (error.message.includes('workflow_id')) {
 errorMsg = `Workflow not found. Please select a valid workflow.`;
 } else if (error.message.includes('state_schema') || error.message.includes('nodes') || error.message.includes('edges')) {
 errorMsg = `Workflow configuration error: ${error.message}. Please check the workflow JSON in the editor.`;
 } else if (error.message.includes('Request failed')) {
 errorMsg = `API request failed: ${error.message}. Check server logs for details.`;
 }

 chatHistory.push({ role: 'assistant', content: errorMsg });
 // Terminal logging disabled
 // addTerminalLog(`❌ Error: ${errorMsg}`, 'error');
 addChatMessage('assistant', errorMsg, 'System');

 // Also show in main message area
 showMessage(`Workflow execution failed: ${errorMsg}`, 'error');
 } finally {
 // Re-enable send button
 sendButton.disabled = false;
 sendButton.innerHTML = '<i class="fas fa-paper-plane me-1"></i>Send';
 }
 }

