 // Validate workflow configuration
 function validateWorkflow(nodes, edges) {
 const errors = [];
 const warnings = [];

 // Collect node IDs
 const nodeIds = new Set();
 const nodeIdSet = new Set();

 // 1. Check for duplicate node IDs
 nodes.forEach((node, idx) => {
 if (!node.id || !node.id.trim()) {
 errors.push(`Node ${idx + 1}: Node ID is required`);
 } else if (nodeIdSet.has(node.id)) {
 errors.push(`Node "${node.id}": Duplicate node ID`);
 } else {
 nodeIdSet.add(node.id);
 nodeIds.add(node.id);
 }
 });

 // 2. Check for entry point
 const entryNodes = nodes.filter(n => n.type === 'entry');
 if (entryNodes.length === 0 && nodes.length > 0) {
 warnings.push('No entry node found. First node will be used as entry point.');
 } else if (entryNodes.length > 1) {
 warnings.push(`Multiple entry nodes found: ${entryNodes.map(n => n.id).join(', ')}. First one will be used.`);
 }

 // 3. Validate tool_node has tools
 nodes.forEach(node => {
 if (node.type === 'tool_node') {
 if (!node.tools || node.tools.length === 0) {
 errors.push(`Node "${node.id}" (tool_node): Must select at least one tool`);
 }
 }
 });

 // 4. Validate edges reference existing nodes
 const edgeRefs = new Set();
 edges.forEach((edge, idx) => {
 const from = edge.from;
 const to = edge.to;

 if (from && from !== 'START') {
 if (!nodeIds.has(from)) {
 errors.push(`Edge ${idx + 1}: "from" node "${from}" does not exist`);
 }
 }

 if (to && to !== 'END') {
 if (!nodeIds.has(to)) {
 errors.push(`Edge ${idx + 1}: "to" node "${to}" does not exist`);
 }
 }

 // Check conditional edges
 if (edge.condition && edge.condition.routes) {
 const routes = edge.condition.routes;
 Object.values(routes).forEach(target => {
 if (target && target !== 'END' && !nodeIds.has(target)) {
 errors.push(`Edge ${idx + 1}: Conditional route "${target}" does not exist`);
 }
 });
 }

 // Track edge references for reachability check
 if (from && from !== 'START') edgeRefs.add(from);
 if (to && to !== 'END') edgeRefs.add(to);
 if (edge.condition && edge.condition.routes) {
 Object.values(edge.condition.routes).forEach(target => {
 if (target && target !== 'END') edgeRefs.add(target);
 });
 }
 });

 // 5. Check for unreachable nodes (nodes not referenced by any edge)
 if (nodes.length > 0 && edges.length > 0) {
 const entryNodeId = entryNodes.length > 0 ? entryNodes[0].id : nodes[0].id;
 const reachable = new Set([entryNodeId]);
 let changed = true;

 // Simple reachability: mark nodes reachable from START/entry
 while (changed) {
 changed = false;
 edges.forEach(edge => {
 const from = edge.from === 'START' ? entryNodeId : edge.from;
 if (reachable.has(from)) {
 const to = edge.to === 'END' ? null : edge.to;
 if (to && !reachable.has(to)) {
 reachable.add(to);
 changed = true;
 }
 // Check conditional routes
 if (edge.condition && edge.condition.routes) {
 Object.values(edge.condition.routes).forEach(target => {
 if (target && target !== 'END' && !reachable.has(target)) {
 reachable.add(target);
 changed = true;
 }
 });
 }
 }
 });
 }

 nodes.forEach(node => {
 if (!reachable.has(node.id) && node.type !== 'entry') {
 warnings.push(`Node "${node.id}" may be unreachable from entry point`);
 }
 });
 }

 // 6. Check for basic cycles (simple check: if node points to itself or immediate cycle)
 edges.forEach((edge, idx) => {
 if (edge.from === edge.to && edge.from !== 'START' && edge.to !== 'END') {
 warnings.push(`Edge ${idx + 1}: Node "${edge.from}" points to itself (potential infinite loop)`);
 }
 });

 return { errors, warnings, valid: errors.length === 0 };
 }

 // Show validation errors in wizard
