 // Create workflow from wizard data
 async function createWorkflowFromWizard() {
 try {
 const workflowName = document.getElementById('wizardWorkflowName').value.trim();
 const description = document.getElementById('wizardDescription').value.trim();

 // Collect state schema
 const stateSchema = {
 query: 'str',
 messages: 'list'
 };
 document.querySelectorAll('.state-var-row').forEach(row => {
 const nameInput = row.querySelector('.state-var-name');
 const typeSelect = row.querySelector('.state-var-type');
 if (nameInput && typeSelect && nameInput.value.trim()) {
 stateSchema[nameInput.value.trim()] = typeSelect.value;
 }
 });

 // Find entry point
 let entryPoint = null;
 for (const node of wizardNodes) {
 if (node.type === 'entry') {
 entryPoint = node.id;
 break;
 }
 }
 if (!entryPoint && wizardNodes.length > 0) {
 entryPoint = wizardNodes[0].id;
 }

 // Prepare request data
 const requestData = {
 workflow_name: workflowName,
 description: description || `Hierarchical workflow: ${workflowName}`,
 state_schema: stateSchema,
 nodes: wizardNodes,
 edges: wizardEdges,
 entry_point: entryPoint
 };

 // Call API
 const response = await fetchWithAuth('/api/workflow/hierarchical', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json'
 },
 body: JSON.stringify(requestData)
 });

 const result = await response.json();

 if (response.ok) {
 // Close modal
 closeWizardModal();

 // Show success message
 showMessage(`Workflow "${workflowName}" created successfully!`, 'success');

 // Refresh workflow list
 await loadWorkflowList();

 // Select the newly created workflow
 if (result.workflow && result.workflow.id) {
 setTimeout(() => {
 selectWorkflowCard(result.workflow.id);
 }, 500);
 }
 } else {
 showMessage(`Error: ${result.detail || 'Failed to create workflow'}`, 'error');
 }

 } catch (error) {
 console.error('Error creating workflow:', error);
 showMessage(`Error creating workflow: ${error.message}`, 'error');
 }
 }
