 backdrop-filter: blur(12px);
 -webkit-backdrop-filter: blur(12px);
 border: 1px solid var(--border); 
 border-radius: 24px; 
 padding: 24px; 
 transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
 position: relative;
 overflow: hidden;
 }

 .glass-card::before {
 content: '';
 position: absolute;
 top: 0; left: 0; right: 0; height: 1px;
 background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
 }

 .glass-card:hover { 
 transform: translateY(-4px);
 border-color: rgba(99, 102, 241, 0.5); 
 box-shadow: 0 15px 30px -10px rgba(0, 0, 0, 0.5); 
 }

 label {
 color: var(--text-label);
 font-weight: 600;
 font-size: 0.85rem;
 margin-bottom: 8px;
 letter-spacing: 0.5px;
 }

 .form-control, .form-select { 
 background: #0a0a0a; 
 border: 1px solid var(--border); 
 color: #fff; 
 border-radius: 12px; 
 padding: 14px; 
 font-weight: 500;
 }

 .form-control:focus, .form-select:focus { 
 background: #000; 
 border-color: var(--accent); 
 box-shadow: 0 0 0 4px rgba(99, 102, 241, 0.15); 
 color: #fff; 
 }

 .btn-add { 
 background: linear-gradient(135deg, var(--accent), #4f46e5); 
 color: #fff; 
 border: none; 
 border-radius: 14px; 
 font-weight: 700; 
 padding: 16px; 
 transition: transform 0.1s;
 box-shadow: 0 4px 20px rgba(99, 102, 241, 0.3);
 }

 .btn-add:hover { 
 box-shadow: 0 6px 25px rgba(99, 102, 241, 0.5);
 color: white;
 }

 .btn-add:active { 
 transform: scale(0.97); 
 }

 .ledger-item { 
 background: rgba(255,255,255,0.02);
 border: 1px solid transparent;
 padding: 16px; 
 margin-bottom: 12px;
 border-radius: 16px; 
 transition: all 0.2s;
 cursor: pointer;
 }

 .ledger-item:hover { 
 background: rgba(255,255,255,0.05); 
 border-color: var(--border);
 transform: translateX(5px);
 }

 .badge-type { 
 font-size: 0.65rem; 
 padding: 4px 8px; 
 border-radius: 6px; 
 font-weight: 700; 
 text-transform: uppercase; 
 }

 .credit-badge { background: rgba(16, 185, 129, 0.15); color: #34d399; }
 .debit-badge { background: rgba(99, 102, 241, 0.15); color: #818cf8; }

 .heat-cell { 
 width: 100%; 
 aspect-ratio: 1; 
 border-radius: 6px; 
 background: #18181b; 
 transition: transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275); 
 }

 .heat-cell:hover { 
 transform: scale(1.5); 
 z-index: 10; 
 box-shadow: 0 0 10px var(--accent); 
 }

 .chart-wrapper { position: relative; height: 200px; width: 100%; }

 ::-webkit-scrollbar { width: 6px; }
 ::-webkit-scrollbar-track { background: var(--bg); }
 ::-webkit-scrollbar-thumb { background: #333; border-radius: 10px; }
 ::-webkit-scrollbar-thumb:hover { background: var(--accent); }

 .floating-header {
 animation: float 6s ease-in-out infinite;
 }

 @keyframes float {
 0% { transform: translateY(0px); }
 50% { transform: translateY(-10px); }
 100% { transform: translateY(0px); }
 }

 .pop-in { animation: popIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; opacity: 0; transform: scale(0.9); }
 @keyframes popIn { to { opacity: 1; transform: scale(1); } }
