<script>
 let charts = {};
 document.getElementById('currentDate').valueAsDate = new Date();

 function refreshUI() { loadHistory(); loadAnalytics(); }
 function refreshUIWithAnim() { 
 $('#ledger').fadeOut(200, function() {
 loadHistory(); 
 $(this).fadeIn(200);
 });
 loadAnalytics();
 }

 $('#sourceApp').on('change', function() {
 if($(this).val() === 'Cash') {
 $('#digitalFields').slideUp(300);
 $('#paymentType').val('Debit');
 } else {
 $('#digitalFields').slideDown(300);
 }
 });

 $('#isRefundSwitch').on('change', function() {
 const isChecked = $(this).is(':checked');
 $('#is_refund_val').val(isChecked ? 'true' : 'false');
 if(isChecked) {
 $('#submitBtn').removeClass('btn-add').addClass('btn-success').html('<i class="bi bi-arrow-down-left me-2"></i> Log Income');
 } else {
 $('#submitBtn').removeClass('btn-success').addClass('btn-add').html('<i class="bi bi-plus-lg me-2"></i> Record Transaction');
 }
 });

 function loadHistory() {
 $.get('/history', function(data) {
 let html = '', total = 0;
 let delay = 0;

 data.forEach((t) => {
 total += t.is_refund ? -t.amount : t.amount;
 const badge = t.payment_type === 'Credit' ? 'credit-badge' : 'debit-badge';
 const date = new Date(t.transaction_date).toLocaleDateString('en-IN', {day:'2-digit', month:'short'});
 const icon = t.is_refund ? 'bi-arrow-down-left-circle-fill text-success' : 'bi-arrow-up-right-circle text-muted';

 html += `
 <div class="ledger-item d-flex justify-content-between align-items-center animate-in" style="animation-delay: ${delay}ms; animation-duration: 0.4s">
 <div class="d-flex align-items-center">
 <div class="me-3 fs-4"><i class="bi ${icon}"></i></div>
 <div>
 <div class="fw-bold text-white mb-1" style="font-size: 0.95rem;">${t.vendor_name || t.category}</div>
 <div class="small text-secondary fw-medium" style="font-size: 0.75rem;">${date} • <span class="text-white opacity-75">${t.source_app}</span> • ${t.sub_category || ''}</div>
 </div>
 </div>
 <div class="text-end">
 <div class="fw-bold fs-5 mb-1 ${t.is_refund ? 'text-success' : 'text-white'}">
 ${t.is_refund ? '+' : ''}₹${t.amount.toLocaleString('en-IN')}
 </div>
 <div class="d-flex gap-2 justify-content-end align-items-center">
 <span class="badge-type ${badge}">${t.payment_type}</span>
 <i class="bi bi-pencil-fill text-secondary opacity-25 ms-2 edit-btn transition-transform" style="cursor:pointer; font-size: 0.8rem" onclick='openEdit(${JSON.stringify(t)})'></i>
 <i class="bi bi-trash-fill text-danger opacity-25 delete-btn transition-transform" style="cursor:pointer; font-size: 0.8rem" onclick="deleteItem(${t.id})"></i>
 </div>
 </div>
 </div>`;
 delay += 50; 
 });
 $('#ledger').html(html || '<div class="text-center py-5 text-secondary opacity-25"><i class="bi bi-inbox fs-1 d-block mb-3"></i>Empty Treasury</div>');
 $('#grandTotal').text('₹' + total.toLocaleString('en-IN'));
 });
 }

 function updateHeatmap(dailyData) {
 let html = '';
 const now = new Date();
 const amounts = Object.values(dailyData);
 const maxSpend = Math.max(...amounts, 1);

 for (let i = 29; i >= 0; i--) {
 const d = new Date();
 d.setDate(now.getDate() - i);
 const dateStr = d.toISOString().split('T')[0];
 const spend = dailyData[dateStr] || 0;
 const intensity = spend > 0 ? (spend / maxSpend) : 0;

 let color;
 if (spend === 0) color = '#18181b';
 else color = `rgba(99, 102, 241, ${0.3 + (intensity * 0.7)})`;

 html += `<div class="heat-cell" style="background-color: ${color}" data-bs-toggle="tooltip" title="${dateStr}: ₹${spend}"></div>`;
 }
 $('#heatmapGrid').html(html);
 }

 function openEdit(t) {
 $('#editId').val(t.id);
 $('#editDate').val(t.transaction_date);
 $('#editAmount').val(t.amount);
 $('#editCategory').val(t.category);
 $('#editSource').val(t.source_app);
 $('#editType').val(t.payment_type);
 $('#editVendor').val(t.vendor_name);
 $('#editSubCat').val(t.sub_category);
 new bootstrap.Modal('#editModal').show();
 }

 $('#editForm').on('submit', function(e) {
 e.preventDefault();
 $.ajax({
 url: `/update/${$('#editId').val()}`,
 type: 'PUT',
 data: $(this).serialize(),
 success: function() {
 bootstrap.Modal.getInstance('#editModal').hide();
 refreshUI();
 }
 });
 });

 function loadAnalytics() {
 $.get('/analytics', function(data) {
 updateBarChart(data.daily);
 updatePieChart(data.apps);
 updateHeatmap(data.daily);
 });
 }

 function updateBarChart(dailyData) {
 const ctx = document.getElementById('barChart').getContext('2d');
 if(charts.bar) charts.bar.destroy();

 const gradient = ctx.createLinearGradient(0, 0, 0, 400);
 gradient.addColorStop(0, '#6366f1');
 gradient.addColorStop(1, 'rgba(99, 102, 241, 0.1)');

 charts.bar = new Chart(ctx, {
 type: 'bar',
 data: {
 labels: Object.keys(dailyData).slice(-7).map(d => d.split('-')[2]),
 datasets: [{ 
 data: Object.values(dailyData).slice(-7), 
 backgroundColor: gradient, 
 borderRadius: 6,
 barThickness: 20,
 hoverBackgroundColor: '#818cf8'
 }]
 },
 options: { 
 responsive: true, maintainAspectRatio: false, 
 plugins: { legend: { display: false }, tooltip: { backgroundColor: '#000', titleFont: {family: 'Outfit'}, bodyFont: {family: 'Plus Jakarta Sans'} } },
 scales: { 
 y: { display: false }, 
 x: { grid: { display: false }, ticks: { color: '#71717a', font: {family: 'Plus Jakarta Sans', weight: '600'} } } 
 },
 animation: { duration: 800, easing: 'easeOutQuart' }
 }
 });
 }

 function updatePieChart(appData) {
 const ctx = document.getElementById('pieChart').getContext('2d');
 if(charts.pie) charts.pie.destroy();
 charts.pie = new Chart(ctx, {
 type: 'doughnut',
 data: {
 labels: Object.keys(appData),
 datasets: [{ 
 data: Object.values(appData), 
 backgroundColor: ['#6366f1', '#818cf8', '#a5b4fc', '#c7d2fe', '#e0e7ff'], 
 borderWidth: 0,
 hoverOffset: 15
 }]
 },
 options: { 
 responsive: true, maintainAspectRatio: false, cutout: '75%',
 plugins: { legend: { position: 'right', labels: { color: '#a1a1aa', usePointStyle: true, font: {family: 'Plus Jakarta Sans', size: 11} } } },
 animation: { animateScale: true, animateRotate: true }
 }
 });
 }

 function deleteItem(id) { 
 if(confirm("Confirm deletion?")) {
 $.ajax({ url: `/delete/${id}`, type: 'DELETE', success: refreshUI }); 
 }
 }

 $('#expenseForm').on('submit', function(e) {
 e.preventDefault();
 const btn = $('#submitBtn');
 const originalText = btn.html();
 btn.prop('disabled', true).html('<span class="spinner-border spinner-border-sm"></span> Processing...');

 $.post('/add-expense', $(this).serialize(), function() { 
 confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 }, colors: ['#6366f1', '#10b981'] });
 refreshUI(); 
 $('#expenseForm')[0].reset(); 
 document.getElementById('currentDate').valueAsDate = new Date();

 setTimeout(() => {
 btn.prop('disabled', false).removeClass('btn-success').addClass('btn-add').html('<i class="bi bi-check-lg me-2"></i> Saved!');
 setTimeout(() => btn.html(originalText), 2000);
 }, 500);
 });
 });

 $(document).ready(refreshUI);
</script>
</body>
</html>

