 <div class="small text-muted d-flex align-items-center gap-2">
 <span class="badge bg-secondary bg-opacity-25 text-light fw-normal" style="font-size: 0.7rem">${t.source_app}</span>
 <span class="text-truncate" style="max-width: 150px;">${t.sub_category || ''}</span>
 </div>
 </div>
 </div>
 <div class="text-end">
 <div class="fs-5 fw-bold mb-1" style="color: ${amountColor}">${sign}₹${t.amount.toLocaleString('en-IN')}</div>
 <div class="d-flex justify-content-end gap-2 text-muted opacity-50 small">
 <i class="bi bi-pencil-square" onclick='openEdit(${JSON.stringify(t)})' style="cursor:pointer"></i>
 <i class="bi bi-trash-fill hover-danger" onclick="deleteItem(${t.id})" style="cursor:pointer"></i>
 </div>
 </div>
 </div>
 `;
 });

 $('#ledger').html(html || '<div class="text-center py-5 text-muted opacity-50">Treasury is empty. Start recording.</div>');

 // Animate total
 $({ val: 0 }).animate({ val: total }, {
 duration: 1000,
 easing: 'swing',
 step: function() { $('#grandTotal').text('₹' + Math.ceil(this.val).toLocaleString('en-IN')); }
 });
 });
 }

 function updateHeatmap(dailyData) {
 let html = '';
 const now = new Date();
 const amounts = Object.values(dailyData);
 const maxSpend = Math.max(...amounts, 1);

 for (let i = 29; i >= 0; i--) {
 const d = new Date();
 d.setDate(now.getDate() - i);
 const dateStr = d.toISOString().split('T')[0];
 const spend = dailyData[dateStr] || 0;

 let bg = 'rgba(255,255,255,0.05)';
 if(spend > 0) {
 const opacity = 0.2 + (spend / maxSpend) * 0.8;
 bg = `rgba(99, 102, 241, ${opacity})`;
 }

 html += `<div class="heat-cell" style="background-color: ${bg}" data-bs-toggle="tooltip" title="${dateStr}: ₹${spend}"></div>`;
 }
 $('#heatmapGrid').html(html);
 }

 function openEdit(t) {
 $('#editId').val(t.id);
 $('#editDate').val(t.transaction_date);
 $('#editAmount').val(t.amount);
 $('#editCategory').val(t.category);
 $('#editSource').val(t.source_app);
 $('#editSubCat').val(t.sub_category);
 new bootstrap.Modal('#editModal').show();
 }

 $('#editForm').on('submit', function(e) {
 e.preventDefault();
 $.ajax({
 url: `/update/${$('#editId').val()}`,
 type: 'PUT',
 data: $(this).serialize(),
 success: function() {
 bootstrap.Modal.getInstance('#editModal').hide();
 refreshUI();
 }
 });
 });

 function loadAnalytics() {
 $.get('/analytics', function(data) {
 updateCharts(data);
 });
 }

 function updateCharts(data) {
 // Bar Chart
 const ctxBar = document.getElementById('barChart').getContext('2d');
 if(charts.bar) charts.bar.destroy();

 const gradientBar = ctxBar.createLinearGradient(0, 0, 0, 300);
 gradientBar.addColorStop(0, '#818cf8');
 gradientBar.addColorStop(1, 'rgba(99, 102, 241, 0.1)');

 charts.bar = new Chart(ctxBar, {
 type: 'bar',
 data: {
 labels: Object.keys(data.daily).slice(-7).map(d => d.split('-')[2]),
 datasets: [{ 
 data: Object.values(data.daily).slice(-7), 
 backgroundColor: gradientBar,
 borderRadius: 4,
 barThickness: 12
 }]
 },
 options: { 
 responsive: true, maintainAspectRatio: false,
 plugins: { legend: { display: false } },
 scales: { 
 y: { display: false }, 
 x: { grid: { display: false }, ticks: { color: '#64748b' } } 
 }
 }
 });

 // Pie Chart
 const ctxPie = document.getElementById('pieChart').getContext('2d');
 if(charts.pie) charts.pie.destroy();

 charts.pie = new Chart(ctxPie, {
 type: 'doughnut',
 data: {
 labels: Object.keys(data.apps),
 datasets: [{ 
 data: Object.values(data.apps), 
 backgroundColor: ['#6366f1', '#a855f7', '#ec4899', '#14b8a6', '#f43f5e'],
 borderWidth: 0,
 }]
 },
 options: { 
 responsive: true, maintainAspectRatio: false, cutout: '80%',
 plugins: { legend: { position: 'right', labels: { boxWidth: 8, color: '#94a3b8', font: {size: 10} } } } 
 }
 });

 updateHeatmap(data.daily);
 }

 function deleteItem(id) { 
 if(confirm("Remove this entry?")) {
 $.ajax({ url: `/delete/${id}`, type: 'DELETE', success: refreshUI }); 
 }
 }

 function refreshUI() {
 loadHistory();
 loadAnalytics();
 }

 $('#expenseForm').on('submit', function(e) {
 e.preventDefault();
 const btn = $('#submitBtn');
 const orig = btn.html();
 btn.prop('disabled', true).html('<span class="spinner-border spinner-border-sm"></span> Saving...');

 $.post('/add-expense', $(this).serialize(), function() { 
 refreshUI(); 
 $('#expenseForm')[0].reset(); 
 document.getElementById('currentDate').valueAsDate = new Date();
 btn.prop('disabled', false).html(orig);
 });
 });

 // Initial Load
 $(document).ready(refreshUI);

 // CSS Keyframes injection for JS interactions
 const styleSheet = document.createElement("style");
 styleSheet.innerText = `
 @keyframes slideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
 `;
 document.head.appendChild(styleSheet);
</script>
</body>
</html>

