 const logoLine1 = document.getElementById('logo-line1');
 const logoLine2 = document.getElementById('logo-line2');

 setTimeout(() => {
 animateLogoText(logoLine1, 'PivotBridge', () => {
 animateLogoText(logoLine2, 'Labs');
 });
 }, 200);

