 console.log(response);
 demoResult.innerHTML = "Something went wrong! Please try again later.";
 demoResult.style.color = 'red'; // Error color
 }
 })
 .catch(error => {
 console.log(error);
 demoResult.innerHTML = "Network error. Please check your connection and try again.";
 demoResult.style.color = 'red'; // Error color
 })
 .finally(function() {
 demoForm.reset();
 setTimeout(() => {
 demoResult.innerHTML = ""; // Clear message
 $('#scheduleDemoModal').modal('hide'); // Close modal after submission
 }, 3000);
 });
 });
