 scene.add(core);

 // --- Particle System (from Design 1) ---
 const particlesGeometry = new THREE.BufferGeometry();
 const particlesCount = 7000;
 const posArray = new Float32Array(particlesCount * 3);

 for (let i = 0; i < particlesCount * 3; i++) {
 posArray[i] = (Math.random() - 0.5) * 30;
 }
 particlesGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));

 const particlesMaterial = new THREE.PointsMaterial({
 size: 0.015,
 color: 0x00c6ff, /* Using accent for particles */
 transparent: true,
 blending: THREE.AdditiveBlending
 });
 particles = new THREE.Points(particlesGeometry, particlesMaterial);
 scene.add(particles);

 camera.position.z = targetZ;

 window.addEventListener('resize', onWindowResize, false);
 document.addEventListener('scroll', onScroll, false);
 animate();
 }

 function onWindowResize() {
 camera.aspect = window.innerWidth / window.innerHeight;
 camera.updateProjectionMatrix();
 renderer.setSize(window.innerWidth, window.innerHeight);
 }

 function onScroll() {
 scrollY = window.scrollY;
 // Adjust scroll percentage for the new layout (features section is lighter)
 const scrollPercent = scrollY / (document.body.scrollHeight - window.innerHeight);
 // Adjust targetZ to make the zoom less aggressive or tuned to the new content flow
 targetZ = 15 - (scrollPercent * 10); // Reduced zoom effect
 }

 const clock = new THREE.Clock();
 function animate() {
 requestAnimationFrame(animate);
 const elapsedTime = clock.getElapsedTime();

 // Animate particles and core
 particles.rotation.y = elapsedTime * 0.05;
 core.rotation.x = elapsedTime * 0.1;
 core.rotation.y = elapsedTime * 0.1;
 core.rotation.z = elapsedTime * 0.08;

 // Smoothly interpolate camera position
 camera.position.z += (targetZ - camera.position.z) * 0.05;

 renderer.render(scene, camera);
 }

 init3D();

 // Smooth scrolling for anchor links (from Design 2)
 $('a[href^="#"]').on('click', function(e) {
 e.preventDefault();
 var target = $(this.getAttribute('href'));
 if(target.length) {
 $('html, body').animate({
 scrollTop: target.offset().top - 80 // Adjust for fixed navbar
 }, 800);
 }
 });
