 // Adjust targetZ to make the zoom less aggressive or tuned to the new content flow
 targetZ = 15 - (scrollPercent * 10); // Reduced zoom effect
 }

 const clock = new THREE.Clock();
 function animate() {
 requestAnimationFrame(animate);
 const elapsedTime = clock.getElapsedTime();

 // Animate particles and core
 particles.rotation.y = elapsedTime * 0.05;
 core.rotation.x = elapsedTime * 0.1;
 core.rotation.y = elapsedTime * 0.1;
 core.rotation.z = elapsedTime * 0.08;

 // Smoothly interpolate camera position
 camera.position.z += (targetZ - camera.position.z) * 0.05;

 renderer.render(scene, camera);
 }

 init3D();

