from .invalid_argument_error import InvalidArgumentError
from .matrix import Matrix
from .path import Path
from .path_not_found_error import PathNotFoundError
from .position import Position
from .sequence import Sequence

class PathFinder:
 def __init__(
 self, matrix: Matrix, sequences: list[Sequence], max_path_length: int
 ) -> None:
 self.matrix = matrix
 self.sequences = sequences
 self.max_path_length = max_path_length
 self.rows = matrix.row_count
 self.cols = matrix.column_count
 self.best_path = None
 self.best_score = -1

 if not self.matrix.values:
 raise InvalidArgumentError("Matrix should be non-empty")
 if not self.sequences:
 raise InvalidArgumentError("There should be at least one sequence")
 for seq in self.sequences:
 if not seq.codes:
 raise InvalidArgumentError("All sequences should be non-empty")
 if seq.score <= 0:
 raise InvalidArgumentError("All sequences should have a score greater than zero")
 if self.max_path_length <= 0:
 raise InvalidArgumentError("Maximum path length should be greater than zero")

 def run(self) -> Path:
 for col in range(self.cols):
 self._dfs([(0, col)], set([(0, col)]), 0, [])
 if not self.best_path:
 raise PathNotFoundError("Path not found")
 return Path([Position(r, c) for r, c in self.best_path])

 def _dfs(self, path, visited, score, completed_sequences):
 if len(path) > self.max_path_length:
 return

 current_code = self.matrix.value(path[-1][0], path[-1][1])
 new_completed_sequences = self._update_completed_sequences(completed_sequences, current_code)
 new_score = self._calculate_score(new_completed_sequences)

 if new_score > self.best_score or (new_score == self.best_score and len(path) < len(self.best_path or [])):
 self.best_score = new_score
 self.best_path = path[:]

 if len(new_completed_sequences) == len(self.sequences) or len(path) == self.max_path_length:
 return

 row, col = path[-1]
 if len(path) % 2 == 1: # Move in the same column
 for r in range(self.rows):
 if (r, col) not in visited:
 self._dfs(path + [(r, col)], visited | {(r, col)}, new_score, new_completed_sequences)
 else: # Move in the same row
 for c in range(self.cols):
 if (row, c) not in visited:
 self._dfs(path + [(row, c)], visited | {(row, c)}, new_score, new_completed_sequences)

 def _update_completed_sequences(self, completed_sequences, current_code):
 new_completed_sequences = completed_sequences[:]
 temp_sequences = []
 for seq in self.sequences:
 temp_sequences.append(seq.codes[:])

 for i, seq in enumerate(temp_sequences):
 if i not in new_completed_sequences:
 if len(seq) > 0 and seq[0] == current_code:
 if len(seq) == 1:
 new_completed_sequences.append(i)
 else:
 temp_sequences[i] = seq[1:]

 for i, seq in enumerate(self.sequences):
 self.sequences[i].codes = temp_sequences[i]

 return new_completed_sequences

 def _calculate_score(self, completed_sequences):
 score = 0
 for i in completed_sequences:
 score += self.sequences[i].score
 return score

