 1. Backend: Add the New Download Endpoint ( main.py ) 

 Add this new API endpoint to your main.py file. It's almost identical to your existing download_los_file endpoint but queries the correct table ( synthetic_audio_generations ). 

 # main.py

# ... (all your other imports and endpoints) ...

@app.get("/download/synthetic_audio/{request_id}", summary="Download a generated Synthetic Audio file (No Auth)")
async def download_synthetic_audio_file(
 request_id: str,
 db: Session = Depends(get_db)
):
 """
 Finds a Synthetic Audio record by ID, downloads the result from GCS,
 and streams it directly to the client.
 """
 logger.info(f"Public download requested for synthetic audio job {request_id}.")

 # Query the correct table: synthetic_audio_generations
 job = db.query(models.SyntheticAudioGeneration).filter(
 models.SyntheticAudioGeneration.request_id == request_id
 ).first()

 if not job:
 raise HTTPException(status_code=404, detail="Record not found.")

 if job.task_status != models.TaskStatus.SUCCESS or not job.storage_path:
 raise HTTPException(
 status_code=404,
 detail="The requested file is not available. The job may still be processing or has failed."
 )

 try:
 gcs_path = job.storage_path
 bucket_name = gcs_path.split("/")[2]
 blob_name = "/".join(gcs_path.split("/")[3:])

 file_name = os.path.basename(blob_name)
 file_stream = get_blob_stream(bucket_name, blob_name)

 # Determine the media type from the filename (mp3 or zip)
 media_type = "application/zip" if file_name.endswith(".zip") else "audio/mpeg"

 headers = {
 'Content-Disposition': f'attachment; filename="{file_name}"'
 }

 return StreamingResponse(file_stream, media_type=media_type, headers=headers)

 except Exception as e:
 logger.exception(f"Failed to stream download for synthetic audio request_id {request_id}.")
 raise HTTPException(status_code=500, detail="An internal error occurred while preparing the download.")

