 fields.forEach(id => {
 const value = $(`#${id}`).val();
 if(value) curl += `--form '${id}="${value.replace(/"/g, '\\"')}"' \\\n`;
 });
 curl += `--form 'structured="${$('#structured').is(':checked')}"' \\\n`;

 $('.custom-param-row').each(function() {
 const key = $(this).find('.param-key').val();
 const value = $(this).find('.param-value').val();
 if (key && value) {
 curl += `--form '${key}="${value.replace(/"/g, '\\\\"')}"' \\\n`;
 }
 });

 const attachEl = document.getElementById('text_attachment');
 if (attachEl && attachEl.files && attachEl.files[0]) {
 curl += `--form 'attachment=@/${attachEl.files[0].name}'`;
