 fields.forEach(id => formData.append(id, $(`#${id}`).val()));
 formData.append('structured', $('#structured').is(':checked'));

 const attachmentEl = document.getElementById('text_attachment');
 if (attachmentEl && attachmentEl.files && attachmentEl.files[0]) {
 formData.append('attachment', attachmentEl.files[0]);
 }

 $('.custom-param-row').each(function() {
 const key = $(this).find('.param-key').val();
 const value = $(this).find('.param-value').val();
 if (key && value) formData.append(key, value);
 });

 fetch(`${API_BASE_URL}/generate-text`, {
 method: 'POST',
 body: formData,
 })
 .then(response => {
 if (!response.ok) return response.json().then(err => { throw new Error(err.detail || 'API request failed') });
 return response.json();
 })
 .then(data => {
 const format = $('#output_format').val();
 let displayData = data.output;
 if (format === 'JSON') {
 try { displayData = JSON.stringify(JSON.parse(data.output), null, 2); } catch (e) {}
 }
 $('#resultContent').text(displayData);
 $('#copyBtn, #downloadBtn').prop('disabled', false);
 })
 .catch(error => {
 $('#resultContent').html(`<div class="alert alert-danger">${error.message}</div>`);
 })
 .finally(() => {
