 function updateLosCurlCommand() {
 const files = $('#input_files')[0].files;
 let curl = `curl --location '${API_BASE_URL}/LOS_generation' \\\n`;
 curl += `--header 'Authorization: Bearer ${$('#google_token').val() || 'YOUR_GOOGLE_ID_TOKEN'}' \\\n`;

 const fields = ['record_name', 'record_type', 'los_num_records'];
 const fieldMap = {
 'record_name': 'record_name',
 'record_type': 'record_type', 
 'los_num_records': 'num_records'
 };

 fields.forEach(id => {
 const value = $(`#${id}`).val();
 if(value) curl += `--form '${fieldMap[id]}="${value.replace(/"/g, '\\"')}"' \\\n`;
 });

 if (files && files.length > 0) {
