 <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
 <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
 <script>
 $(document).ready(function() {
 const API_BASE_URL = 'http://127.0.0.1:8000';

 // ===== TEXT GENERATION SCRIPT =====
 $('#addParamBtn').click(function() {
 const paramRow = `<div class="custom-param-row mt-2"><div class="row g-2"><div class="col-md-5"><input type="text" class="form-control param-key" placeholder="Parameter name"></div><div class="col-md-5"><input type="text" class="form-control param-value" placeholder="Parameter value"></div><div class="col-md-2"><button type="button" class="btn btn-outline-danger w-100 remove-param"><i class="bi bi-trash"></i></button></div></div></div>`;
 $('#customParamsContainer').append(paramRow);
 updateCurlCommand();
 });
 $(document).on('click', '.remove-param', function() { $(this).closest('.custom-param-row').remove(); updateCurlCommand(); });
 $('#textGenForm').on('input change', updateCurlCommand);
 $('#textGenForm').submit(function(e) { e.preventDefault(); generateContent(); });
 $('#copyBtn').click(function() { const content = $('#resultContent').text(); navigator.clipboard.writeText(content); const originalText = $(this).html(); $(this).html('<i class="bi bi-check2 me-1"></i>Copied!'); setTimeout(() => { $(this).html(originalText); }, 2000); });
 $('#downloadBtn').click(function() { const content = $('#resultContent').text(); const format = $('#output_format').val(); let filename = `generated_content.${format.toLowerCase()}`; let mimeType = 'text/plain'; if(format === 'JSON') mimeType = 'application/json'; if(format === 'XML') mimeType = 'application/xml'; if(format === 'CSV') mimeType = 'text/csv'; const blob = new Blob([content], { type: mimeType }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url); });
 function updateCurlCommand() { let curl = `curl --location '${API_BASE_URL}/generate-text' \\\n`; const fields = ['instruction', 'output_format', 'num_records', 'language_style', 'text_length', 'sample_data']; fields.forEach(id => { const value = $(`#${id}`).val(); if(value) curl += `--form '${id}="${value.replace(/"/g, '\\"')}"' \\\n`; }); curl += `--form 'structured="${$('#structured').is(':checked')}"' \\\n`; $('.custom-param-row').each(function() { const key = $(this).find('.param-key').val(); const value = $(this).find('.param-value').val(); if (key && value) { curl += `--form '${key}="${value.replace(/"/g, '\\\\"')}"' \\\n`; } }); const attachEl = document.getElementById('text_attachment'); if (attachEl && attachEl.files && attachEl.files[0]) { curl += `--form 'attachment=@/${attachEl.files[0].name}'`; } else { curl = curl.slice(0, -2); } $('#curlCommand').text(curl.trim()); }
 function generateContent() { $('#generateSpinner').removeClass('d-none'); $('#generateText').text('Generating...'); $('#generateBtn').prop('disabled', true); $('#resultContent').html('<div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div><p class="mt-2">Generating content...</p></div>'); const formData = new FormData(); const fields = ['instruction', 'output_format', 'num_records', 'language_style', 'text_length', 'sample_data']; fields.forEach(id => formData.append(id, $(`#${id}`).val())); formData.append('structured', $('#structured').is(':checked')); const attachmentEl = document.getElementById('text_attachment'); if (attachmentEl && attachmentEl.files && attachmentEl.files[0]) { formData.append('attachment', attachmentEl.files[0]); } $('.custom-param-row').each(function() { const key = $(this).find('.param-key').val(); const value = $(this).find('.param-value').val(); if (key && value) formData.append(key, value); }); fetch(`${API_BASE_URL}/generate-text`, { method: 'POST', body: formData, }) .then(response => { if (!response.ok) return response.json().then(err => { throw new Error(err.detail || 'API request failed') }); return response.json(); }) .then(data => { const format = $('#output_format').val(); let displayData = data.output; if (format === 'JSON') { try { displayData = JSON.stringify(JSON.parse(data.output), null, 2); } catch (e) {} } $('#resultContent').text(displayData); $('#copyBtn, #downloadBtn').prop('disabled', false); }) .catch(error => { $('#resultContent').html(`<div class="alert alert-danger">${error.message}</div>`); }) .finally(() => { $('#generateSpinner').addClass('d-none'); $('#generateText').text('Generate Content'); $('#generateBtn').prop('disabled', false); }); }

 // ===== AUDIO SCRIPT =====
 $('#audioForm').on('input change', updateAudioCurlCommand);
 $('#audioForm').submit(function(e) { e.preventDefault(); generateAudio(); });
 $('#audioCopyBtn').click(function() { navigator.clipboard.writeText($('#audioResultContent').text()); const originalText = $(this).html(); $(this).html('<i class="bi bi-check2 me-1"></i>Copied!'); setTimeout(() => { $(this).html(originalText); }, 2000); });
 $('#audioDownloadBtn').click(function() { const content = $('#audioResultContent').text(); const blob = new Blob([content], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'transcripts.json'; a.click(); URL.revokeObjectURL(url); });
 function updateAudioCurlCommand() { const file = $('#audio_file')[0].files[0]; let curl = `curl --location '${API_BASE_URL}/generate-audio' \\\n--form 'file=@"${file ? file.name : '/path/to/your/audio.wav'}"'`; const fields = ['dataset_name', 'audio_instruction', 'number_of_clips', 'clip_duration', 'select_format', 'audio_type', 'download_type']; fields.forEach(id => { const value = $(`#${id}`).val(); if (value) { curl += ` \\\n--form '${id.replace('audio_', '')}="${value.replace(/"/g, '\\"')}"'`; } }); $('#audioCurlCommand').text(curl); }
 function generateAudio() { $('#audioSpinner').removeClass('d-none'); $('#generateAudioText').text('Generating...'); $('#audioGenerateBtn').prop('disabled', true); $('#audioResultContent').text('Processing...'); const fileInput = $('#audio_file')[0]; if (!fileInput.files.length) { $('#audioResultContent').html('<div class="alert alert-warning">Please select a file.</div>'); $('#audioSpinner').addClass('d-none'); $('#generateAudioText').text('Generate Transcript'); $('#audioGenerateBtn').prop('disabled', false); return; } const formData = new FormData(); formData.append('file', fileInput.files[0]); const fields = ['dataset_name', 'audio_instruction', 'number_of_clips', 'clip_duration', 'select_format', 'audio_type', 'download_type']; fields.forEach(id => { const value = $(`#${id}`).val(); if (value) formData.append(id.replace('audio_', ''), value); }); fetch(`${API_BASE_URL}/generate-audio`, { method: 'POST', body: formData }) .then(response => { if (!response.ok) return response.json().then(err => { throw new Error(err.detail || 'API request failed') }); return response.json(); }) .then(data => { $('#audioResultContent').text(JSON.stringify(data, null, 2)); $('#audioCopyBtn, #audioDownloadBtn').prop('disabled', false); }) .catch(error => { $('#audioResultContent').html(`<div class="alert alert-danger">${error.message}</div>`); }) .finally(() => { $('#audioSpinner').addClass('d-none'); $('#generateAudioText').text('Generate Transcript'); $('#audioGenerateBtn').prop('disabled', false); }); }

 // ===== NEW LOS SCRIPT =====
 $('#losForm').on('input change', updateLosCurlCommand);
 $('#losForm').submit(function(e) { e.preventDefault(); generateLos(); });
 function updateLosCurlCommand() {
 let curl = `curl --location '${API_BASE_URL}/LOS_generation' \\\n`;
 const fields = ['record_name', 'record_type', 'num_records_los'];
 fields.forEach(id => {
 const value = $(`#${id}`).val();
 if(value) curl += `--form '${id.replace('_los', '')}="${value.replace(/"/g, '\\"')}"' \\\n`;
 });

 const files = $('#input_files')[0].files;
 if (files.length > 0) {
 for(let i = 0; i < files.length; i++) {
 curl += `--form 'input_files=@"${files[i].name}"' \\\n`;
 }
 } else {
 curl += `--form 'input_files=@"/path/to/sample1.txt"' \\\n`;
 }
 $('#losCurlCommand').text(curl.slice(0, -2).trim());
 }
 function generateLos() {
 $('#losSpinner').removeClass('d-none');
 $('#generateLosText').text('Submitting...');
 $('#losGenerateBtn').prop('disabled', true);
 $('#losResultContent').text('Submitting request to the background processor...');

 const fileInput = $('#input_files')[0];
 if (!fileInput.files.length) {
 $('#losResultContent').html('<div class="alert alert-warning">Please select at least one reference file.</div>');
 $('#losSpinner').addClass('d-none');
 $('#generateLosText').text('Start Generation');
 $('#losGenerateBtn').prop('disabled', false);
 return;
 }

 const formData = new FormData();
 formData.append('record_name', $('#record_name').val());
 formData.append('record_type', $('#record_type').val());
 formData.append('num_records', $('#num_records_los').val());
 for(let i = 0; i < fileInput.files.length; i++) {
 formData.append('input_files', fileInput.files[i]);
 }

 fetch(`${API_BASE_URL}/LOS_generation`, {
 method: 'POST',
 body: formData
 })
 .then(response => {
 if (!response.ok) return response.json().then(err => { throw new Error(err.detail || 'API request failed') });
 return response.json();
 })
 .then(data => {
 $('#losResultContent').text(JSON.stringify(data, null, 2));
 // Maybe trigger a dashboard refresh
 setTimeout(() => $('#dashboard-tab').click(), 2000);
 })
 .catch(error => {
 $('#losResultContent').html(`<div class="alert alert-danger">${error.message}</div>`);
 })
 .finally(() => {
 $('#losSpinner').addClass('d-none');
 $('#generateLosText').text('Start Generation');
 $('#losGenerateBtn').prop('disabled', false);
 });
 }

 // ===== UPDATED DASHBOARD SCRIPT =====
 function renderRecordCard(record) {
 let badgeClass, iconClass, title, detailsContent;
 const createdAt = new Date(record.created_at).toLocaleString();
 const detailsId = `details-${record.request_id}`;

 switch(record.record_type) {
 case 'text':
 badgeClass = 'bg-primary';
 iconClass = 'bi-textarea-t';
 title = record.dataset_name || 'Untitled Text Gen';
 detailsContent = record.generated_output || 'No output.';
 break;
 case 'audio':
 badgeClass = 'bg-success';
 iconClass = 'bi-mic';
 title = record.dataset_name || 'Untitled Audio Gen';
 try { detailsContent = JSON.stringify(record.transcripts || [], null, 2); } 
 catch (e) { detailsContent = 'Could not parse transcripts.'; }
 break;
 case 'los':
 badgeClass = 'bg-warning text-dark';
 iconClass = 'bi-file-earmark-ruled';
 title = record.record_name || 'Untitled LOS Gen';
 let statusColor = 'text-muted';
 if (record.task_status === 'SUCCESS') statusColor = 'text-success';
 if (record.task_status === 'FAILED') statusColor = 'text-danger';
