 });

 function updateCurlCommand() {
 let curl = `curl --location '${API_BASE_URL}/generate-text' \\\n`;
 const fields = ['instruction', 'output_format', 'num_records', 'language_style', 'text_length', 'sample_data'];
 fields.forEach(id => {
 const value = $(`#${id}`).val();
 if(value) curl += `--form '${id}="${value.replace(/"/g, '\\"')}"' \\\n`;
 });
 curl += `--form 'structured="${$('#structured').is(':checked')}"' \\\n`;

 $('.custom-param-row').each(function() {
 const key = $(this).find('.param-key').val();
