 <script>
 $(document).ready(function() {
 const API_BASE_URL = 'http://127.0.0.1:8000';
 const USER_ID = 'test-user'; // Hardcoded for local testing

 function getStatusBadge(status) {
 switch(status) {
 case 'QUEUED': return '<span class="badge status-badge bg-secondary">Queued</span>';
 case 'GENERATING': return '<span class="badge status-badge bg-primary">Generating...</span>';
 case 'SUCCESS': return '<span class="badge status-badge bg-success">Success</span>';
 case 'FAILED': return '<span class="badge status-badge bg-danger">Failed</span>';
 default: return `<span class="badge status-badge bg-light text-dark">${status}</span>`;
 }
 }

 function renderRecordCard(record) {
 const createdAt = new Date(record.created_at).toLocaleString();
 let cardHtml = '';

 const title = record.dataset_name || record.record_name || 'Untitled';
 const detailsId = `details-${record.request_id}`;

 let typeInfo = {};
 switch(record.record_type) {
 case 'text':
 typeInfo = { badge: 'bg-info', icon: 'bi-textarea-t' };
 break;
 case 'audio':
 typeInfo = { badge: 'bg-warning', icon: 'bi-mic' };
 break;
