 if (record.record_type === 'los') {
 cardHtml += `<div class="mb-2"><strong>Status:</strong> ${getStatusBadge(record.task_status)}</div>`;
 if (record.storage_path) {
 cardHtml += `<p class="mb-1"><small><strong>Output:</strong> <code>${record.storage_path}</code></small></p>`;
 }
 if (record.task_status === 'FAILED' && record.error_message) {
 cardHtml += `<a class="btn btn-sm btn-outline-danger" data-bs-toggle="collapse" href="#${detailsId}" role="button">View Error</a>`;
 }
 } else {
 cardHtml += `<a class="btn btn-sm btn-outline-secondary" data-bs-toggle="collapse" href="#${detailsId}" role="button">View Details</a>`;
 }

 cardHtml += `<div class="collapse mt-3" id="${detailsId}"><div class="card card-body p-0"><pre class="details-pre mb-0"><code>`;

 if (record.record_type === 'text') {
 cardHtml += $('<textarea />').html(record.generated_output).text();
 } else if (record.record_type === 'audio') {
 cardHtml += JSON.stringify(record.transcripts, null, 2);
 } else if (record.record_type === 'los' && record.error_message) {
 cardHtml += $('<textarea />').html(record.error_message).text();
 }

 cardHtml += `</code></pre></div></div></div></div></div>`;
 return cardHtml;
