 <script>
 document.addEventListener('DOMContentLoaded', function() {
 const API_BASE_URL = 'http://127.0.0.1:8000';
 const recordsContent = document.getElementById('recordsContent');

 const STATUS_BADGES = {
 'QUEUED': 'bg-secondary',
 'GENERATING': 'bg-info text-dark',
 'SUCCESS': 'bg-success',
 'FAILED': 'bg-danger'
 };

 function getStatusBadge(status) {
 const badgeClass = STATUS_BADGES[status] || 'bg-dark';
 return `<span class="badge ${badgeClass} status-badge">${status}</span>`;
 }

 function renderRecordCard(record) {
 const createdAt = new Date(record.created_at).toLocaleString();
 const title = record.dataset_name || record.record_name || 'Untitled';
 const detailsId = `details-${record.request_id}`;

 let badgeHtml = '';
 let iconHtml = '';
 let detailsContent = '';
 let footerHtml = '';

 switch(record.record_type) {
 case 'text':
 badgeHtml = `<span class="badge bg-primary"><i class="bi bi-textarea-t me-1"></i> TEXT</span>`;
 detailsContent = record.generated_output || 'No output.';
 break;
 case 'audio':
 badgeHtml = `<span class="badge bg-info text-dark"><i class="bi bi-mic me-1"></i> AUDIO</span>`;
 detailsContent = JSON.stringify(record.transcripts || [], null, 2);
 break;
 case 'los':
 badgeHtml = `<span class="badge bg-success"><i class="bi bi-file-earmark-ruled me-1"></i> LOS</span>`;
 detailsContent = `Record Type: ${record.record_type}\nRecords Requested: ${record.num_records_requested}`;
 if (record.task_status === 'SUCCESS') {
 footerHtml = `<div class="mt-3"><strong>Output Location:</strong> <code class="d-block">${record.storage_path}</code></div>`;
 } else if (record.task_status === 'FAILED') {
 footerHtml = `<div class="mt-3 text-danger"><strong>Error:</strong> <pre class="mb-0">${record.error_message}</pre></div>`;
 }
 break;
 }

 return `
 <div class="col-md-6 col-lg-4">
 <div class="card">
 <div class="card-body">
 <div class="d-flex justify-content-between align-items-start">
 <div>
 <h5 class="card-title mb-1">${record.request_id}</h5>
 <h6 class="card-subtitle mb-2 text-muted">${title}</h6>
 </div>
 ${record.record_type === 'los' ? getStatusBadge(record.task_status) : badgeHtml}
 </div>
 <p class="card-text mb-2"><small class="text-muted">Created: ${createdAt}</small></p>
 <a class="btn btn-sm btn-outline-secondary" data-bs-toggle="collapse" href="#${detailsId}" role="button">
 View Details
 </a>
 <div class="collapse mt-3" id="${detailsId}">
 <pre class="details-pre"><code>${detailsContent}</code></pre>
 ${footerHtml}
 </div>
 </div>
 </div>
 </div>`;
 }

 function loadRecords(url) {
 recordsContent.innerHTML = '<div class="text-center py-5"><div class="spinner-border text-primary" role="status"></div><p class="mt-2">Loading records...</p></div>';

 fetch(API_BASE_URL + url)
 .then(response => {
 if (response.status === 404) return [];
 if (!response.ok) return response.json().then(err => { throw new Error(err.detail || `API Error: ${response.statusText}`) });
 return response.json();
 })
 .then(data => {
 recordsContent.innerHTML = '';
 if (data && data.length > 0) {
 data.forEach(record => recordsContent.insertAdjacentHTML('beforeend', renderRecordCard(record)));
 } else {
 recordsContent.innerHTML = '<div class="col-12"><div class="alert alert-info">No records found.</div></div>';
 }
 })
 .catch(error => {
 recordsContent.innerHTML = `<div class="col-12"><div class="alert alert-danger">${error.message}</div></div>`;
 });
 }

 document.getElementById('searchForm').addEventListener('submit', function(e) {
 e.preventDefault();
 const requestId = document.getElementById('searchRequestId').value.trim();
 const datasetName = document.getElementById('searchDatasetName').value.trim();
 const params = new URLSearchParams();
 if (requestId) params.append('request_id', requestId);
 if (datasetName) params.append('dataset_name', datasetName);
 loadRecords(`/records?${params.toString()}`);
 });

 document.getElementById('refreshBtn').addEventListener('click', function() {
 document.getElementById('searchForm').reset();
 loadRecords('/records');
 });

 // Initial load
 loadRecords('/records');
 });
 </script>
</body>
</html>

