 <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
 <script>
 $(document).ready(function() {
 const API_BASE_URL = 'http://127.0.0.1:8000';

 // ===== TEXT GENERATION SCRIPT =====
 $('#addParamBtn').click(function() {
 const paramRow = `<div class="custom-param-row mt-2"><div class="row g-2"><div class="col-md-5"><input type="text" class="form-control param-key" placeholder="Parameter name"></div><div class="col-md-5"><input type="text" class="form-control param-value" placeholder="Parameter value"></div><div class="col-md-2"><button type="button" class="btn btn-outline-danger w-100 remove-param"><i class="bi bi-trash"></i></button></div></div></div>`;
 $('#customParamsContainer').append(paramRow);
 updateCurlCommand();
 });

 $(document).on('click', '.remove-param', function() {
 $(this).closest('.custom-param-row').remove();
 updateCurlCommand();
 });

 $('#textGenForm').on('input change', updateCurlCommand);

 $('#textGenForm').submit(function(e) { e.preventDefault(); generateContent(); });

 $('#copyBtn').click(function() {
 const content = $('#resultContent').text();
 navigator.clipboard.writeText(content);
 const originalText = $(this).html();
 $(this).html('<i class="bi bi-check2 me-1"></i>Copied!');
 setTimeout(() => { $(this).html(originalText); }, 2000);
 });

 $('#downloadBtn').click(function() {
 const content = $('#resultContent').text();
 const format = $('#output_format').val();
 let filename = `generated_content.${format.toLowerCase()}`;
 let mimeType = 'text/plain';
 if(format === 'JSON') mimeType = 'application/json';
 if(format === 'XML') mimeType = 'application/xml';
 if(format === 'CSV') mimeType = 'text/csv';

 const blob = new Blob([content], { type: mimeType });
 const url = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = url;
 a.download = filename;
 document.body.appendChild(a);
 a.click();
 document.body.removeChild(a);
 URL.revokeObjectURL(url);
 });

 function updateCurlCommand() {
 let curl = `curl --location '${API_BASE_URL}/generate-text' \\\n`;
 const fields = ['instruction', 'output_format', 'num_records', 'language_style', 'text_length', 'sample_data'];
 fields.forEach(id => {
 const value = $(`#${id}`).val();
 if(value) curl += `--form '${id}="${value.replace(/"/g, '\\"')}"' \\\n`;
 });
 curl += `--form 'structured="${$('#structured').is(':checked')}"' \\\n`;

 $('.custom-param-row').each(function() {
 const key = $(this).find('.param-key').val();
 const value = $(this).find('.param-value').val();
 if (key && value) {
 curl += `--form '${key}="${value.replace(/"/g, '\\\\"')}"' \\\n`;
 }
 });

 const attachEl = document.getElementById('text_attachment');
 if (attachEl && attachEl.files && attachEl.files[0]) {
 curl += `--form 'attachment=@/${attachEl.files[0].name}'`;
 } else {
 curl = curl.slice(0, -2); // Remove last ' \'
 }

 $('#curlCommand').text(curl.trim());
 }

 function generateContent() {
 $('#generateSpinner').removeClass('d-none');
 $('#generateText').text('Generating...');
 $('#generateBtn').prop('disabled', true);
 $('#resultContent').html('<div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div><p class="mt-2">Generating content...</p></div>');

 const formData = new FormData();
 const fields = ['instruction', 'output_format', 'num_records', 'language_style', 'text_length', 'sample_data'];
 fields.forEach(id => formData.append(id, $(`#${id}`).val()));
 formData.append('structured', $('#structured').is(':checked'));

 const attachmentEl = document.getElementById('text_attachment');
 if (attachmentEl && attachmentEl.files && attachmentEl.files[0]) {
 formData.append('attachment', attachmentEl.files[0]);
 }

 $('.custom-param-row').each(function() {
 const key = $(this).find('.param-key').val();
 const value = $(this).find('.param-value').val();
 if (key && value) formData.append(key, value);
 });

 fetch(`${API_BASE_URL}/generate-text`, {
 method: 'POST',
 body: formData,
 })
 .then(response => {
 if (!response.ok) return response.json().then(err => { throw new Error(err.detail || 'API request failed') });
 return response.json();
 })
 .then(data => {
 const format = $('#output_format').val();
 let displayData = data.output;
 if (format === 'JSON') {
 try { displayData = JSON.stringify(JSON.parse(data.output), null, 2); } catch (e) {}
 }
 $('#resultContent').text(displayData);
 $('#copyBtn, #downloadBtn').prop('disabled', false);
 })
 .catch(error => {
 $('#resultContent').html(`<div class="alert alert-danger">${error.message}</div>`);
 })
 .finally(() => {
 $('#generateSpinner').addClass('d-none');
 $('#generateText').text('Generate Content');
 $('#generateBtn').prop('disabled', false);
 });
 }

 // ===== AUDIO SCRIPT =====
 $('#audioForm').on('input change', updateAudioCurlCommand);
 $('#audioForm').submit(function(e) { e.preventDefault(); generateAudio(); });

 $('#audioCopyBtn').click(function() {
 navigator.clipboard.writeText($('#audioResultContent').text());
 const originalText = $(this).html();
 $(this).html('<i class="bi bi-check2 me-1"></i>Copied!');
 setTimeout(() => { $(this).html(originalText); }, 2000);
 });

 $('#audioDownloadBtn').click(function() {
 const content = $('#audioResultContent').text();
 const blob = new Blob([content], { type: 'application/json' });
 const url = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = url;
 a.download = 'transcripts.json';
 a.click();
 URL.revokeObjectURL(url);
 });

 function updateAudioCurlCommand() {
 const file = $('#audio_file')[0].files[0];
 let curl = `curl --location '${API_BASE_URL}/generate-audio' \\\n--form 'file=@"${file ? file.name : '/path/to/your/audio.wav'}"'`;

 const fields = ['dataset_name', 'audio_instruction', 'number_of_clips', 'clip_duration', 'select_format', 'audio_type', 'download_type'];
 fields.forEach(id => {
 const value = $(`#${id}`).val();
 if (value) {
 curl += ` \\\n--form '${id.replace('audio_', '')}="${value.replace(/"/g, '\\"')}"'`;
 }
 });
 $('#audioCurlCommand').text(curl);
 }

 function generateAudio() {
 $('#audioSpinner').removeClass('d-none');
 $('#generateAudioText').text('Generating...');
 $('#audioGenerateBtn').prop('disabled', true);
 $('#audioResultContent').text('Processing...');

 const fileInput = $('#audio_file')[0];
 if (!fileInput.files.length) {
 $('#audioResultContent').html('<div class="alert alert-warning">Please select a file.</div>');
 $('#audioSpinner').addClass('d-none');
 $('#generateAudioText').text('Generate Transcript');
 $('#audioGenerateBtn').prop('disabled', false);
 return;
 }

 const formData = new FormData();
 formData.append('file', fileInput.files[0]);

 const fields = ['dataset_name', 'audio_instruction', 'number_of_clips', 'clip_duration', 'select_format', 'audio_type', 'download_type'];
 fields.forEach(id => {
 const value = $(`#${id}`).val();
 if (value) formData.append(id.replace('audio_', ''), value);
 });

 fetch(`${API_BASE_URL}/generate-audio`, {
 method: 'POST',
 body: formData
 })
 .then(response => {
 if (!response.ok) return response.json().then(err => { throw new Error(err.detail || 'API request failed') });
 return response.json();
 })
 .then(data => {
 $('#audioResultContent').text(JSON.stringify(data, null, 2));
 $('#audioCopyBtn, #audioDownloadBtn').prop('disabled', false);
 })
 .catch(error => {
 $('#audioResultContent').html(`<div class="alert alert-danger">${error.message}</div>`);
 })
 .finally(() => {
 $('#audioSpinner').addClass('d-none');
 $('#generateAudioText').text('Generate Transcript');
 $('#audioGenerateBtn').prop('disabled', false);
 });
 }

 // ===== NEW DASHBOARD SCRIPT =====
 function renderRecordCard(record) {
 const isText = record.record_type === 'text';
 const badgeClass = isText ? 'bg-primary' : 'bg-success';
 const iconClass = isText ? 'bi-textarea-t' : 'bi-mic';
 const title = record.dataset_name || 'Untitled';
 const detailsId = `details-${record.request_id}`;
 const createdAt = new Date(record.created_at).toLocaleString();
 let detailsContent = '';

 if (isText) {
 detailsContent = record.generated_output || 'No output.';
 } else {
 try {
 detailsContent = JSON.stringify(record.transcripts || [], null, 2);
 } catch (e) {
 detailsContent = 'Could not parse transcripts.';
 }
 }

 return `
 <div class="card dashboard-card">
 <div class="card-body">
 <div class="d-flex justify-content-between align-items-start">
 <div>
 <h5 class="card-title mb-1">${record.request_id}</h5>
 <h6 class="card-subtitle mb-2 text-muted">${title}</h6>
 </div>
 <span class="badge ${badgeClass}"><i class="bi ${iconClass} me-1"></i> ${record.record_type.toUpperCase()}</span>
 </div>
 <p class="card-text mb-2"><small class="text-muted">Created: ${createdAt}</small></p>
 <a class="btn btn-sm btn-outline-secondary" data-bs-toggle="collapse" href="#${detailsId}" role="button">
 View Details
 </a>
 <div class="collapse mt-3" id="${detailsId}">
 <pre class="details-pre"><code>${$('<textarea />').html(detailsContent).text()}</code></pre>
 </div>
 </div>
 </div>`;
 }

 function loadDashboardData(url) {
 const contentDiv = $('#dashboardContent');
 contentDiv.html('<div class="text-center py-5"><div class="spinner-border text-primary" role="status"></div><p class="mt-2">Loading records...</p></div>');

 fetch(API_BASE_URL + url)
 .then(response => {
 if (response.status === 404) return [];
 if (!response.ok) return response.json().then(err => { throw new Error(err.detail || `API Error: ${response.statusText}`) });
 return response.json();
 })
 .then(data => {
 contentDiv.empty();
 if (data && data.length > 0) {
 data.forEach(record => contentDiv.append(renderRecordCard(record)));
 } else {
 contentDiv.html('<div class="alert alert-info">No records found.</div>');
 }
 })
 .catch(error => {
 contentDiv.html(`<div class="alert alert-danger">${error.message}</div>`);
 });
 }

 $('#dashboard-tab').on('shown.bs.tab', function() { loadDashboardData('/records'); });

 $('#refreshDashboardBtn').click(function() {
 $('#searchForm')[0].reset();
 loadDashboardData('/records');
});

 $('#searchForm').submit(function(e) {
 e.preventDefault();
 const requestId = $('#searchRequestId').val().trim();
 const datasetName = $('#searchDatasetName').val().trim();

 if (!requestId && !datasetName) {
 loadDashboardData('/records');
 return;
 }

 const params = new URLSearchParams();
 if (requestId) params.append('request_id', requestId);
 if (datasetName) params.append('dataset_name', datasetName);

 // This is the line to change
 loadDashboardData(`/records?${params.toString()}`); // Changed from /search
 });

 // Initial call to set CURL commands
 updateCurlCommand();
 updateAudioCurlCommand();
 });
 </script>
</body>
</html>

