Of course. Here are the two HTML files for testing your API locally. 

 records.html : A new, simple page to test the /records endpoint. 

 index.html : Your existing file, updated with the new "LOS Modality" tab for submitting generation requests. 

 1. records.html 

 This is a standalone file. Save it as records.html and open it in your browser. It fetches and displays all record types from your local database. 

 Note : This page assumes you have disabled authentication on the /records endpoint for local testing, or you will need to add a valid Authorization header in the fetch request inside the script. 

 <!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>Generation Records</title>
 <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
 <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.0/font/bootstrap-icons.css">
 <style>
 body { background-color: #f5f7fb; }
 .header { background: linear-gradient(135deg, #0d6efd, #6f42c1); color: white; padding: 2rem 0; margin-bottom: 2rem; }
 .card { border-radius: 12px; box-shadow: 0 6px 15px rgba(0,0,0,0.08); border: none; margin-bottom: 1.5rem; }
 .card-body { padding: 1.25rem 1.5rem; }
 .card-title { font-family: monospace; word-break: break-all; font-size: 1rem; }
 pre { background-color: #e9ecef; padding: 1rem; border-radius: 8px; max-height: 250px; overflow: auto; white-space: pre-wrap; word-break: break-all; }
 .status-badge { font-size: 0.8em; vertical-align: middle; }
 </style>
</head>
<body>
 <div class="header">
 <div class="container">
 <h1><i class="bi bi-archive-fill"></i> Generation Records</h1>
 <p>A simple dashboard to view all records from the local database.</p>
 </div>
 </div>

 <div class="container">
 <div class="card mb-4">
 <div class="card-body">
 <form id="searchForm" class="row g-2 align-items-center">
 <div class="col-md-5">
 <input type="text" class="form-control" id="searchRequestId" placeholder="Filter by Request ID...">
 </div>
 <div class="col-md-5">
 <input type="text" class="form-control" id="searchDatasetName" placeholder="Filter by Dataset/Record Name...">
 </div>
 <div class="col-md-2 d-grid">
 <button type="submit" class="btn btn-primary"><i class="bi bi-search me-1"></i> Filter</button>
 </div>
 </form>
 </div>
 </div>

 <div id="recordsContent">
 </div>
 </div>

 <script>
 document.addEventListener('DOMContentLoaded', function() {
 const API_BASE_URL = 'http://127.0.0.1:8000';
 const recordsContent = document.getElementById('recordsContent');
 const searchForm = document.getElementById('searchForm');
 // NOTE: For your actual setup, you'll need a valid token.
 // For local testing with auth disabled, this can be any string.
 const AUTH_TOKEN = 'DUMMY_TOKEN'; 

 function getStatusBadge(status) {
 switch (status) {
 case 'SUCCESS': return '<span class="badge bg-success status-badge">SUCCESS</span>';
 case 'FAILED': return '<span class="badge bg-danger status-badge">FAILED</span>';
 case 'GENERATING': return '<span class="badge bg-primary status-badge">GENERATING</span>';
 case 'QUEUED': return '<span class="badge bg-secondary status-badge">QUEUED</span>';
 default: return `<span class="badge bg-light text-dark status-badge">${status}</span>`;
 }
 }

 function renderRecord(record) {
 const createdAt = new Date(record.created_at).toLocaleString();
 let detailsHtml = '';
 let title = record.dataset_name || record.record_name || 'Untitled';
 let badgeClass, iconClass;

 switch(record.record_type) {
 case 'text':
 badgeClass = 'bg-primary';
 iconClass = 'bi-textarea-t';
 detailsHtml = `<pre><code>${escapeHtml(record.generated_output)}</code></pre>`;
 break;
 case 'audio':
 badgeClass = 'bg-info';
 iconClass = 'bi-mic';
 detailsHtml = `<pre><code>${escapeHtml(JSON.stringify(record.transcripts, null, 2))}</code></pre>`;
 break;
 case 'los':
 badgeClass = 'bg-success';
 iconClass = 'bi-file-earmark-ruled';
 detailsHtml = `
 <ul class="list-group list-group-flush">
 <li class="list-group-item d-flex justify-content-between"><strong>Status:</strong> ${getStatusBadge(record.task_status)}</li>
 <li class="list-group-item d-flex justify-content-between"><strong>Output Path:</strong> <code>${record.storage_path || 'N/A'}</code></li>
 <li class="list-group-item d-flex justify-content-between"><strong>Error:</strong> <span class="text-danger">${record.error_message || 'None'}</span></li>
 </ul>`;
 break;
 }

 return `
 <div class="card">
 <div class="card-body">
 <div class="d-flex justify-content-between align-items-start">
 <div>
 <h5 class="card-title mb-1">${record.request_id}</h5>
 <h6 class="card-subtitle mb-2 text-muted">${title}</h6>
 </div>
 <span class="badge ${badgeClass}"><i class="bi ${iconClass} me-1"></i> ${record.record_type.toUpperCase()}</span>
 </div>
 <p class="card-text mb-2"><small class="text-muted">Created: ${createdAt}</small></p>
 ${detailsHtml}
 </div>
 </div>`;
 }

 async function fetchRecords(url) {
 recordsContent.innerHTML = '<div class="text-center py-5"><div class="spinner-border text-primary"></div><p class="mt-2">Loading...</p></div>';
 try {
 const response = await fetch(API_BASE_URL + url, {
 headers: {
 'Authorization': `Bearer ${AUTH_TOKEN}`
 }
 });
 if (response.status === 404) {
 recordsContent.innerHTML = '<div class="alert alert-info">No records found.</div>';
 return;
 }
 if (!response.ok) throw new Error(`API Error: ${response.statusText}`);

 const data = await response.json();
 if (data && data.length > 0) {
 recordsContent.innerHTML = data.map(renderRecord).join('');
 } else {
 recordsContent.innerHTML = '<div class="alert alert-info">No records found.</div>';
 }
 } catch (error) {
 recordsContent.innerHTML = `<div class="alert alert-danger">${error.message}</div>`;
 }
 }

 searchForm.addEventListener('submit', (e) => {
 e.preventDefault();
 const requestId = document.getElementById('searchRequestId').value.trim();
 const datasetName = document.getElementById('searchDatasetName').value.trim();
 const params = new URLSearchParams();
 if (requestId) params.append('request_id', requestId);
 if (datasetName) params.append('dataset_name', datasetName);
 fetchRecords(`/records?${params.toString()}`);
 });

 function escapeHtml(unsafe) {
 if (typeof unsafe !== 'string') return '';
 return unsafe
 .replace(/&/g, "&amp;")
