 <script>
 let sessionId = null;

 // Main graph
 let network = null, nodesDS = null, edgesDS = null;
 // Fullscreen graph
 let networkFull = null, nodesFull = null, edgesFull = null;

 function isMasterAgent(label){
 const s = (label||'').toLowerCase();
 return s.includes('router') || s.includes('manager');
 }

 function buildEntriesFromToggles(){
 const toggles = Array.from(document.querySelectorAll('.agent-toggle:checked'));
 return toggles.map(cb=>{
 const labelEl = document.querySelector('span#name_'+cb.id.replace('agent_','')) || document.querySelector('label[for="'+cb.id+'"]');
 const name = labelEl ? labelEl.textContent.trim() : cb.value;
 let tools = [];
 if (cb.dataset.config) {
 try{
 const cfg = JSON.parse(cb.dataset.config);
 const t = (cfg.mcp && Array.isArray(cfg.mcp.tools)) ? cfg.mcp.tools : [];
 tools = t.filter(Boolean).map(x=>x.name).filter(Boolean);
 }catch(e){ console.warn('Bad config JSON', e); }
 }
 return { id: cb.id, value: cb.value, name, isMaster: isMasterAgent(name), tools, desc: cb.dataset.description || '' , llm: cb.dataset.llm || ''};
 });
 }

 function renderWireflowInto(dsNodes, dsEdges, visNet){
 const entries = buildEntriesFromToggles();
 const masters = entries.filter(e=>e.isMaster);
 const agents = entries.filter(e=>!e.isMaster);

 dsNodes.clear(); dsEdges.clear();

 // Masters
 masters.forEach((m, idx)=>{
 dsNodes.add({ id:'m_'+idx, label:m.name, level:0, shape:'box',
 color:{ background:'#6c4df6', border:'#4a32e3' }, font:{ color:'#fff', size:14 }});
 });
 if(masters.length===0 && agents.length>0){
 dsNodes.add({ id:'m_auto', label:'Master (Auto)', level:0, shape:'box',
 color:{ background:'#6c4df6', border:'#4a32e3' }, font:{ color:'#fff', size:14 }});
 masters.push({ synthetic:true, name:'Master (Auto)' });
 }

 // Agents and Tools
 agents.forEach((a, aidx)=>{
 const aId = 'a_'+aidx;
 dsNodes.add({ id:aId, label:a.name, level:1, shape:'box',
 color:{ background:'#22c55e', border:'#16a34a' }, font:{ color:'#fff', size:13 }});
 masters.forEach((m, midx)=>{
 const mId = m.synthetic ? 'm_auto' : 'm_'+midx;
 dsEdges.add({ from:mId, to:aId, color:{ color:'#9aa2ff' } });
 });
 a.tools.forEach((tool, tidx)=>{
 const tId = 't_'+aidx+'_'+tidx;
 dsNodes.add({ id:tId, label:tool, level:2, shape:'box',
 color:{ background:'#e2e8f0', border:'#cbd5e1' }, font:{ color:'#111827', size:12 }});
 dsEdges.add({ from:aId, to:tId, dashes:true, color:{ color:'#b6b9ff' } });
 });
 });

 visNet.fit({ animation: { duration: 300, easing: 'easeInOutQuad' } });
 }

 function renderWireflow(){
 if (network) renderWireflowInto(nodesDS, edgesDS, network);
 if (networkFull) renderWireflowInto(nodesFull, edgesFull, networkFull);
 updateLLMSummary();
 updatePerCardToolLists();
 }

 function updateLLMSummary(){
 const entries = buildEntriesFromToggles();
 const llms = new Set(entries.map(e=>e.llm).filter(Boolean));
 const llmInfo = document.getElementById('llmInfo');
 const llmModel = document.getElementById('llmModel');
 if(llms.size){
 llmModel.textContent = Array.from(llms).join(', ');
 llmInfo.style.display = 'block';
 } else {
 llmInfo.style.display = 'none';
 }
 }

 function updatePerCardToolLists(){
 const toggles = Array.from(document.querySelectorAll('.agent-toggle'));
 toggles.forEach(cb=>{
 const cardTools = document.getElementById('toolsInCard_'+cb.value);
 if(!cardTools) return;
 cardTools.innerHTML = '';
 if(!cb.checked) return;

 let tools = [];
 if (cb.dataset.config) {
 try{
 const cfg = JSON.parse(cb.dataset.config);
 const t = (cfg.mcp && Array.isArray(cfg.mcp.tools)) ? cfg.mcp.tools : [];
 tools = t.filter(Boolean).map(x=>x.name).filter(Boolean);
 }catch(e){}
 }
 tools.forEach(name=>{
 const item = document.createElement('div');
 item.className = 'list-group-item py-1 px-2 my-1';
 item.textContent = name;
 cardTools.appendChild(item);
 });
 });
 }

 function initNetwork(container, autorefresh=true){
 const dsN = new vis.DataSet([]);
 const dsE = new vis.DataSet([]);
 const data = { nodes: dsN, edges: dsE };
 const options = {
 autoResize: true,
 nodes:{ shape:'box', margin:8, font:{ size:12 } },
 edges:{ arrows:{ to:{ enabled:true } }, smooth:{ type:'cubicBezier' } },
 layout:{ hierarchical:{ enabled:true, direction:'UD', sortMethod:'directed', nodeSpacing:110, levelSeparation:130 } },
 physics:false,
 interaction:{ dragNodes:true, hover:true }
 };
 const net = new vis.Network(container, data, options);
 if(autorefresh){
 const ro = new ResizeObserver(()=> net.fit({ animation:false }));
 ro.observe(container);
 }
 return { dsN, dsE, net };
 }

 // Send message
 let sending = false;
 async function sendMessage(){
 if (sending) return;
 const input = document.getElementById('userInput');
 const message = input.value.trim();
 const selected = Array.from(document.querySelectorAll('.agent-toggle:checked'));
 const frameworkSelect = document.getElementById('frameworkSelect');
 const frameworkType = frameworkSelect ? frameworkSelect.value : 'langgraph';

 if(!message) return;
 if(selected.length === 0){ alert('Please toggle ON at least one agent'); return; }

 const agentIds = selected.map(cb => cb.value).join(',');
 sending = true;

 input.disabled = true; 
 document.getElementById('sendButton').disabled = true;
 document.querySelectorAll('.agent-toggle').forEach(cb => cb.disabled = true);

 try{
 addMessage(message, true);
 input.value = ''; autoResizeTextarea(input);

 const resp = await fetch('/ask', {
 method: 'POST',
 headers: { 'Content-Type':'application/json' },
 body: JSON.stringify({ query: message, agent: agentIds, session_id: sessionId || null, framework_type: frameworkType })
 });

 if(!resp.ok){
 let err = 'Failed to get response from agent';
 try{ const j = await resp.json(); err = j.detail || err; }catch{}
 throw new Error(err);
 }

 const data = await resp.json();
 if(!sessionId) sessionId = data.session_id;

 let responseText = data.result;
 if(typeof responseText === 'object'){
 responseText = responseText.result || JSON.stringify(responseText, null, 2);
 }
 addMessage(responseText);
 }catch(e){
 addMessage('Error: ' + e.message);
 }finally{
 sending = false;
 input.disabled = false;
 document.getElementById('sendButton').disabled = false;
 document.querySelectorAll('.agent-toggle').forEach(cb => cb.disabled = false);
 input.focus();
 }
 }

 function addMessage(content, isUser=false){
 const chat = document.getElementById('chatContainer');
 const el = document.createElement('div');
 el.className = `message ${isUser ? 'user-message' : 'agent-message'}`;
 const time = document.createElement('span'); time.className = 'message-time'; time.textContent = new Date().toLocaleTimeString();
 const body = document.createElement('div'); body.textContent = content;
 el.appendChild(time); el.appendChild(body);
 chat.appendChild(el); chat.scrollTop = chat.scrollHeight;
 }

 function autoResizeTextarea(el){ el.style.height='auto'; el.style.height = Math.min(el.scrollHeight, 220)+'px'; }

 document.addEventListener('DOMContentLoaded', () => {
 // Enable tooltips
 const tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
 tooltipTriggerList.map(el => new bootstrap.Tooltip(el, { boundary: document.body })); /* [Tooltips need init] [web:49][web:50] */

 // Always bind chat first so errors later don't block it
 document.getElementById('sendButton').addEventListener('click', sendMessage);
 const userInput = document.getElementById('userInput');
 userInput.addEventListener('input', function(){ autoResizeTextarea(this); });
 userInput.addEventListener('keydown', function(e){ if(e.key==='Enter' && !e.shiftKey){ e.preventDefault(); sendMessage(); } });

 // Init main network safely
 try {
 const main = initNetwork(document.getElementById('agentNetwork')); nodesDS = main.dsN; edgesDS = main.dsE; network = main.net;
 } catch (e) { console.error('Wireflow init error:', e); }

 // Fullscreen modal network
 const modalEl = document.getElementById('wireflowModal');
 if (modalEl) {
 modalEl.addEventListener('shown.bs.modal', () => {
 if(!networkFull){
 const full = initNetwork(document.getElementById('agentNetworkFull')); nodesFull = full.dsN; edgesFull = full.dsE; networkFull = full.net;
 }
 renderWireflow();
 networkFull.fit({ animation: { duration: 200 } });
 });
 modalEl.addEventListener('hidden.bs.modal', () => { renderWireflow(); });
 }

 // Toggle agents: show/hide details and re-render graph
 document.querySelectorAll('.agent-toggle').forEach(cb=>{
 cb.addEventListener('change', () => {
 const details = document.getElementById('details_'+cb.value);
 if(details){ new bootstrap.Collapse(details, { toggle: cb.checked }); }
 renderWireflow();
 });
 });

 // Optional toolbar (guarded: may be commented out)
 const fitBtn = document.getElementById('wfFitBtn');
 const minBtn = document.getElementById('wfMinBtn');
 if (fitBtn) fitBtn.addEventListener('click', () => network && network.fit({ animation:{ duration:250 }}));
 if (minBtn) minBtn.addEventListener('click', () => {
 const canvas = document.getElementById('agentNetwork');
 const minimized = canvas.style.height === '160px';
 canvas.style.height = minimized ? '300px' : '160px';
 if (network) { network.redraw(); network.fit({ animation:false }); }
 });

 // Initial
 autoResizeTextarea(userInput);
 renderWireflow();
 });
