You are absolutely right! That is some excellent debugging. 

 Your analysis is spot on. The search function was looking for the keyword anywhere within the entire gen_ai.prompt field, which, as you correctly pointed out, includes the conversation history sent to the agent. However, the summary displayed on the dashboard was only extracting the text from the Current Task: . 

 This created the exact discrepancy you found: a trace would appear in the search results if "pinterest" was in its conversation history, even if it wasn't in the current task you were seeing in the summary. 

 The Solution: Two-Step Filtering 

 To fix this, I've implemented a more precise two-step filtering process directly within the search_traces_by_text function: 

 Broad Database Search: The code first performs a broad search in ClickHouse to fetch all traces where the keyword might exist somewhere in the prompt. This gives us a list of "candidate" traces. 

 Precise Python Filter: It then immediately processes these candidates in Python. For each trace, it extracts only the Current Task: text (using the same logic as the summary display) and checks if your search term is present in that specific part. 

 Only the traces that pass this second, more precise check are returned and displayed. This ensures that the search results perfectly match the summaries you see. 

 Fully Updated and Corrected Code 

 Here is the complete code with the improved search logic. The only function that has changed is search_traces_by_text . 

 import streamlit as st
import clickhouse_connect
import pandas as pd
import json
import re
from datetime import datetime, timedelta, timezone, time

HOST = '127.0.0.1'
PORT = 8123
DATABASE = 'openlit'
USERNAME = 'default'
PASSWORD = 'OPENLIT'

DASHBOARD_NAME = "SpanScan"
DASHBOARD_TAGLINE = "Unraveling the Threads of Your Distributed Applications"

@st.cache_resource
def get_clickhouse_client():
 try:
 client = clickhouse_connect.get_client(
 host=HOST,
 port=PORT,
 database=DATABASE,
 username=USERNAME,
 password=PASSWORD
 )
 return client
 except Exception as e:
 st.error(f"Error connecting to ClickHouse: {e}")
 st.info("Please ensure your ClickHouse instance is running.")
 return None

def get_distinct_trace_ids(_client, start_time=None, end_time=None):
 try:
 base_query = "SELECT TraceId FROM otel_traces"

 where_clauses = []
 if start_time:
 where_clauses.append(f"Timestamp >= '{start_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if end_time:
 where_clauses.append(f"Timestamp <= '{end_time.strftime('%Y-%m-%d %H:%M:%S')}'")

 if where_clauses:
 base_query += " WHERE " + " AND ".join(where_clauses)

 query = base_query + " GROUP BY TraceId ORDER BY max(Timestamp) DESC"

 result = _client.query(query)
 return [row[0] for row in result.result_rows]
 except Exception as e:
 st.error(f"Error fetching Trace IDs: {e}")
 return []

def search_traces_by_text(_client, search_term, start_time=None, end_time=None):
 if not search_term:
 return []
 try:
 # Step 1: Broad search in ClickHouse to get candidate traces
 search_clause = f"""
 (
 (mapContains(SpanAttributes, 'gen_ai.prompt') AND SpanAttributes['gen_ai.prompt'] LIKE '%{search_term}%') OR
 (mapContains(SpanAttributes, 'gen_ai.completion') AND SpanAttributes['gen_ai.completion'] LIKE '%{search_term}%')
 )
 """
 where_clauses = [search_clause]
 if start_time:
 where_clauses.append(f"Timestamp >= '{start_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if end_time:
 where_clauses.append(f"Timestamp <= '{end_time.strftime('%Y-%m-%d %H:%M:%S')}'")

 query = "SELECT TraceId, SpanAttributes['gen_ai.prompt'] as prompt FROM otel_traces WHERE "
 query += " AND ".join(where_clauses)
 query += " GROUP BY TraceId, prompt ORDER BY max(Timestamp) DESC"

 candidate_traces = _client.query_df(query)

 # Step 2: Precise filter in Python to match summary logic
 final_trace_ids = []
 for _, row in candidate_traces.iterrows():
 trace_id = row['TraceId']
 prompt = row['prompt']

 if prompt and isinstance(prompt, str):
 # Use the same regex as the summary function to get the "Current Task"
 match = re.search(r"Current Task:\s*(.*?)(?:\n\nThis is the expected criteria|Final Answer:|$)", prompt, re.DOTALL)
 if not match:
 match = re.search(r"Current Task:\s*(.*)", prompt, re.DOTALL)

 if match:
 current_task_text = match.group(1)
 # Check if search term is in the extracted task text
 if search_term.lower() in current_task_text.lower():
 if trace_id not in final_trace_ids:
 final_trace_ids.append(trace_id)

 return final_trace_ids
 except Exception as e:
 st.error(f"Error during text search: {e}")
 return []

@st.cache_data(ttl=600)
def get_trace_summaries(_client, trace_ids):
 if not trace_ids:
 return {}

 summaries = {trace_id: "No summary available" for trace_id in trace_ids}
 try:
 trace_ids_str = ", ".join([f"'{tid}'" for tid in trace_ids])
 query = f"""
 SELECT
 TraceId,
 SpanAttributes['gen_ai.prompt'] as prompt,
 SpanAttributes['gen_ai.completion'] as completion
 FROM otel_traces
 WHERE TraceId IN ({trace_ids_str})
 AND (mapContains(SpanAttributes, 'gen_ai.prompt') OR mapContains(SpanAttributes, 'gen_ai.completion'))
 ORDER BY Timestamp ASC
 """
 result = _client.query_df(query)

 if result.empty:
 return summaries

 trace_data = {}
 for _, row in result.iterrows():
 tid = row['TraceId']
 if tid not in trace_data:
 trace_data[tid] = {'input': None, 'output': None}

 if row['prompt'] and not trace_data[tid]['input']:
 match = re.search(r"Current Task:\s*(.*?)(?:\n\nThis is the expected criteria|Final Answer:)", row['prompt'], re.DOTALL)
 if match:
 trace_data[tid]['input'] = match.group(1).strip()
 else:
 match = re.search(r"Current Task:\s*(.*)", row['prompt'], re.DOTALL)
 if match:
 trace_data[tid]['input'] = match.group(1).strip()

 if row['completion']:
 parsed = parse_llm_completion(row['completion'])
 if parsed.get('final_answer'):
 trace_data[tid]['output'] = parsed.get('final_answer')

 for tid, data in trace_data.items():
 summary_text = ""
 if data['input']:
 summary_text = f"Input: {data['input']}"
 elif data['output']:
 summary_text = f"Output: {data['output'][:70]}..."

 if summary_text:
 summaries[tid] = summary_text.replace("\n", " ")

 return summaries
 except Exception as e:
 st.warning(f"Could not fetch summaries: {e}")
 return summaries

@st.cache_data
def get_table_schema(_client, table_name):
 try:
 query = f"DESCRIBE TABLE {table_name}"
 result = _client.query_df(query)
 return result
 except Exception as e:
 st.error(f"Error describing table {table_name}: {e}")
 return pd.DataFrame()

def get_trace_details(_client, trace_id):
 try:
 trace_query = f"SELECT TraceId, SpanId, ParentSpanId, SpanName, SpanKind, Duration, Timestamp, SpanAttributes FROM otel_traces WHERE TraceId = '{trace_id}' ORDER BY Timestamp ASC"
 trace_result = _client.query(trace_query)
 return trace_result.result_rows
 except Exception as e:
 st.error(f"An error occurred while querying data: {e}")
 return []

def parse_llm_completion(completion_text):
 if not isinstance(completion_text, str):
 return {}
 parsed_data = {}
 thought_match = re.search(r"Thought:(.*?)(?:\nAction:|\nFinal Answer:|$)", completion_text, re.DOTALL)
 if thought_match:
 parsed_data['thought'] = thought_match.group(1).strip()
 action_match = re.search(r"Action:(.*?)(?:\nAction Input:|$)", completion_text, re.DOTALL)
 if action_match:
 parsed_data['action'] = action_match.group(1).strip()
 action_input_match = re.search(r"Action Input:(.*?)(?:\nObservation:|$)", completion_text, re.DOTALL)
 if action_input_match:
 parsed_data['action_input'] = action_input_match.group(1).strip()
 final_answer_match = re.search(r"Final Answer:(.*)", completion_text, re.DOTALL)
 if final_answer_match:
 parsed_data['final_answer'] = final_answer_match.group(1).strip()
 if not parsed_data and completion_text:
 thought_before_final = re.search(r"Thought:(.*?)(\nFinal Answer:)", completion_text, re.DOTALL)
 if thought_before_final:
 parsed_data['thought'] = thought_before_final.group(1).strip()
 elif "Final Answer:" not in completion_text and "Action:" not in completion_text:
 parsed_data['final_answer'] = completion_text.strip()
 return parsed_data

def display_span_recursively(span, span_tree):
 span_name = span['SpanName']
 duration_ms = span['Duration'] / 1_000_000
 attrs = span.get('SpanAttributes', {})
 expander_label = f"{span_name} | ⏱️ {duration_ms:.2f} ms"
 is_expanded = st.session_state.get('expand_all', False)
 with st.expander(expander_label, expanded=is_expanded):
 if span_name == "invoke_agent crew":
 st.markdown("##### 🚀 Transaction Start")
 st.write(f"**Total Duration:** {duration_ms:.2f} ms")
 st.write(f"**Timestamp:** {span['Timestamp']}")
 elif span_name == "Crew Created":
 st.markdown("##### 👥 Crew Assembly")
 st.write(f"**Crew ID:** `{attrs.get('crew_id', 'N/A')}`")
 c1, c2 = st.columns(2)
 c1.metric("Agents Configured", attrs.get('crew_number_of_agents', 'N/A'))
 c2.metric("Tasks Assigned", attrs.get('crew_number_of_tasks', 'N/A'))
 if 'crew_agents' in attrs:
 with st.expander("View Agent Details"):
 st.json(attrs['crew_agents'])
 if 'crew_tasks' in attrs:
 with st.expander("View Task Details"):
 st.json(attrs['crew_tasks'])
 elif span_name == "Task Created":
 st.markdown("##### ✅ Task Initialized")
 st.write(f"**Crew ID:** `{attrs.get('crew_id', 'N/A')}`")
 st.write(f"**Task ID:** `{attrs.get('task_id', 'N/A')}`")
 elif span_name.startswith("invoke_agent"):
 agent_name = attrs.get('gen_ai.agent.name', 'Unknown Agent')
 st.markdown(f"##### 🤖 Agent Running: `{agent_name}`")
 if 'gen_ai.agent.tools' in attrs:
 st.write("**Available Tools:**")
