import os
import re
import json
from dotenv import load_dotenv
from fastapi import FastAPI, Form, Request
from fastapi.staticfiles import StaticFiles
from fastapi.responses import JSONResponse
from google import genai

load_dotenv()
GEMINI_API_KEY = os.getenv("GEMINI_API_KEY")
if not GEMINI_API_KEY:
 raise RuntimeError("GEMINI_API_KEY not set in .env")

app = FastAPI()
app.mount("/", StaticFiles(directory="static", html=True), name="static")

def strip_code_fences(text: str) -> str:
 pattern = r"^\s*```(?:json)?\s*\n?|\n?\s*```$"
 return re.sub(pattern, "", text, flags=re.MULTILINE)

@app.post("/api/palettes", response_class=JSONResponse)
async def generate_palettes(user_prompt: str = Form(...), tags: str = Form("")):
 client = genai.Client(api_key=GEMINI_API_KEY)
 chat = client.chats.create(model="gemini-2.0-flash")
 prompt_text = (
 f"Generate 5 distinct color palettes. Each palette should be a list of 3–6 hex colors.\n"
 f"Mood/Theme: {user_prompt}.\n"
 f"Tag: {tags if tags else 'none'}.\n"
 "Respond in JSON format with a single key \"palettes\", whose value is an array of palettes. "
 "Example:\n"
 "{\n"
 ' "palettes": [ ["#FF5733","#C70039","#900C3F"], ["#123456","#654321","#ABCDEF"], ... ]\n'
 "}\n\n"
 "Only output valid JSON—no extra text."
 )
 try:
 response = chat.send_message(prompt_text)
 raw_text = response.text
 except Exception as e:
 return JSONResponse(status_code=500, content={"error": f"Gemini API error: {e}"})
