from langchain_core.messages import SystemMessagefrom langgraph.graph import StateGraph, START, END, MessagesStatefrom langgraph.prebuilt import ToolNode

DANGEROUS_TOOLS = ["build_custom_tool", "test_tool_sandbox", "promote_tool"]def build_agent(llm, tools, memory):
 llm_with_tools = llm.bind_tools(tools)

 async def call_model(state: MessagesState):
 sys_prompt = SystemMessage(content="""You are an elite AI Tool Engineer.
 CRITICAL LOGIC RULES:
 1. HOT-RELOADING: When you use `promote_tool`, the tool is INSTANTLY LIVE. You can immediately use it.
 2. BUILD COMMAND RULE: You MUST provide the `parameters` dictionary in `build_custom_tool`. The `python_code` MUST end with a `return` statement returning a JSON-serializable dict.
 3. SANDBOX TESTING RULE: When calling `test_tool_sandbox`, you MUST pass inputs nested inside the `test_payload` dictionary (e.g. {"name": "my_tool", "test_payload": {"input_string": "hello"}}).
 4. STOP ON FAILURE: If a test returns an error, DO NOT silently rebuild the tool. STOP, explain the error, and ask the user if they want you to rewrite it.
 """)
 response = await llm_with_tools.ainvoke([sys_prompt] + state['messages'])
 return {"messages": [response]}

 def should_continue(state: MessagesState):
 last_msg = state['messages'][-1]
 if not hasattr(last_msg, 'tool_calls') or not last_msg.tool_calls: return END
 for tc in last_msg.tool_calls:
 if tc['name'] in DANGEROUS_TOOLS: return "dangerous_tools"
 return "safe_tools"

 workflow = StateGraph(MessagesState)
 workflow.add_node("agent", call_model)
 workflow.add_node("safe_tools", ToolNode(tools)) 
 workflow.add_node("dangerous_tools", ToolNode(tools)) 

 workflow.add_edge(START, "agent")
 workflow.add_conditional_edges("agent", should_continue, ["safe_tools", "dangerous_tools", END])
 workflow.add_edge("safe_tools", "agent") 
 workflow.add_edge("dangerous_tools", "agent") 

 return workflow.compile(checkpointer=memory, interrupt_before=["dangerous_tools"])
