import os, jsonfrom fastapi import FastAPI, WebSocket, WebSocketDisconnectfrom fastapi.responses import HTMLResponsefrom dotenv import load_dotenvfrom langchain_openai import ChatOpenAIfrom langchain_core.messages import ToolMessagefrom langgraph.checkpoint.memory import MemorySaverfrom mcp import ClientSessionfrom mcp.client.sse import sse_clientfrom langchain_mcp_adapters.tools import load_mcp_toolsfrom main import build_agent, DANGEROUS_TOOLS

load_dotenv()
app = FastAPI()
memory = MemorySaver()@app.get("/")async def get_ui():
 with open("index.html", "r") as f: return HTMLResponse(f.read())@app.websocket("/ws/chat")async def websocket_endpoint(websocket: WebSocket):
 await websocket.accept()
 llm = ChatOpenAI(model="gpt-4o", temperature=0)
 mcp_url = "http://localhost:8000/sse"
 try:
 async with sse_client(url=mcp_url) as (read, write):
 async with ClientSession(read, write) as session:
 await session.initialize()
 config = {"configurable": {"thread_id": "dynamo_web_final"}}
 await websocket.send_text(json.dumps({"type": "system", "content": "✅ Connected to DynamoMCP."}))
 processed_ids = set()

 while True:
 data = await websocket.receive_text()
 payload = json.loads(data)
 action = payload.get("action")

 try:
 if action == "chat":
 user_msg = payload.get("message")
 tools = await load_mcp_tools(session)
 agent = build_agent(llm, tools, memory)
 stream = agent.astream({"messages": [("user", user_msg)]}, config, stream_mode="values")
 elif action == "approve":
 stream = agent.astream(None, config, stream_mode="values")
 elif action == "reject":
 state = agent.get_state(config)
 last_msg = state.values["messages"][-1]
 tool_msgs = [ToolMessage(tool_call_id=tc['id'], name=tc['name'], content="USER REJECTED.") for tc in last_msg.tool_calls]
 agent.update_state(config, {"messages": tool_msgs})
 await websocket.send_text(json.dumps({"type": "system", "content": "❌ Cancelled."}))
 stream = agent.astream(None, config, stream_mode="values")

 async for event in stream:
 latest_msg = event["messages"][-1]
 if latest_msg.id in processed_ids: continue
 processed_ids.add(latest_msg.id)

 if latest_msg.type == "ai":
 if hasattr(latest_msg, 'tool_calls') and latest_msg.tool_calls:
 for tc in latest_msg.tool_calls:
 icon = "⚠️" if tc['name'] in DANGEROUS_TOOLS else "⚡"
 msg = f"<b>{icon} Tool Call:</b> <code>{tc['name']}</code><br><b>Args:</b> <pre>{json.dumps(tc['args'], indent=2)}</pre>"
 await websocket.send_text(json.dumps({"type": "tool_call", "content": msg}))
 elif latest_msg.content:
 await websocket.send_text(json.dumps({"type": "ai_message", "content": latest_msg.content}))
 elif latest_msg.type == "tool":
 await websocket.send_text(json.dumps({"type": "tool_result", "name": latest_msg.name, "content": str(latest_msg.content)}))

 state = agent.get_state(config)
 if state.next and state.next[0] == "dangerous_tools":
 last_msg = state.values["messages"][-1]
 pending_tools = [tc['name'] for tc in last_msg.tool_calls] if hasattr(last_msg, 'tool_calls') else []
 await websocket.send_text(json.dumps({"type": "pause", "tools": pending_tools}))
 except Exception as e: await websocket.send_text(json.dumps({"type": "system", "content": f"❌ Error: {str(e)}"}))
 except WebSocketDisconnect: pass
