 <link href="https://cdn.jsdelivr.net/npm/vis-network@9.1.2/dist/vis-network.min.css" rel="stylesheet"/>
 <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css">
 <style>
 @import url('https://fonts.googleapis.com/css2?family=Tourney:ital,wght@0,100..900;1,100..900&display=swap');
 </style>
 <style>
 :root{
 --brand-primary:#6c4df6; --brand-primary-600:#5a3ef0; --brand-primary-700:#4a32e3;
 --brand-accent:#22c55e; --brand-accent-600:#16a34a;
 --ink-900:#0f172a; --ink-700:#334155; --ink-500:#64748b;
 --surface:#ffffff; --border:#e5e7eb;
 }
 html, body {
 height: 100vh;
 overflow: hidden;
 }
 body{ background:linear-gradient(180deg,#f3f5ff 0%, #f9fafb 30%, #f7f8ff 100%); color:var(--ink-900); }
 .page-wrapper {
 height: 100%;
 display: flex;
 flex-direction: column;
 }
 .main-content-row {
 flex-grow: 1;
 min-height: 0;
 }
 .sidebar-column {
 height: 100%;
 overflow-y: auto;
 padding-bottom: 1rem;
 }
 .page-header{ background:linear-gradient(90deg, var(--brand-primary) 0%, #8b5cf6 100%); border-radius:16px; padding:1px 16px; color:#fff;
 display:flex; align-items:center; justify-content:space-between; box-shadow:0 8px 24px rgba(108,77,246,.25); }
 .page-header h1{ font-size:2.5rem; margin:0; letter-spacing:.3px; font-family: "Tourney", sans-serif; color:#F5F5DC; font-weight:600;}
 .page-header h1{ transition: transform .25s ease, text-shadow .25s ease, letter-spacing .25s ease, filter .25s ease; will-change: transform, text-shadow, letter-spacing; }
 .page-header h1:hover{ transform: translateY(-1px) scale(1.04); letter-spacing:.6px; text-shadow: 0 6px 22px rgba(108,77,246,.45), 0 2px 8px rgba(0,0,0,.15); filter: drop-shadow(0 4px 10px rgba(108,77,246,.3)); }
 .page-header .btn{ background:#fff; color:var(--brand-primary-700); border:0; font-weight:600; box-shadow:0 2px 10px rgba(0,0,0,.06); }
 .page-header .btn:hover{ color:#fff; background:rgba(255,255,255,.15); border:1px solid rgba(255,255,255,.35); }

 .card{ border:1px solid var(--border); border-radius:14px; background:var(--surface); box-shadow:0 10px 24px rgba(17,24,39,.06); transition: transform .18s ease, box-shadow .18s ease; }
 .card:hover{ transform: translateY(-2px); box-shadow:0 14px 28px rgba(17,24,39,.08); }
 .card-title{ font-size:.95rem; color:var(--ink-700); margin-bottom:.75rem; font-weight:700; letter-spacing:.2px; }

 .agent-list .list-group{ border:0; gap:10px; }
 .agent-item{ border:1px solid var(--border); border-radius:12px; padding:.6rem .75rem; transition: background-color .2s ease; }
 .agent-item.is-master { background-color: #f3f0ff; border-color: #ddd6fe; }
 .agent-item.is-worker { background-color: #f0fdf4; border-color: #dcfce7; }

 .agent-head{ display:flex; align-items:center; justify-content:space-between; gap:.6rem; }
 .agent-name{ font-weight:700; color:#111827; }
 .agent-tags{ display:flex; align-items:center; gap:.5rem; }
 .agent-chip{ font-size:.72rem; background:#eef2ff; color:#4338ca; padding:.15rem .5rem; border-radius:999px; font-weight:700; }
 .agent-chip.master{ background:#ecfdf5; color:#047857; }

 .form-check.form-switch .form-check-input{ width:2.6rem; height:1.4rem; cursor:pointer; box-shadow:inset 0 0 0 1px #d1d5db; }
 .form-check.form-switch .form-check-input:checked{ background-color:#6c4df6; box-shadow:inset 0 0 0 1px #5b46e8; }

 .agent-collapse-toggle {
 display: none;
 width: 26px; height: 26px;
 line-height: 1;
 border-radius: 8px;
 transition: background-color .2s ease;
 }
 .agent-item.is-selected .agent-collapse-toggle {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 }
 .agent-collapse-toggle .bi {
 transition: transform 0.25s ease-in-out;
 }
 .agent-collapse-toggle[aria-expanded="false"] .bi {
 transform: rotate(-180deg);
 }

 .agent-details{ border-top:1px dashed #e5e7eb; margin-top:.5rem; padding-top:.6rem; }
 .agent-desc{ font-size:.82rem; color:#444; line-height:1.35; }
 .agent-tools .list-group-item{ border-radius:10px; border:1px dashed #dbeafe; background:#f8fafc; font-family:ui-monospace,Menlo,Consolas,monospace; font-size:.8rem; }

 .chat-container{ overflow-y:auto; border:1px solid var(--border); background:#fff; border-radius:16px; padding:18px; }
 .message{ margin-bottom:14px; padding:12px 14px; border-radius:12px; max-width:80%; word-break:break-word; white-space:pre-wrap; box-shadow:0 2px 8px rgba(2,6,23,.06); }
 .user-message{ margin-left:auto; background:linear-gradient(135deg, var(--brand-primary) 0%, #8b5cf6 100%); color:#fff; }
 .agent-message{ background:linear-gradient(135deg, #212d38 0%, #1b2936 100%); color:#fff; }
 .message-time{ font-size:.75rem; opacity:.85; display:block; margin-bottom:4px; }

 .input-area{ margin-top:12px; background:linear-gradient(90deg, #373049 0%, #261f36 100%); border:1px solid var(--border); border-radius:14px; display:flex; gap:8px; padding:6px; align-items:flex-end; box-shadow:0 6px 18px rgba(17,24,39,.06); }
 #userInput.form-control{ border-radius:10px; border:1px solid #e5e7eb; min-height:46px; max-height:220px; resize:none; overflow-y:hidden; }
 #sendButton{
 border-radius: 50%;
 background: #6c4df6;
 border: 0;
 width: 46px;
 height: 46px;
 padding: 0;
 font-weight: 700;
 box-shadow: 0 8px 16px rgba(108,77,246,.25);
 flex-shrink: 0;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 }
 #sendButton:hover{ background:#5a3ef0; }
 #sendButton .material-symbols-outlined {
 font-size: 24px;
 color: white;
 }

 .wireflow-toolbar{ display:flex; gap:.5rem; align-items:center; justify-content:flex-end; }
 .wireflow-toolbar .btn{ border-radius:10px; }
 #agentNetwork{ height:300px; border:1px dashed #dbeafe; border-radius:12px; background: radial-gradient(1200px 600px at 0% 0%, #f5f7ff 0%, #ffffff 70%); }
 .wireflow-toolbar .btn[data-bs-toggle="collapse"] .bi {
 transition: transform 0.25s ease-in-out;
 }
 .wireflow-toolbar .btn[data-bs-toggle="collapse"][aria-expanded="false"] .bi {
 transform: rotate(-180deg);
 }

 .modal-fullscreen .modal-body{ padding:0; }
 #agentNetworkFull{ height:85vh; border:0; }

 /* Custom Scrollbar Styles */
 .sidebar-column, .chat-container {
 scrollbar-width: thin;
 scrollbar-color: var(--brand-primary) transparent;
 }
 .sidebar-column::-webkit-scrollbar, .chat-container::-webkit-scrollbar {
 width: 8px;
 }
 .sidebar-column::-webkit-scrollbar-track, .chat-container::-webkit-scrollbar-track {
 background: transparent;
 }
 .sidebar-column::-webkit-scrollbar-thumb, .chat-container::-webkit-scrollbar-thumb {
 background-color: var(--brand-primary-600);
 border-radius: 20px;
 }
 .sidebar-column:hover::-webkit-scrollbar-thumb, .chat-container:hover::-webkit-scrollbar-thumb {
 background-color: var(--brand-primary);
 }
 </style>
</head>
<body>
 <div class="container-fluid py-4 page-wrapper">
 <div class="page-header mb-3">
 <h1 class="mb-0">Agentarium</h1>
 <a href="/agent-management" class="btn btn-sm">Manage Agents</a>
 </div>

 <div class="row g-3 main-content-row">
 <div class="col-lg-3 sidebar-column">
 <div class="card">
 <div class="card-body agent-list">
 <h6 class="text-muted small fw-bold mt-3 mb-2 ps-1">MASTER AGENTS</h6>
 <ul class="list-group mb-3">
 {% for agent_id, agent_info in agents.items() %}
 {% set name = agent_info.name if agent_info.name is defined else agent_id %}
 {% if 'router' in name|lower or 'manager' in name|lower %}
 {% set description = agent_info.description if agent_info.description is defined else agent_info %}
 {% set is_master = true %}
 {% set config = agent_info.config if agent_info.config is defined else none %}
 {% set llm = agent_info.llm_used if agent_info.llm_used is defined else none %}
 <li class="list-group-item agent-item {{ 'is-master' if is_master else 'is-worker' }}" id="card_{{ agent_id }}">
 <div class="agent-head">
 <div class="d-flex align-items-center gap-2">
 <span class="agent-name" id="name_{{ agent_id }}" data-bs-toggle="tooltip" data-bs-placement="top" title="{{ description }}">{{ name }}</span>
 <div class="agent-tags">
 <span class="agent-chip {{ 'master' if is_master else '' }}">{{ 'Master' if is_master else 'Agent' }}</span>
 </div>
 </div>
 <div class="d-flex align-items-center gap-2">
 <button class="btn btn-light btn-sm p-0 agent-collapse-toggle" type="button" data-bs-toggle="collapse" data-bs-target="#details_{{ agent_id }}" aria-expanded="false" aria-controls="details_{{ agent_id }}">
 <i class="bi bi-chevron-up"></i>
 </button>
 <div class="form-check form-switch m-0">
 <input class="form-check-input agent-toggle" type="checkbox" role="switch" value="{{ agent_id }}" id="agent_{{ agent_id }}" data-description="{{ description }}"
 {% if llm %}data-llm="{{ llm }}"{% endif %}
 {% if config %}data-config='{{ config|tojson|safe }}'{% endif %}>
 </div>
 </div>
 </div>
 <div class="agent-details collapse" id="details_{{ agent_id }}">
 <div class="agent-desc mb-2">{{ description }}</div>
 <div class="agent-tools">
 <div class="fw-semibold small text-muted mb-1">Tools</div>
 <div class="list-group list-group-flush" id="toolsInCard_{{ agent_id }}"></div>
 </div>
 </div>
 </li>
 {% endif %}
 {% endfor %}
 </ul>

 <h6 class="text-muted small fw-bold mt-4 mb-2 ps-1">WORKER AGENTS</h6>
 <ul class="list-group">
 {% for agent_id, agent_info in agents.items() %}
 {% set name = agent_info.name if agent_info.name is defined else agent_id %}
 {% if not ('router' in name|lower or 'manager' in name|lower) %}
 {% set description = agent_info.description if agent_info.description is defined else agent_info %}
 {% set is_master = false %}
 {% set config = agent_info.config if agent_info.config is defined else none %}
 {% set llm = agent_info.llm_used if agent_info.llm_used is defined else none %}
 <li class="list-group-item agent-item {{ 'is-master' if is_master else 'is-worker' }}" id="card_{{ agent_id }}">
 <div class="agent-head">
 <div class="d-flex align-items-center gap-2">
 <span class="agent-name" id="name_{{ agent_id }}" data-bs-toggle="tooltip" data-bs-placement="top" title="{{ description }}">{{ name }}</span>
 <div class="agent-tags">
 <span class="agent-chip {{ 'master' if is_master else '' }}">{{ 'Master' if is_master else 'Agent' }}</span>
 </div>
 </div>
 <div class="d-flex align-items-center gap-2">
 <button class="btn btn-light btn-sm p-0 agent-collapse-toggle" type="button" data-bs-toggle="collapse" data-bs-target="#details_{{ agent_id }}" aria-expanded="false" aria-controls="details_{{ agent_id }}">
 <i class="bi bi-chevron-up"></i>
 </button>
 <div class="form-check form-switch m-0">
 <input class="form-check-input agent-toggle" type="checkbox" role="switch" value="{{ agent_id }}" id="agent_{{ agent_id }}" data-description="{{ description }}"
 {% if llm %}data-llm="{{ llm }}"{% endif %}
 {% if config %}data-config='{{ config|tojson|safe }}'{% endif %}>
 </div>
 </div>
 </div>
 <div class="agent-details collapse" id="details_{{ agent_id }}">
 <div class="agent-desc mb-2">{{ description }}</div>
 <div class="agent-tools">
 <div class="fw-semibold small text-muted mb-1">Tools</div>
 <div class="list-group list-group-flush" id="toolsInCard_{{ agent_id }}"></div>
 </div>
 </div>
 </li>
 {% endif %}
 {% endfor %}
 </ul>

 <div id="llmInfo" class="mt-3" style="display:none;">
 <h6 class="card-title">LLM Configuration</h6>
 <div class="alert alert-info py-2 px-3 mb-2">
 <strong>Model:</strong> <span id="llmModel"></span>
 </div>
 </div>
 </div>
 </div>

 <div class="card mt-3">
 <div class="card-body">
 <div class="d-flex align-items-center justify-content-between mb-2">
 <h5 class="card-title mb-0">Agent Wireflow</h5>
 <div class="wireflow-toolbar">
 <button class="btn btn-sm btn-outline-secondary p-0" style="width: 28px; height: 28px;" type="button" data-bs-toggle="collapse" data-bs-target="#wireflowCollapse" aria-expanded="true" title="Toggle View">
 <i class="bi bi-chevron-up"></i>
 </button>
 <button class="btn btn-primary btn-sm" data-bs-toggle="modal" data-bs-target="#wireflowModal" title="Fullscreen">
 <i class="bi bi-arrows-fullscreen"></i>
 </button>
 </div>
 </div>
 <div class="collapse show" id="wireflowCollapse">
 <div id="agentNetwork"></div>
 </div>
 </div>
 </div>
 </div>

 <div class="col-lg-9 d-flex flex-column">
 <div class="card h-100">
 <div class="card-body d-flex flex-column h-100">
 <div class="chat-container flex-grow-1 mb-2" id="chatContainer" aria-live="polite"></div>
 <div class="input-area">
 <textarea id="userInput" class="form-control" rows="1" placeholder="Type a message... (Enter to send, Shift+Enter for newline)" aria-label="Message input"></textarea>

 <select id="frameworkSelect" class="form-select ms-2" style="max-width: 140px; height: 46px;" aria-label="Select framework">
 <option value="langgraph">LangGraph</option>
 <option value="crew" selected>Crew</option>
 </select>

 <button class="btn" id="sendButton" type="button" aria-label="Send message">
 <span class="material-symbols-outlined">send</span>
 </button>
 </div>

 <div class="text-center small text-muted mt-1">Press Enter to send • Press Shift+Enter for a new line</div>
 </div>
 </div>
 </div>
 </div>
 </div>

 <div class="modal fade" id="wireflowModal" tabindex="-1" aria-hidden="true">
 <div class="modal-dialog modal-fullscreen">
 <div class="modal-content">
 <div class="modal-header">
 <h5 class="modal-title">Agent Wireflow</h5>
 <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
 </div>
 <div class="modal-body">
 <div id="agentNetworkFull"></div>
 </div>
 </div>
 </div>
 </div>

 <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
 <script src="https://cdn.jsdelivr.net/npm/vis-network@9.1.2/dist/vis-network.min.js"></script>

 <script>
 let sessionId = null;
 let network = null, nodesDS = null, edgesDS = null;
 let networkFull = null, nodesFull = null, edgesFull = null;

 function isMasterAgent(label){
 const s = (label||'').toLowerCase();
 return s.includes('router') || s.includes('manager');
 }

 function buildEntriesFromToggles(){
 const toggles = Array.from(document.querySelectorAll('.agent-toggle:checked'));
 return toggles.map(cb=>{
 const labelEl = document.querySelector('span#name_'+cb.id.replace('agent_','')) || document.querySelector('label[for="'+cb.id+'"]');
 const name = labelEl ? labelEl.textContent.trim() : cb.value;
 let tools = [];
 if (cb.dataset.config) {
 try{
 const cfg = JSON.parse(cb.dataset.config);
 const t = (cfg.mcp && Array.isArray(cfg.mcp.tools)) ? cfg.mcp.tools : [];
 tools = t.filter(Boolean).map(x=>x.name).filter(Boolean);
 }catch(e){ console.warn('Bad config JSON', e); }
 }
 return { id: cb.id, value: cb.value, name, isMaster: isMasterAgent(name), tools, desc: cb.dataset.description || '' , llm: cb.dataset.llm || ''};
 });
 }

 function renderWireflowInto(dsNodes, dsEdges, visNet){
 const entries = buildEntriesFromToggles();
 const masters = entries.filter(e=>e.isMaster);
 const agents = entries.filter(e=>!e.isMaster);

 dsNodes.clear(); dsEdges.clear();

 masters.forEach((m, idx)=>{
 dsNodes.add({ id:'m_'+idx, label:m.name, level:0, shape:'box',
 color:{ background:'#6c4df6', border:'#4a32e3' }, font:{ color:'#fff', size:14 }});
 });
 if(masters.length===0 && agents.length>0){
 dsNodes.add({ id:'m_auto', label:'Master (Auto)', level:0, shape:'box',
 color:{ background:'#6c4df6', border:'#4a32e3' }, font:{ color:'#fff', size:14 }});
 masters.push({ synthetic:true, name:'Master (Auto)' });
 }

 agents.forEach((a, aidx)=>{
 const aId = 'a_'+aidx;
 dsNodes.add({ id:aId, label:a.name, level:1, shape:'box',
 color:{ background:'#22c55e', border:'#16a34a' }, font:{ color:'#fff', size:13 }});
 masters.forEach((m, midx)=>{
 const mId = m.synthetic ? 'm_auto' : 'm_'+midx;
 dsEdges.add({ from:mId, to:aId, color:{ color:'#9aa2ff' } });
 });
 a.tools.forEach((tool, tidx)=>{
 const tId = 't_'+aidx+'_'+tidx;
 dsNodes.add({ id:tId, label:tool, level:2, shape:'box',
 color:{ background:'#e2e8f0', border:'#cbd5e1' }, font:{ color:'#111827', size:12 }});
 dsEdges.add({ from:aId, to:tId, dashes:true, color:{ color:'#b6b9ff' } });
 });
 });

 visNet.fit({ animation: { duration: 300, easing: 'easeInOutQuad' } });
 }

 function renderWireflow(){
 const entries = buildEntriesFromToggles();
 const wireflowCollapseEl = document.getElementById('wireflowCollapse');

 if (wireflowCollapseEl) {
 const bsCollapse = bootstrap.Collapse.getOrCreateInstance(wireflowCollapseEl);
 if (entries.length > 0) {
 bsCollapse.show();
 } else {
 bsCollapse.hide();
 }
 }

 if (network) renderWireflowInto(nodesDS, edgesDS, network);
 if (networkFull) renderWireflowInto(nodesFull, edgesFull, networkFull);
 updateLLMSummary();
 updatePerCardToolLists();
 }

 function updateLLMSummary(){
 const entries = buildEntriesFromToggles();
 const llms = new Set(entries.map(e=>e.llm).filter(Boolean));
 const llmInfo = document.getElementById('llmInfo');
 const llmModel = document.getElementById('llmModel');
 if(llms.size){
 llmModel.textContent = Array.from(llms).join(', ');
 llmInfo.style.display = 'block';
 } else {
 llmInfo.style.display = 'none';
 }
 }

 function updatePerCardToolLists(){
 const toggles = Array.from(document.querySelectorAll('.agent-toggle'));
 toggles.forEach(cb=>{
 const cardTools = document.getElementById('toolsInCard_'+cb.value);
 if(!cardTools) return;
 cardTools.innerHTML = '';
 if(!cb.checked) return;

 let tools = [];
 if (cb.dataset.config) {
 try{
 const cfg = JSON.parse(cb.dataset.config);
 const t = (cfg.mcp && Array.isArray(cfg.mcp.tools)) ? cfg.mcp.tools : [];
 tools = t.filter(Boolean).map(x=>x.name).filter(Boolean);
 }catch(e){}
 }
 tools.forEach(name=>{
 const item = document.createElement('div');
 item.className = 'list-group-item py-1 px-2 my-1';
 item.textContent = name;
 cardTools.appendChild(item);
 });
 });
 }

 function initNetwork(container, autorefresh=true){
 const dsN = new vis.DataSet([]);
 const dsE = new vis.DataSet([]);
 const data = { nodes: dsN, edges: dsE };
 const options = {
 autoResize: true,
 nodes:{ shape:'box', margin:8, font:{ size:12 } },
 edges:{ arrows:{ to:{ enabled:true } }, smooth:{ type:'cubicBezier' } },
 layout:{ hierarchical:{ enabled:true, direction:'UD', sortMethod:'directed', nodeSpacing:110, levelSeparation:130 } },
 physics:false,
 interaction:{ dragNodes:true, hover:true }
 };
 const net = new vis.Network(container, data, options);
 if(autorefresh){
 const ro = new ResizeObserver(()=> net.fit({ animation:false }));
 ro.observe(container);
 }
 return { dsN, dsE, net };
 }

 let sending = false;
 async function sendMessage(){
 if (sending) return;
 const input = document.getElementById('userInput');
 const message = input.value.trim();
 const selected = Array.from(document.querySelectorAll('.agent-toggle:checked'));
 const frameworkSelect = document.getElementById('frameworkSelect');
 const frameworkType = frameworkSelect ? frameworkSelect.value : 'crew';

 if(!message) return;
 if(selected.length === 0){ alert('Please toggle ON at least one agent'); return; }

 const agentIds = selected.map(cb => cb.value).join(',');
 sending = true;

 input.disabled = true; 
 document.getElementById('sendButton').disabled = true;
 document.querySelectorAll('.agent-toggle').forEach(cb => cb.disabled = true);

 try{
 addMessage(message, true);
 input.value = ''; autoResizeTextarea(input);

 const resp = await fetch('/ask', {
 method: 'POST',
 headers: { 'Content-Type':'application/json' },
 body: JSON.stringify({ query: message, agent: agentIds, session_id: sessionId || null, framework_type: frameworkType })
 });

 if(!resp.ok){
 let err = 'Failed to get response from agent';
 try{ const j = await resp.json(); err = j.detail || err; }catch{}
 throw new Error(err);
 }

 const data = await resp.json();
 if(!sessionId) sessionId = data.session_id;

 let responseText = data.result;
 if(typeof responseText === 'object'){
 responseText = responseText.result || JSON.stringify(responseText, null, 2);
 }
 addMessage(responseText);
 }catch(e){
 addMessage('Error: ' + e.message);
 }finally{
 sending = false;
 input.disabled = false;
 document.getElementById('sendButton').disabled = false;
 document.querySelectorAll('.agent-toggle:not(:checked)').forEach(cb => cb.disabled = false);
 const checkedAndDisabled = document.querySelectorAll('.agent-toggle:checked[disabled]');
 checkedAndDisabled.forEach(cb => {
 const config = JSON.parse(cb.dataset.config || '{}');
 if (!config || !config.crew_members) {
 cb.disabled = false;
 }
 });
 input.focus();
 }
 }

 function addMessage(content, isUser=false){
 const chat = document.getElementById('chatContainer');
 const el = document.createElement('div');
 el.className = `message ${isUser ? 'user-message' : 'agent-message'}`;
 const time = document.createElement('span'); time.className = 'message-time'; time.textContent = new Date().toLocaleTimeString();
 const body = document.createElement('div'); body.textContent = content;
 el.appendChild(time); el.appendChild(body);
 chat.appendChild(el); chat.scrollTop = chat.scrollHeight;
 }

 function autoResizeTextarea(el){ el.style.height='auto'; el.style.height = Math.min(el.scrollHeight, 220)+'px'; }

 document.addEventListener('DOMContentLoaded', () => {
 const tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
 tooltipTriggerList.map(el => new bootstrap.Tooltip(el, { boundary: document.body }));

 document.getElementById('sendButton').addEventListener('click', sendMessage);
 const userInput = document.getElementById('userInput');
 userInput.addEventListener('input', function(){ autoResizeTextarea(this); });
 userInput.addEventListener('keydown', function(e){ if(e.key==='Enter' && !e.shiftKey){ e.preventDefault(); sendMessage(); } });

 try {
 const main = initNetwork(document.getElementById('agentNetwork')); nodesDS = main.dsN; edgesDS = main.dsE; network = main.net;
 } catch (e) { console.error('Wireflow init error:', e); }

 const modalEl = document.getElementById('wireflowModal');
 if (modalEl) {
 modalEl.addEventListener('shown.bs.modal', () => {
 if(!networkFull){
 const full = initNetwork(document.getElementById('agentNetworkFull')); nodesFull = full.dsN; edgesFull = full.dsE; networkFull = full.net;
 }
 renderWireflow();
 networkFull.fit({ animation: { duration: 200 } });
 });
 modalEl.addEventListener('hidden.bs.modal', () => { renderWireflow(); });
 }

 document.querySelectorAll('.agent-toggle').forEach(cb => {
 cb.addEventListener('change', () => {
 const agentId = cb.value;
 const detailsEl = document.getElementById('details_' + agentId);
 const cardEl = cb.closest('.agent-item');

 if (!detailsEl || !cardEl) return;

 const collapseInstance = bootstrap.Collapse.getOrCreateInstance(detailsEl);

 if (cb.checked) {
 cardEl.classList.add('is-selected');
 collapseInstance.show();
 } else {
 cardEl.classList.remove('is-selected');
 collapseInstance.hide();
 }

 const configStr = cb.dataset.config;
 if (configStr) {
 try {
