/* =========================================
 1. VARIABLES & RESET
 ========================================= */
 :root {
 /* Brand Colors (Indigo Theme) */
 --primary: #4f46e5; /* Indigo 600 */
 --primary-hover: #4338ca; /* Indigo 700 */
 --primary-soft: #eef2ff; /* Indigo 50 */

 /* Neutral Colors */
 --secondary: #64748b; /* Slate 500 */
 --text-main: #1e293b; /* Slate 800 */
 --text-muted: #64748b; /* Slate 500 */

 /* Backgrounds */
 --bg-body: #f8fafc; /* Slate 50 */
 --bg-sidebar: #ffffff;
 --border-color: #e2e8f0; /* Slate 200 */

 /* UI Elements */
 --card-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.05), 0 2px 4px -2px rgb(0 0 0 / 0.05);
 --card-shadow-hover: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.05);
 --radius-md: 12px;
 --radius-sm: 8px;
 --font-main: 'Inter', sans-serif;
}

* {
 box-sizing: border-box;
}

body {
 font-family: var(--font-main);
 background: var(--bg-body);
 color: var(--text-main);
 margin: 0;
 display: flex;
 min-height: 100vh;
 font-size: 15px;
 line-height: 1.6;
 overflow-x: hidden;
}

/* =========================================
 2. SIDEBAR
 ========================================= */
#sidebar {
 width: 280px;
 background: var(--bg-sidebar);
 border-right: 1px solid var(--border-color);
 position: fixed;
 top: 0;
 left: 0;
 height: 100vh;
 z-index: 1000;
 display: flex;
 flex-direction: column;
 transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Hidden state for mobile (default visible on desktop) */
#sidebar.active {
 transform: translateX(-100%);
}

.sidebar-header {
 padding: 24px 28px;
 border-bottom: 1px solid var(--border-color);
}

.sidebar-header h3 {
 margin: 0;
 font-size: 1.25rem;
 font-weight: 700;
 color: var(--text-main);
 letter-spacing: -0.025em;
 display: flex;
 align-items: center;
 gap: 8px;
}

.sidebar-header h3 i {
 color: var(--primary);
 font-size: 1.4rem;
}

.sidebar-header .brand-accent {
 color: var(--primary);
}

.sidebar-scroll {
 flex: 1;
 overflow-y: auto;
 padding: 24px 16px;
}

/* Scrollbar Styling */
.sidebar-scroll::-webkit-scrollbar {
 width: 6px;
}
.sidebar-scroll::-webkit-scrollbar-track {
 background: transparent;
}
.sidebar-scroll::-webkit-scrollbar-thumb {
 background-color: #cbd5e1;
 border-radius: 20px;
}

.category-header {
 font-size: 0.7rem;
 text-transform: uppercase;
 letter-spacing: 0.08em;
 color: var(--text-muted);
 font-weight: 700;
