 padding: 10px 12px;
 color: var(--text-muted);
 text-decoration: none;
 border-radius: var(--radius-sm);
 font-weight: 500;
 transition: all 0.2s ease;
 gap: 12px;
}

#sidebar ul li a:hover {
 background: #f8fafc;
 color: var(--text-main);
}

#sidebar ul li a.active {
 background: var(--primary-soft);
 color: var(--primary);
}

#sidebar ul li a i {
 font-size: 1.1em;
 opacity: 0.9;
}

.sidebar-footer {
 padding: 20px 28px;
 border-top: 1px solid var(--border-color);
 background: #fcfcfc;
}

.user-info {
 display: flex;
 align-items: center;
 gap: 12px;
}

.avatar {
