 font-size: 0.9rem;
 box-shadow: 0 2px 4px rgba(79, 70, 229, 0.2);
}

/* =========================================
 3. MAIN CONTENT & NAVBAR
 ========================================= */
#content {
 flex: 1;
 margin-left: 280px;
