 display: flex;
 flex-direction: column;
}

/* Full width when sidebar is hidden */
#content.active {
 margin-left: 0;
}

.navbar {
 background: rgba(255, 255, 255, 0.9);
 backdrop-filter: blur(10px);
 -webkit-backdrop-filter: blur(10px);
