 transform: translateY(-50%);
 color: #94a3b8;
 font-size: 1.1rem;
 pointer-events: none;
}

/* =========================================
 5. DASHBOARD CARDS (QUICK ACCESS)
 ========================================= */
.dashboard-card {
 background: white;
 border-radius: 16px;
 padding: 24px 20px;
 border: 1px solid var(--border-color);
 text-align: center;
 cursor: pointer;
 transition: all 0.2s ease;
 height: 100%;
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
}

.dashboard-card:hover {
 transform: translateY(-4px);
 box-shadow: var(--card-shadow-hover);
 border-color: var(--primary-soft);
}

.dashboard-card:active {
 transform: scale(0.98);
}

.icon-box {
 width: 56px;
 height: 56px;
 border-radius: 14px;
 display: flex;
 align-items: center;
 justify-content: center;
