 margin-bottom: 16px;
 transition: transform 0.2s;
}

.dashboard-card:hover .icon-box {
 transform: scale(1.1);
}

/* Dashboard Icon Colors */
.bg-blue-soft { background: #eff6ff; }
.bg-purple-soft { background: #f5f3ff; }
.text-purple { color: #7c3aed; }
.bg-green-soft { background: #f0fdf4; }
.bg-orange-soft { background: #fff7ed; }
.bg-pink-soft { background: #fdf2f8; }

.dashboard-card h5 {
 font-size: 1rem;
 font-weight: 600;
 margin: 0 0 4px 0;
 color: var(--text-main);
}

.dashboard-card p {
 font-size: 0.8rem;
 color: var(--text-muted);
 margin: 0;
}

/* =========================================
 6. API DOCUMENTATION CARDS
 ========================================= */
#api-container {
 padding: 32px 40px;
 max-width: 1200px;
 margin: 0 auto;
 width: 100%;
}

.api-card {
 background: white;
 border: 1px solid var(--border-color);
 border-radius: var(--radius-md);
 margin-bottom: 32px;
