}

.api-card:hover {
 box-shadow: var(--card-shadow-hover);
}

.api-header {
 padding: 24px;
 border-bottom: 1px solid #f1f5f9;
}

.api-header h5 {
 font-size: 1.15rem;
 margin-bottom: 8px;
 color: var(--text-main);
}

.api-meta {
 display: flex;
 align-items: center;
 gap: 12px;
 margin-top: 16px;
 flex-wrap: wrap;
}

.api-method {
 font-weight: 700;
 font-size: 0.75rem;
 padding: 4px 10px;
 border-radius: 6px;
 text-transform: uppercase;
 letter-spacing: 0.05em;
 min-width: 65px;
 text-align: center;
}

.method-post { background: #eff6ff; color: #2563eb; border: 1px solid #dbeafe; }
.method-get { background: #f0fdf4; color: #16a34a; border: 1px solid #dcfce7; }
.method-put { background: #fff7ed; color: #ea580c; border: 1px solid #ffedd5; }
.method-delete { background: #fef2f2; color: #dc2626; border: 1px solid #fee2e2; }

.api-endpoint {
 font-family: 'SF Mono', 'Roboto Mono', Menlo, monospace;
