 background: rgba(255,255,255,0.1);
 border: 1px solid rgba(255,255,255,0.1);
 color: #cbd5e1;
 font-size: 0.75rem;
 padding: 4px 12px;
 border-radius: 4px;
 cursor: pointer;
 transition: all 0.2s;
}
.copy-btn:hover {
 background: rgba(255,255,255,0.2);
