 box-shadow: 0 0 20px rgba(0,0,0,0.1);
 }

 /* Content & Navbar */
 #content { margin-left: 0; }
 .navbar { padding: 12px 16px; }

 /* Container Padding */
 #api-container { padding: 20px 16px; }

 /* Dashboard Grid Adjustments */
 .dashboard-card { padding: 16px; margin-bottom: 0; }
 .icon-box { width: 42px; height: 42px; font-size: 1.4rem; margin-bottom: 10px; }

 /* API Card adjustments */
 .api-card { border-radius: 12px; margin-bottom: 20px; }
 .api-header { padding: 16px; }
 .api-meta { gap: 8px; }

 .nav-tabs { padding: 0 16px; gap: 8px; }
 .nav-tabs .nav-link { font-size: 0.85rem; padding: 12px 8px; }
 .tab-content { padding: 16px; }

 /* Overlay for Mobile Sidebar */
 .overlay {
 position: fixed;
 top: 0; left: 0; right: 0; bottom: 0;
 background: rgba(0,0,0,0.5);
 z-index: 950;
 opacity: 0;
 pointer-events: none;
 transition: opacity 0.3s;
 }
 .overlay.active {
 opacity: 1;
 pointer-events: auto;
 }
}

