 if (yearSpan) yearSpan.textContent = new Date().getFullYear();

 // 3. Initialize Components
 setupSidebar();
 preloadAllAPIs();
 setupSearch();
 setupRippleEffect(); // Init Ripple Engine
});

/* =========================================
 UI & ANIMATIONS
 ========================================= */

function setupRippleEffect() {
 // Add ripple class to dashboard cards automatically
 document.querySelectorAll('.dashboard-card, #sidebar ul li a, .btn-brand').forEach(el => {
 el.classList.add('ripple-surface');
 });

 document.addEventListener('click', function(e) {
 const target = e.target.closest('.ripple-surface');
 if (!target) return;

 const ripple = document.createElement('span');
 const rect = target.getBoundingClientRect();
 const size = Math.max(rect.width, rect.height);
 const x = e.clientX - rect.left - size / 2;
 const y = e.clientY - rect.top - size / 2;

 ripple.style.width = ripple.style.height = `${size}px`;
 ripple.style.left = `${x}px`;
 ripple.style.top = `${y}px`;
 ripple.classList.add('ripple');

 // Remove existing ripples to keep DOM clean
 const existingRipple = target.querySelector('.ripple');
 if (existingRipple) existingRipple.remove();

 target.appendChild(ripple);

 // Remove after animation
 setTimeout(() => ripple.remove(), 600);
 });
}

function renderSkeletonLoader(container) {
 // Generates a shimmering skeleton UI
 let skeletonHTML = '';
 for(let i=0; i<3; i++) {
 skeletonHTML += `
 <div class="skeleton-loader">
 <div class="sk-header"></div>
 <div class="sk-line w-70"></div>
 <div class="sk-line w-100"></div>
 <div class="sk-line w-40"></div>
 </div>`;
 }
 container.innerHTML = `<div class="fade-in">${skeletonHTML}</div>`;
}

function setupSidebar() {
 const sidebar = document.getElementById('sidebar');
 const content = document.getElementById('content');
 const overlay = document.querySelector('.overlay');
 const triggers = [
 document.getElementById('sidebarCollapse'),
 document.getElementById('sidebarCollapseDesktop')
 ];

 function toggleSidebar() {
 sidebar.classList.toggle('active');
 content.classList.toggle('active');
 if (overlay) overlay.classList.toggle('active');
 }

 triggers.forEach(t => { if(t) t.addEventListener('click', toggleSidebar); });

 if (overlay) {
 overlay.addEventListener('click', () => {
 sidebar.classList.remove('active');
 content.classList.remove('active');
 overlay.classList.remove('active');
 });
 }
}

