async function preloadAllAPIs() {
 allAPIsCache = [];
 for (const [key, config] of Object.entries(apiConfig)) {
 try {
 const response = await fetch(config.file);
 const data = await response.json();
 const taggedData = data.map(item => ({ 
 ...item, 
 _categoryName: config.name, 
 _categoryId: key 
 }));
 allAPIsCache.push(...taggedData);
 } catch (e) { console.warn(`Skipping ${key}: ${e.message}`); }
 }
}

function setupSearch() {
 const searchInput = document.getElementById('apiSearch');
 const container = document.getElementById('api-container');
 const title = document.getElementById('current-section-title');

 if(!searchInput) return;

 searchInput.addEventListener('input', (e) => {
 const query = e.target.value.toLowerCase().trim();

 if (query.length === 0) {
 if(title) title.textContent = "Dashboard";
 container.innerHTML = dashboardHTML;
 return;
 }

 if(title) title.textContent = "Search Results";

 const results = allAPIsCache.filter(api => 
 (api.title && api.title.toLowerCase().includes(query)) ||
 (api.endpoint && api.endpoint.toLowerCase().includes(query)) ||
 (api.description && api.description.toLowerCase().includes(query))
 );

 renderAPIs(results);
 });
}

async function loadCategory(category, element) {
 const container = document.getElementById('api-container');
 const title = document.getElementById('current-section-title');
 const searchInput = document.getElementById('apiSearch');

 // Smooth scroll to top
 window.scrollTo({ top: 0, behavior: 'smooth' });

 if(searchInput) searchInput.value = '';

 // Update Sidebar State
 document.querySelectorAll('#sidebar ul li a').forEach(el => el.classList.remove('active'));
 if (element) element.classList.add('active');

 // Close Mobile Sidebar
 if (window.innerWidth <= 768) {
 document.getElementById('sidebar').classList.remove('active');
 document.querySelector('.overlay').classList.remove('active');
 }

 const current = apiConfig[category];
 if (!current) return;

 if(title) title.textContent = current.name;

 // Render Professional Skeleton Loader
 renderSkeletonLoader(container);

 // Artificial delay (300ms) to show off the smooth transition if data loads too fast
 const minDelay = new Promise(resolve => setTimeout(resolve, 300));

 try {
 const [response] = await Promise.all([fetch(current.file), minDelay]);
 if (!response.ok) throw new Error(`HTTP ${response.status}`);

 const apis = await response.json();
 const taggedAPIs = apis.map(api => ({ ...api, _categoryName: current.name }));

 renderAPIs(taggedAPIs);

 } catch (error) {
 container.innerHTML = `<div class="alert alert-danger">Error: ${error.message}</div>`;
 }
}

function renderAPIs(apis) {
 const container = document.getElementById('api-container');
 container.innerHTML = '';

 if (apis.length === 0) {
 container.innerHTML = `
 <div class="text-center mt-5 py-5 text-muted fade-in">
 <i class="ri-file-search-line" style="font-size: 3rem; opacity: 0.5;"></i>
 <h5 class="mt-3">No matching APIs found</h5>
 </div>`;
 return;
 }

 apis.forEach((api, index) => {
 const uniqueId = `api-${index}-${Date.now()}`;

 // Input Table Logic
 let inputRows = (api.inputs || []).map(i => `
 <tr>
 <td class="fw-bold text-dark" style="width: 35%">${i.Param}</td>
 <td style="width: 15%"><span class="badge ${i["M/O"] === 'M' ? 'bg-danger' : 'bg-secondary'}">${i["M/O"]}</span></td>
 <td class="text-muted small">${i.Description}</td>
 </tr>
 `).join('') || '<tr><td colspan="3" class="text-center text-muted fst-italic">No input parameters required.</td></tr>';

 // Calculate Stagger Delay (max 500ms to prevent long waits on huge lists)
 const delay = Math.min(index * 0.05, 0.5);

 const cardHtml = `
 <div class="api-card" style="animation-delay: ${delay}s">
 <div class="api-header">
 <div class="d-flex justify-content-between align-items-start mb-2">
 <div>
 ${api._categoryName ? `<span class="badge bg-light text-primary border mb-2">${api._categoryName}</span>` : ''}
 <h5 class="mb-1 fw-bold text-dark">${api.title}</h5>
 </div>
 </div>
 <p class="mb-3 text-muted small">${api.description}</p>
 <div class="api-meta">
 <span class="api-method ${getMethodClass(api.method)}">${api.method}</span>
 <span class="api-endpoint text-truncate">${api.endpoint}</span>
 </div>
 </div>

 <div class="api-body">
 <ul class="nav nav-tabs mb-0" role="tablist">
 <li class="nav-item"><button class="nav-link active ripple-surface" data-bs-toggle="tab" data-bs-target="#inputs-${uniqueId}">Inputs</button></li>
 <li class="nav-item"><button class="nav-link ripple-surface" data-bs-toggle="tab" data-bs-target="#curl-${uniqueId}">cURL</button></li>
 <li class="nav-item"><button class="nav-link ripple-surface" data-bs-toggle="tab" data-bs-target="#response-${uniqueId}">Response</button></li>
 </ul>
 <div class="tab-content">
 <div class="tab-pane fade show active" id="inputs-${uniqueId}">
 <div class="table-responsive border rounded bg-white">
 <table class="table table-hover mb-0"><thead class="table-light"><tr><th>Param</th><th>Type</th><th>Desc</th></tr></thead><tbody>${inputRows}</tbody></table>
 </div>
 </div>
 <div class="tab-pane fade" id="curl-${uniqueId}">
 <div class="code-block"><button class="copy-btn" onclick="copyCode(this)">Copy</button><code>${escapeHtml(api.curl)}</code></div>
 </div>
 <div class="tab-pane fade" id="response-${uniqueId}">
 ${generateResponseHtml(api.response)}
 </div>
 </div>
 </div>
 </div>`;
 container.insertAdjacentHTML('beforeend', cardHtml);
 });
}

/* =========================================
 HELPERS
 ========================================= */
function generateResponseHtml(res) {
 if (!res) return '<div class="p-3 text-muted">No data.</div>';
 if (res.headers || res.body) {
 return (res.headers ? `<div class="mb-3"><small class="text-uppercase fw-bold text-muted">Headers</small><div class="code-block"><button class="copy-btn" onclick="copyCode(this)">Copy</button><code>${JSON.stringify(res.headers,null,2)}</code></div></div>` : '') +
 (res.body ? `<div><small class="text-uppercase fw-bold text-muted">Body</small><div class="code-block"><button class="copy-btn" onclick="copyCode(this)">Copy</button><code>${JSON.stringify(res.body,null,2)}</code></div></div>` : '');
 }
 return `<div class="code-block"><button class="copy-btn" onclick="copyCode(this)">Copy</button><code>${JSON.stringify(res,null,2)}</code></div>`;
}

function getMethodClass(m) { return m==='POST'?'method-post':m==='GET'?'method-get':m==='PUT'?'method-put':'method-delete'; }
function escapeHtml(t) { return t ? t.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;") : ''; }

function copyCode(btn) {
 const codeBlock = btn.nextElementSibling;
 if (codeBlock) {
 navigator.clipboard.writeText(codeBlock.innerText).then(() => {
 const original = btn.innerText;
 btn.innerText = 'Copied!';
 btn.style.color = '#10b981';
 btn.style.borderColor = '#10b981';
 setTimeout(() => {
 btn.innerText = original;
 btn.style.color = '';
 btn.style.borderColor = '';
 }, 2000);
 });
 }
}

