// Global Configuration
const apiConfig = {
 'dkyc': { file: 'data/dkyc.json', name: 'Jukshio DKYC' },
 'defrauds': { file: 'data/defrauds.json', name: 'Defraud & Group' },
 'digilocker': { file: 'data/digilocker.json', name: 'DigiLocker Integration' },
 'verification': { file: 'data/verification.json', name: 'Verification APIs' },
 'retail': { file: 'data/retail.json', name: 'Smart Cart APIs' }
};

// Cache for Global Search
let allAPIsCache = [];

document.addEventListener('DOMContentLoaded', () => {
 // 1. Initialize Footer Year
 const yearSpan = document.getElementById('year');
 if (yearSpan) yearSpan.textContent = new Date().getFullYear();

 // 2. Sidebar Toggle Logic
 setupSidebar();

 // 3. Preload all APIs for Search
 preloadAllAPIs();

 // 4. Search Listener
 setupSearch();
});

function setupSidebar() {
 const sidebarCollapse = document.getElementById('sidebarCollapse');
 const sidebar = document.getElementById('sidebar');
 const content = document.getElementById('content');
 const overlay = document.querySelector('.overlay');

 function toggleSidebar() {
 sidebar.classList.toggle('active');
 content.classList.toggle('active');
 if (overlay) overlay.classList.toggle('active');
 }

 if (sidebarCollapse) sidebarCollapse.addEventListener('click', toggleSidebar);
 if (overlay) overlay.addEventListener('click', () => {
 sidebar.classList.remove('active');
 content.classList.remove('active');
 overlay.classList.remove('active');
 });
}

/**
 * Preloads all JSON files into a single array for search
 */
async function preloadAllAPIs() {
 allAPIsCache = [];
 for (const [key, config] of Object.entries(apiConfig)) {
 try {
 const response = await fetch(config.file);
 const data = await response.json();
 // Tag data with category info for search context
 const taggedData = data.map(item => ({
 ...item,
 _categoryName: config.name,
 _categoryId: key
 }));
 allAPIsCache.push(...taggedData);
 } catch (error) {
 console.error(`Error preloading ${key}:`, error);
 }
 }
}

/**
 * Handles Global Search Logic
 */
function setupSearch() {
 const searchInput = document.getElementById('apiSearch');
 const container = document.getElementById('api-container');
 const title = document.getElementById('current-section-title');

 searchInput.addEventListener('input', (e) => {
 const query = e.target.value.toLowerCase().trim();

 // Clear sidebar active state visually
 document.querySelectorAll('#sidebar ul li a').forEach(el => el.classList.remove('active'));

 if (query.length === 0) {
 title.textContent = "Welcome to Jukshio API Nexus";
 container.innerHTML = `
 <div class="text-center mt-5 text-muted">
 <div style="font-size: 4rem; color: #e2e8f0; margin-bottom: 20px;"><i class="ri-dashboard-3-line"></i></div>
 <h4>Search or Select a Category</h4>
 <p>Use the sidebar to browse or type above to search.</p>
 </div>`;
 return;
 }

 // Filter Logic
 const results = allAPIsCache.filter(api => 
 (api.title && api.title.toLowerCase().includes(query)) ||
 (api.endpoint && api.endpoint.toLowerCase().includes(query)) ||
 (api.description && api.description.toLowerCase().includes(query))
 );

 title.textContent = `Search Results (${results.length})`;
 renderAPIs(results);
 });
}

/**
 * Loads specific category from Sidebar
 */
async function loadCategory(category, element) {
 const container = document.getElementById('api-container');
 const title = document.getElementById('current-section-title');
 const searchInput = document.getElementById('apiSearch');

 // Reset search input
 searchInput.value = '';

 // Update Sidebar Active State
 if (element) {
 document.querySelectorAll('#sidebar ul li a').forEach(el => el.classList.remove('active'));
 element.classList.add('active');
 }

 const current = apiConfig[category];
 if (!current) return;

 title.textContent = current.name;
 container.innerHTML = `
 <div class="text-center mt-5">
 <div class="spinner-border text-primary" role="status"></div>
 <p class="text-muted mt-2">Loading...</p>
 </div>`;

 try {
 const response = await fetch(current.file);
 if (!response.ok) throw new Error(`HTTP ${response.status}`);
 const apis = await response.json();
 // Add category tag even for single loads to keep render logic consistent
 const taggedAPIs = apis.map(api => ({ ...api, _categoryName: current.name }));
 renderAPIs(taggedAPIs);
 } catch (error) {
 console.error("Fetch Error:", error);
 container.innerHTML = `
 <div class="alert alert-danger mx-auto mt-4">
 <strong>Error loading data:</strong> ${error.message}
 </div>`;
 }
}

/**
 * Renders API Cards
 */
function renderAPIs(apis) {
 const container = document.getElementById('api-container');
 container.innerHTML = '';

 if (apis.length === 0) {
 container.innerHTML = `
 <div class="text-center mt-5 text-muted">
 <i class="ri-file-search-line" style="font-size: 3rem; opacity: 0.5;"></i>
 <h5 class="mt-3">No matching APIs found</h5>
 <p>Try searching for a different endpoint or keyword.</p>
 </div>`;
 return;
 }

 apis.forEach((api, index) => {
 const uniqueId = `api-${index}-${Date.now()}`;

 // 1. Inputs Table
 let inputRows = '';
 if (api.inputs && api.inputs.length > 0) {
 inputRows = api.inputs.map(input => `
 <tr>
 <td class="fw-bold text-dark" style="width: 30%">${input.Param}</td>
 <td style="width: 10%"><span class="badge ${input["M/O"] === 'M' ? 'bg-danger' : 'bg-secondary'}">${input["M/O"]}</span></td>
 <td class="text-muted small">${input.Description}</td>
 </tr>
 `).join('');
 } else {
 inputRows = '<tr><td colspan="3" class="text-center text-muted fst-italic">No input parameters required.</td></tr>';
 }

 // 2. Response Block
 let responseHtml = generateResponseHtml(api.response);

 // 3. HTML Card
 const cardHtml = `
 <div class="api-card">
 <div class="api-header">
 <div class="d-flex justify-content-between align-items-start mb-2">
 <div>
 ${api._categoryName ? `<span class="category-badge mb-2 d-inline-block">${api._categoryName}</span>` : ''}
 <h5 class="mb-1 fw-bold text-dark">${api.title}</h5>
 </div>
 <span class="badge bg-light text-muted border">ID: ${api.id || index + 1}</span>
 </div>
 <p class="mb-3 text-muted small">${api.description}</p>
 <div class="api-meta">
 <span class="api-method ${getMethodClass(api.method)}">${api.method}</span>
 <span class="api-endpoint text-truncate">${api.endpoint}</span>
 </div>
 </div>

 <div class="api-body">
 <ul class="nav nav-tabs mb-0" role="tablist">
 <li class="nav-item">
 <button class="nav-link active" data-bs-toggle="tab" data-bs-target="#inputs-${uniqueId}">
 <i class="ri-input-method-line me-1"></i> Inputs
 </button>
 </li>
 <li class="nav-item">
 <button class="nav-link" data-bs-toggle="tab" data-bs-target="#curl-${uniqueId}">
 <i class="ri-terminal-box-line me-1"></i> cURL
 </button>
 </li>
 <li class="nav-item">
 <button class="nav-link" data-bs-toggle="tab" data-bs-target="#response-${uniqueId}">
 <i class="ri-arrow-up-down-line me-1"></i> Response
 </button>
 </li>
 </ul>

 <div class="tab-content">
 <div class="tab-pane fade show active" id="inputs-${uniqueId}">
 <div class="table-responsive border rounded bg-white">
 <table class="table table-hover align-middle mb-0">
 <thead class="table-light">
 <tr><th>Parameter</th><th>Type</th><th>Description</th></tr>
 </thead>
 <tbody>${inputRows}</tbody>
 </table>
 </div>
 </div>
 <div class="tab-pane fade" id="curl-${uniqueId}">
 <div class="code-block">
 <button class="copy-btn" onclick="copyCode(this)">Copy</button>
 <code>${escapeHtml(api.curl)}</code>
 </div>
 </div>
 <div class="tab-pane fade" id="response-${uniqueId}">
 ${responseHtml}
 </div>
 </div>
 </div>
 </div>`;

 container.insertAdjacentHTML('beforeend', cardHtml);
 });
}

/** Helper: Generate Response HTML based on structure */
function generateResponseHtml(response) {
 if (!response) return '<div class="p-3 text-muted">No response data available.</div>';

 if (response.headers || response.body) {
 let html = '';
 if (response.headers) {
 html += `
 <div class="mb-3">
 <small class="text-uppercase fw-bold text-muted d-block mb-1" style="font-size: 0.7rem;">Response Headers</small>
 <div class="code-block" style="max-height: 200px;">
 <button class="copy-btn" onclick="copyCode(this)">Copy</button>
 <code>${JSON.stringify(response.headers, null, 2)}</code>
 </div>
 </div>`;
 }
 if (response.body) {
 html += `
 <div>
 <small class="text-uppercase fw-bold text-muted d-block mb-1" style="font-size: 0.7rem;">Response Body</small>
 <div class="code-block">
 <button class="copy-btn" onclick="copyCode(this)">Copy</button>
 <code>${JSON.stringify(response.body, null, 2)}</code>
 </div>
 </div>`;
 }
 return html;
 }

 // Flat response
 return `
 <div class="code-block">
 <button class="copy-btn" onclick="copyCode(this)">Copy</button>
 <code>${JSON.stringify(response, null, 2)}</code>
 </div>`;
}

/** Helper: Get CSS class for method */
function getMethodClass(method) {
 if (!method) return 'method-get';
 const m = method.toUpperCase();
 if (m === 'POST') return 'method-post';
 if (m === 'PUT') return 'method-put';
 if (m === 'DELETE') return 'method-delete';
 return 'method-get';
}

function escapeHtml(text) {
 if (!text) return '';
 return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function copyCode(btn) {
 const codeBlock = btn.nextElementSibling;
 if (codeBlock) {
 navigator.clipboard.writeText(codeBlock.innerText).then(() => {
 const original = btn.innerText;
 btn.innerText = 'Copied!';
 btn.style.color = '#10b981';
 setTimeout(() => {
 btn.innerText = original;
 btn.style.color = '';
 }, 2000);
 });
 }
}

