async function sendMessage() {
 const input = document.getElementById('userInput');
 const message = input.value.trim();

 // Find all checked agent checkboxes
 const selectedCheckboxes = document.querySelectorAll('.agent-checkbox:checked');

 if (!message) return;
 if (selectedCheckboxes.length === 0) {
 alert('Please select at least one agent first');
 return;
 }

 // Get the ID from each checked box and join them with a comma
 const agentIds = Array.from(selectedCheckboxes).map(cb => cb.value).join(',');

 // Disable input and button while processing
 input.disabled = true;
 document.getElementById('sendButton').disabled = true;
 document.querySelectorAll('.agent-checkbox').forEach(cb => cb.disabled = true);

 try {
 // Add user message to chat
 addMessage(message, true);
 input.value = '';

 console.log('Sending request:', {
 query: message,
 agent: agentIds, // Pass the comma-separated string
 session_id: sessionId
 });

 const response = await fetch('/ask', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json'
 },
 body: JSON.stringify({
 query: message,
 agent: agentIds,
 session_id: sessionId || null
 })
 });

 if (!response.ok) {
 const errorData = await response.json();
 console.error('Server response:', errorData);
 throw new Error(errorData.detail || 'Failed to get response from agent');
 }

 const data = await response.json();
 console.log('Server response:', data);

 if (!sessionId) {
 sessionId = data.session_id;
 }

 // Add agent response to chat
 let responseText = data.result;
 if (typeof responseText === 'object') {
 responseText = JSON.stringify(responseText, null, 2);
 }
 addMessage(responseText);

 } catch (error) {
 console.error('Error:', error);
 addMessage(`Error: ${error.message}`);
 } finally {
 // Re-enable input and button
 input.disabled = false;
 document.getElementById('sendButton').disabled = false;
 document.querySelectorAll('.agent-checkbox').forEach(cb => cb.disabled = false);
 input.focus();
 }
}

