# modalities/synthetic_audio/pipeline.py
import yaml
import json
import io
import random
import logging
from tqdm import tqdm
from pydub import AudioSegment
import openai

# Get the same logger used by FastAPI
logger = logging.getLogger("uvicorn")

def generate_data(client, model_config, use_case_config, existing_attributes):
 """Generates a single, unique JSON data point for a dialogue."""
 prompts = use_case_config['prompts']
 user_prompt = prompts['user_template'].format(
 existing_attributes=json.dumps(existing_attributes),
 context=use_case_config['context'],
 schema_hint=json.dumps(use_case_config['schema'])
 )
 try:
 response = client.chat.completions.create(
 model=model_config['generation_model'],
 messages=[{"role": "system", "content": prompts['system']}, {"role": "user", "content": user_prompt}],
 response_format={"type": "json_object"},
 temperature=model_config.get('temperature', 0.8),
 max_tokens=model_config.get('max_tokens', 2048),
 )
 return json.loads(response.choices[0].message.content)
 except Exception as e:
 logger.warning(f"Warning: Failed to generate data. Error: {e}.")
 return None

def synthesize_dialogue_segment(client, tts_model, dialogue, audio_settings):
 """Synthesizes a single dialogue into an AudioSegment object."""
 full_audio = AudioSegment.empty()
 pause_segment = AudioSegment.silent(duration=audio_settings.get('pause_between_speakers_ms', 500))

 active_voice_cast = {
 speaker: random.choice(options) if isinstance(options, list) else options
 for speaker, options in audio_settings['voice_mapping'].items()
 }
 logger.info(f" - Voice Cast for this dialogue: {active_voice_cast}")

 for turn in dialogue:
 speaker, line = turn.get("speaker"), turn.get("line")
 if not all([speaker, line]): continue
 voice = active_voice_cast.get(speaker)
 if not voice:
 logger.warning(f" - No voice found for speaker '{speaker}'. Skipping line.")
 continue

 try:
 logger.info(f" - Synthesizing for {speaker}...")
 response = client.audio.speech.create(model=tts_model, voice=voice, input=line, response_format="mp3")
 turn_audio = AudioSegment.from_file(io.BytesIO(response.content), format="mp3")
 full_audio += turn_audio + pause_segment
 except Exception as e:
 logger.warning(f" - Warning: Failed to synthesize audio for a line. Error: {e}")
 continue

 return full_audio if len(full_audio) > 0 else None

def run_synthesis_pipeline(config: dict):
 """
 Main orchestrator that generates multiple dialogues, synthesizes them,
 and returns a single combined audio file's bytes.
 """
 job_def = config['job']
 use_case_config = job_def['use_case']
 openai_config = config['openai']

 client = openai.OpenAI(api_key=openai_config['api_key'])

 diversity_keys = use_case_config.get('diversity_check_keys', [])
 attributes_to_avoid = []

 final_stitched_audio = AudioSegment.empty()
 count = job_def.get('count', 1)

 logger.info(f"Starting pipeline to generate {count} dialogues...")
 for i in tqdm(range(count), desc="Generating Dialogues"):
 generated_data = generate_data(client, openai_config, use_case_config, attributes_to_avoid)
 if generated_data is None: continue

 # --- NEW LOGGING: Inspect the data from the LLM ---
 logger.info(f"Generated data from LLM: {json.dumps(generated_data, indent=2)}")

 dialogue_script = generated_data.get("dialogue", [])
 if not dialogue_script:
 logger.warning("No 'dialogue' key found in generated data or dialogue is empty. Skipping audio synthesis for this item.")
 continue

 audio_segment = synthesize_dialogue_segment(
 client, openai_config['tts_model'], dialogue_script, use_case_config['audio_settings']
 )
 if audio_segment is None:
 logger.warning("Synthesize function returned no audio. Skipping this segment.")
 continue

 final_stitched_audio += audio_segment

 if diversity_keys:
 current_attrs = generated_data.get('attributes', {})
 avoid_dict = {key: current_attrs.get(key) for key in diversity_keys if key in current_attrs}
 if avoid_dict:
 attributes_to_avoid.append(avoid_dict)

 if len(final_stitched_audio) == 0:
 raise ValueError("Audio generation failed. No audio was produced.")

 noise_config = use_case_config.get('audio_settings', {}).get('background_noise')
 if noise_config and noise_config.get('file'):
 try:
 background_track = AudioSegment.from_file(noise_config['file']) + noise_config.get('volume_db', -20)
 final_stitched_audio = final_stitched_audio.overlay(background_track, loop=True)
 logger.info("Mixed final audio with background noise.")
 except Exception as e:
 logger.warning(f"Warning: Could not process background noise. Error: {e}.")

 final_audio_io = io.BytesIO()
 final_stitched_audio.export(final_audio_io, format="mp3")
 final_audio_io.seek(0)

 logger.info("Pipeline complete. Returning final audio bytes.")
 return final_audio_io.getvalue()

