# in_memory_db_impl.py

from in_memory_db import InMemoryDB

class InMemoryDBImpl(InMemoryDB):

 def __init__(self):
 self.data = {} # Stores records: {key: {field: {value: int, ttl: int, start_time: int}}}

 def set(self, timestamp: int, key: str, field: str, value: int) -> None:
 if key not in self.data:
 self.data[key] = {}
 self.data[key][field] = {"value": value, "ttl": float('inf'), "start_time": 0}

 def compare_and_set(self, timestamp: int, key: str, field: str, expected_value: int, new_value: int) -> bool:
 if key in self.data and field in self.data[key] and self.data[key][field]["value"] == expected_value:
 self.data[key][field]["value"] = new_value
 return True
 return False

 def compare_and_delete(self, timestamp: int, key: str, field: str, expected_value: int) -> bool:
 if key in self.data and field in self.data[key] and self.data[key][field]["value"] == expected_value:
 del self.data[key][field]
 return True
 return False

 def get(self, timestamp: int, key: str, field: str) -> int | None:
 if key in self.data and field in self.data[key]:
 field_data = self.data[key][field]
 if timestamp < field_data["start_time"] + field_data["ttl"]:
 return field_data["value"]
 return None

 def scan(self, timestamp: int, key: str) -> list[str]:
 if key not in self.data:
 return []

 record = self.data[key]
 fields = sorted(record.keys())
 result = []
 for field in fields:
 field_data = record[field]
 if timestamp < field_data["start_time"] + field_data["ttl"]:
 result.append(f"{field}({field_data['value']})")
 return result

 def scan_by_prefix(self, timestamp: int, key: str, prefix: str) -> list[str]:
 if key not in self.data:
 return []

 record = self.data[key]
 filtered_fields = sorted([field for field in record.keys() if field.startswith(prefix)])
 result = []
 for field in filtered_fields:
 field_data = record[field]
 if timestamp < field_data["start_time"] + field_data["ttl"]:
 result.append(f"{field}({field_data['value']})")
 return result

 def set_with_ttl(self, timestamp: int, key: str, field: str, value: int, ttl: int) -> None:
 if key not in self.data:
 self.data[key] = {}
 self.data[key][field] = {"value": value, "ttl": ttl, "start_time": timestamp}

 def compare_and_set_with_ttl(self, timestamp: int, key: str, field: str, expected_value: int, new_value: int, ttl: int) -> bool:
 if key in self.data and field in self.data[key] and self.data[key][field]["value"] == expected_value:
 self.data[key][field] = {"value": new_value, "ttl": ttl, "start_time": timestamp}
 return True
 return False

 Reasoning for the fix: 

 The original code was mostly correct in terms of implementing the logic for TTL and the new methods. However, the issue was with how the get , scan , and scan_by_prefix methods were handling the return values. 

 The problem: 

 The get , scan , and scan_by_prefix methods were returning the entire dictionary {"value": value, "ttl": ttl, "start_time": timestamp} instead of just the value as expected by the tests. 

 The solution: 

 The solution is to modify these methods to return only the value from the dictionary when a field is found and its TTL is still valid. 

 Changes made: 

 In the get method, the return statement was changed from return field_data to return field_data["value"] . 

 In the scan and scan_by_prefix methods, the string formatting was changed from f"{field}({field_data})" to f"{field}({field_data['value']})" . 

 These changes ensure that the methods return only the value as required by the tests, resolving the failing test cases.

