The issue you're seeing where the error is empty ( "error": "" ) happens because httpx might be throwing a silent exception during the file stream or the response isn't coming back as JSON. Also, the previous call_api was a bit too generic for complex multipart forms. 

 Here is the fixed server.py . I have improved the Multipart/Form-Data handling to exactly match how curl --form works and added better error logging so you can see exactly what the API is complaining about. 

 Updated server.py 

 import os
import yaml
import httpx
import logging
from mcp.server.fastmcp import FastMCP
from pydantic import create_model

# Setup logging to see what's happening in your terminal
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("DynamoServer")

mcp = FastMCP("DynamoAudioServer")

async def call_api(url, method, payload, config):
 async with httpx.AsyncClient(timeout=60.0) as client: # Increased timeout for audio processing
 files = {}
 data = {}

 params_cfg = config.get('parameters', {})

 # Sort payload into 'files' and 'data' based on YAML 'type: file'
 for key, value in payload.items():
 if params_cfg.get(key, {}).get('type') == 'file':
 # Remove quotes if the path was wrapped in them
 clean_path = str(value).strip('"').strip("'")
 if os.path.exists(clean_path):
 # We open in binary mode 'rb'
 files[key] = (os.path.basename(clean_path), open(clean_path, 'rb'))
 logger.info(f"📂 Attaching file: {clean_path}")
 else:
 return {"error": f"File not found at: {clean_path}"}
 else:
 # Ensure data is sent as string for form-data, similar to curl
 data[key] = str(value)

 try:
 if method.upper() == "POST":
 if files:
 # 'files' + 'data' automatically triggers multipart/form-data in httpx
 resp = await client.post(url, data=data, files=files)
 else:
 resp = await client.post(url, json=data)
 else:
 resp = await client.get(url, params=data)

 # Close files immediately after request
 for _, f_tuple in files.items():
 f_tuple[1].close()

 # Try to get JSON, otherwise return the raw text for debugging
 try:
 return resp.json()
 except:
 return {"status": resp.status_code, "raw_response": resp.text}

 except Exception as e:
 logger.error(f"❌ Request failed: {str(e)}")
 return {"error": "Connection Failed", "details": str(e)}

def load_tools():
 print("\n--- 🔎 REGISTERING TOOLS ---")
 tools_dir = "./tools"

 if not os.path.exists(tools_dir):
 os.makedirs(tools_dir)
 return

 for filename in os.listdir(tools_dir):
 if filename.endswith(".yaml"):
 with open(os.path.join(tools_dir, filename)) as f:
 cfg = yaml.safe_load(f)

 # Create the dynamic Pydantic model for the UI
 field_definitions = {}
 for p_name, p_info in cfg.get('parameters', {}).items():
 # For simplicity, we treat all inputs as strings in the UI 
 # and handle conversion in call_api
 field_definitions[p_name] = (str, p_info.get('default', ...))

 ToolModel = create_model(f"{cfg['name']}Model", **field_definitions)

 # Register the tool
 # We use a default argument 'cfg=cfg' to bind the config to the function
 @mcp.tool(name=cfg['name'])
 async def dynamic_tool(args: ToolModel, cfg=cfg):
 # .model_dump() is the Pydantic v2 way to get the dict
 return await call_api(cfg['endpoint'], cfg['method'], args.model_dump(), cfg)

 dynamic_tool.__doc__ = cfg['description']
 print(f"✅ Registered: {cfg['name']}")
 print("----------------------------\n")

load_tools()

if __name__ == "__main__":
 mcp.run()

